(window.GIM_TP=window.GIM_TP||{})["Z.Bamidbar.0"]={"from":0,"a":[[["(במדבר א׳:א׳) וַיְדַבֵּר יְיָ אֶל מֹשֶׁה בְּמִדְבַּר סִינַי בְּאֹהֶל מוֹעֵד וְגוֹ', רִבִּי אַבָּא פָּתַח, (בראשית א׳:כ״ז) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ וְגוֹ', הַאי קְרָא אִתְּמַר. תָּא חֲזֵי, בְּשַׁעֲתָא דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם עָבֵד לֵיהּ בְּדִיּוּקְנָא דְּעִלָּאֵי וְתַתָּאֵי, וַהֲוָה כָּלִיל מִכֹּלָּא, וַהֲוָה נְהוֹרֵיהּ נָהִיר, מִסַּיְיפֵי עָלְמָא עַד סַיְיפֵי עָלְמָא. וַהֲווּ דַּחֲלִין קַמֵּיהּ כֹּלָּא.","וְאַף עַל גַּב דְּהָא אוּקְמוּהָ, אִית לְאִסְתַּכְּלָא בֵּיהּ בְּהַאי קְרָא, וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים בָּרָא אוֹתוֹ, כֵּיוָן דְּאָמַר בְּצַלְמוֹ, מַאי בְּצֶלֶם אֱלֹהִים בָּרָא אוֹתוֹ. אֶלָּא וַדַּאי תְּרֵין דַּרְגִּין דִּכְלִילָן דְּכַר וְנוּקְבָּא, חַד לִדְכַר, וְחַד לְנוּקְבָּא.","וּבְגִין כַּךְ דּוּ פַּרְצוּפִין הֲווֹ ודַּאי, וְסֵיפָא דִּקְרָא אוֹכַח, דִּכְתִּיב זָכָר וּנְקֵבָה בָּרָא אוֹתָם. וְכָלִיל הֲוָה מִכָּל סִטְרִין (נ\"א מתרין סטרין) וְאַף עַל גַּב דְּנוּקְבָּא אֲחִידַת בְּסִטְרוֹי. הָא הִיא נָמֵי כְּלִילָא מִתְּרֵין סִטְרִין, לְמֶהֱוִי שְׁלִים בְּכֹלָּא.","וַהֲוָה מִסְתָּכַּל בְּחָכְמְתָא, לְעֵילָּא וְתַתָּא. כֵּיוָן דְּסָּרַח, אִתְמַעֲטוּ פַּרְצוּפִין, וְחָכְמְּתָא אִסְתָּלָקַת מִנֵּיהּ, וְלָא הֲוָה מִסְתָּכַל אֶלָּא בְּמִלֵי דְּגוּפֵיהּ. לְבָתַר אוֹלִיד בְּנִין מֵעִלָּאֵי וְתַתָּאֵי, וְלָא אִתְיָשָׁבוּ דָּא וְדָא בְּעָלְמָא, עַד דְּאוֹלִיד בַּר, וּמִנֵּיהּ אִשְׁתְּלִים (ס\"א אשתיל) עָלְמָא, דְּאִקְרֵי שֵׁת, וְהָא אוּקְמוּהָ.","וְעִם כָּל דָּא, עָלְמָא תַּתָּאָה לָא אִשְׁתְּלִים, וְלָא הֲוָה שְׁלִים, וְלָא אִשְׁתְּכַח בְּקִיּוּמֵיהּ, עַד דְּאָתָא אַבְרָהָם, וְאִתְקַיָּים עָלְמָא. אֲבָל לָא אִשְׁתְּלִים, עַד דְּאַבְרָהָם אִשְׁתְּכַח בֵּיהּ בְּעָלְמָא וְאָחִיד בֵּיהּ בִּימִינָא, כְּמַאן דְּאָחִיד בִּימִינֵיהּ, לְמַאן דְּנָפִיל. אָתָא יִצְחָק, וְאָחִיד בִּידֵיהּ דְּעָלְמָא בִּשְׂמָאלָא, וְאִתְקָיָּים יַתִּיר. כֵּיוָן דְּאָתָא יַעֲקֹב, אָחִיד בְּאֶמְצָעִיתָא בְּגוּפָא, וְאִתְכְּלִיל בִּתְרֵין סִטְרִין, אִתְקַיָּים עָלְמָא וְלָא הֲוָה מִתְמוֹטֵט.","וְעִם כָּל דָּא לָא אַשְׁתִּיל (ס\"א אשתלים) בְּשָׁרְשׁוֹי, עַד דְּאוֹלִיד תְּרֵיסָר שְׁבָטִין, וְשִׁבְעִין נַפְשָׁאן, וְאַשְׁתִּיל (ס\"א ואשתלים) עָלְמָא. וְעִם כָּל דָּא לָא אִשְׁתְּלִים, עַד דְּקַבִּילוּ יִשְׂרָאֵל אוֹרַיְיתָא בְּטוּרָא דְּסִינַי, וְאִתְּקַם מַשְׁכְּנָא. כְּדֵין אִתְקָיָּימוּ עָלְמִין וְאִשְׁתְּלִימוּ, וְאִתְבְּסָמוּ עִלָּאִין וְתַתָּאִין."],[[0,"וידבר ה' אל","וגו': וידבר ה' אל משה במדבר סיני באהל מועד וגו'. ר' אבא פתח, ויברא אלקים את האדם בצלמו וגו'. מקרא זה למדנו. בוא וראה, בשעה שהקב\"ה ברא את האדם עשה אותו בצורת העליונים והתחתונים, והיה כלול מכולם, והיה אורו מאיר מסוף העולם עד סוף העולם, והכל היו יראים מפניו."],[1,"ואע\"ג דהא אוקמוה","וכו': ואע\"פ שהעמידוהו, יש להסתכל בו במקרא הזה, ויברא אלקים את האדם בצלמו בצלם אלקים ברא אותו. כיון שאמר בצלמו, מהו עוד בצלם אלקים ברא אותו. ומשיב, אלא ודאי שתי מדרגות והיו באדם שהיה כלול מזכר ונקבה לכן, אחד לזכר, דהיינו ויברא וגו'. ואחד לנקבה, דהיינו בצלם וגו'."],[2,"ובגין כך דו פרצופין","וכו': ומשום זה ב' פרצופין היו ודאי, זכר ונקבה, וסוף המקרא מוכח, שכתוב, זכר ונקבה ברא אותם. וכלול היה מב' צדדים. ואע\"פ שהנקבה היתה נאחזת בצדו, הרי היא בפני עצמה היתה כלולה ג\"כ מב' צדדים, שהם חסד ודין, להיות שלם בכל."],[3,"והוה מסתכל בחכמתא","וכו': והיה מסתכל בחכמה למעלה ולמטה. כיון שחטא, נתמעטו הפרצופין, והחכמה נסתלקה ממנו,ולא היה מסתכל אלא בדברי הגוף שלו. ואח\"כ הוליד בנים מעליונים ותחתונים, דהיינו הבל מעליונים, וקין מתחתונים, ולא נתיישבו זה וזה בעולם, שלא נשאר מהם זרע בעולם, עד שהוליד בן, דהיינו שת, וממנו נשתל העולם. והעמידוהו."],[4,"ועכ\"ד עלמא תתאה","וכו': ועכ\"ז עולם התחתון לא נשלם ולא היה שלם, ולא נמצא בקיומו, עד שבא אברהם ונתקיים העולם אבל לא נשלם. עד שאברהם נמצא בעולם ואחז בו, בעולם, בימין שהוא חסד, כמי שאוחז בימינו של מי שנפל. בא יצחק, ואחז בידו של העולם בשמאל, דהיינו בגבורה, ונתקיים העולם יותר. כיון שבא יעקב אחז באמצע, בגוף, שהוא קו האמצעי ונכלל בב' הצדדים, בימין ובשמאל. ונתקיים העולם ולא היה מתמוטט."],[5,"ועם כל דא לא","וכו': ועכ\"ז, לא נשתל העולם בשרשיו, עד שיעקב הוליד י\"ב שבטים וע' נפש, ונשתל העולם. ועכ\"ז לא נשלם עד שקבלו ישראל התורה והוקם המשכן. אז נתקיימו העולמות ונשלמו, ונתבשמו העליונים והתחתונים."]],[[0,"","וַיְדַבֵּר ה' אֶל מֹשֶׁה בְּמִדְבַּר סִינַי בְּאֹהֶל מוֹעֵד וְגוֹ'. רַבִּי אַבָּא פָּתַח, (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ וְגוֹ'. הַפָּסוּק הַזֶּה נִתְבָּאֵר. בֹּא רְאֵה, בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ-בָּרוּךְ-הוּא אֶת הָאָדָם, עָשָׂה אוֹתוֹ בִּדְמוּת שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים, וְהָיָה כָּלוּל מֵהַכֹּל, וְהָיָה אוֹרוֹ מֵאִיר מִסּוֹף הָעוֹלָם וְעַד סוֹפוֹ, וְהָיוּ פוֹחֲדִים מִמֶּנּוּ הַכֹּל."],[1,"","וְאַף עַל גַּב שֶׁהֲרֵי פֵּרְשׁוּהָ, יֵשׁ לְהִסְתַּכֵּל בַּפָּסוּק הַזֶּה. וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ, כֵּיוָן שֶׁאָמַר בְּצַלְמוֹ, מַה זֶּה בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ? אֶלָּא וַדַּאי שְׁתֵּי דְרָגוֹת שֶׁכְּלוּלוֹת זָכָר וּנְקֵבָה, אַחַת לְזָכָר וְאַחַת לִנְקֵבָה."],[2,"","וְלָכֵן שְׁנֵי פַרְצוּפִים הָיוּ בְּוַדַּאי, וְסוֹף הַפָּסוּק מוֹכִיחַ, שֶׁכָּתוּב זָכָר וּנְקֵבָה בָּרָא אֹתָם. וְכָלוּל הָיָה מִכָּל הַצְּדָדִים (משני צדדים). וְאַף עַל גַּב שֶׁהַנְּקֵבָה אֲחוּזָה בְּצִדּוֹ, הֲרֵי הִיא גַּם כְּלוּלָה מִשְּׁנֵי צְדָדִים, לִהְיוֹת שָׁלֵם בַּכֹּל."],[3,"","וְהָיָה מִסְתַּכֵּל בַּחָכְמָה לְמַעְלָה וּלְמַטָּה. כֵּיוָן שֶׁסָּרַח, הִתְמַעֲטוּ הַפַּרְצוּפִים, וְהַחָכְמָה הִסְתַּלְּקָה מִמֶּנּוּ, וְלֹא הָיָה מִסְתַּכֵּל אֶלָּא בְּדִבְרֵי גוּפוֹ. אַחַר כָּךְ הוֹלִיד בָּנִים מֵעֶלְיוֹנִים וְתַחְתּוֹנִים, וְלֹא הִתְיַשְּׁבוּ זֶה וָזֶה בָּעוֹלָם עַד שֶׁהוֹלִיד בֵּן, וּמִמֶּנּוּ נִשְׁלַם (נשתל) הָעוֹלָם, שֶׁנִּקְרָא שֵׁת, וְכָךְ פֵּרְשׁוּהָ."],[4,"","וְעִם כָּל זֶה, הָעוֹלָם הַתַּחְתּוֹן לֹא הֻשְׁלַם וְלֹא הָיָה שָׁלֵם וְלֹא נִמְצָא בְקִיּוּמוֹ, עַד שֶׁבָּא אַבְרָהָם וְעָמַד הָעוֹלָם. אֲבָל לֹא הֻשְׁלַם עַד שֶׁאַבְרָהָם נִמְצָא בּוֹ בָּעוֹלָם, וְאָחַז בּוֹ בְּיָמִין כְּמִי שֶׁאוֹחֵז בִּימִינוֹ אֶת מִי שֶׁנּוֹפֵל. בָּא יִצְחָק וְאָחַז בִּידֵי הָעוֹלָם בִּשְׂמֹאל וְהִתְקַיֵּם יוֹתֵר. כֵּיוָן שֶׁבָּא יַעֲקֹב, אָחַז בְּאֶמְצַע הַגּוּף, וְנִכְלָל בִּשְׁנֵי צְדָדִים, עָמַד הָעוֹלָם וְלֹא הָיָה מִתְמוֹטֵט."],[5,"","וְעִם כָּל זֶה לֹא נִשְׁתַּל (נשלם) בְּשָׁרָשָׁיו עַד שֶׁהוֹלִיד שְׁנֵים עָשָׂר שְׁבָטִים וְשִׁבְעִים נֶפֶשׁ, וְנִשְׁתַּל (ונשלם) הָעוֹלָם. וְעִם כָּל זֶה לֹא הִשְׁתַּלֵּם עַד שֶׁקִּבְּלוּ יִשְׂרָאֵל תּוֹרָה בְּהַר סִינַי וְהוּקַם הַמִּשְׁכָּן, וְאָז עָמְדוּ הָעוֹלָמוֹת וְנִשְׁלְמוּ, וְהִתְבַּשְּׂמוּ עֶלְיוֹנִים וְתַחְתּוֹנִים."]]],[["כֵּיוָן דְּאוֹרַיְיתָא וּמַשְׁכְּנָא אִתּוֹקָמוּ, בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִפְקַד חֵילוֹי דְּאוֹרַיְיתָא, כַּמָה חַיָּילִין אִינּוּן דְּאוֹרַיְיתָא, כַּמָה חַיָּילִין אִינּוּן דְּמַשְׁכְּנָא. תָּא חֲזֵי, כָּל מִלָּה דְּבָעֵי לְאִתְיַישְּׁבָא בְּדוּכְתֵּיהּ, לָא מִתְיַישְּׁבָא עַד דְּאִדְכַּר בְּפוּמָא, וְאִתְמְנֵי עָלָהּ. אוּף הָכָא, בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִפְקַד חַיָּילִין דְּאוֹרַיְיתָא, וְחַיָּילִין דְּמַשְׁכְּנָא, וְכֻלְּהוּ הֲווֹ כְּחַד וְלָא מִתְפָּרְשֵׁי דָּא מִן דָּא, כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא, דְּהָא אוֹרַיְיתָא וּמַשְׁכְּנָא לָא מִתְפָּרְשֵׁי דָּא מִן דָּא, וְאָזְלִין כַּחֲדָא.","וּבְגִין כַּךְ, חַיָּילֵיהוֹן עָאלִין בְּחוּשְׁבָּנָא לְאִשְׁתְּמוֹדְעָא גַּבַּיְיהוּ, בַּר אִינּוּן אַחֲרָנִין דְּלֵית לוֹן חוּשְׁבָּנָא. וּבְגִין כַּךְ כְּתִיב, וַיְדַבֵּר יְיָ אֶל מֹשֶׁה בְּמִדְבַּר סִינַי בְּאֹהֶל מוֹעֵד. אִי בְּאֹהֶל מוֹעֵד, אֲמַאי בְּמִדְבַּר סִינַי. אֶלָּא חַד לְאוֹרַיְיתָא וְחַד לְמַשְׁכְּנָא.","וְהַאי וְהַאי, בְּאֶחָד לַחֹדֶשׁ הַשֵּׁנִי בַּשָּׁנָה הַשֵּׁנִית, וְכֹלָּא חַד, וְהַאי אִקְרֵי (מלכים א ו׳:א׳) חֹדֶשׁ זִיו רֶמֶז לְהַהוּא יַרְחָא וְשַׁתָּא דְּנָהִיר לְסִיהֲרָא, דְּהָא כְּדֵין עָלְמִין כֻּלְּהוּ אִשְׁתְּכָחוּ בִּשְׁלִימוּ. לְצֵאתָם מֵאֶרֶץ מִצְרַיִם, לְאִשְׁתְּמוֹדְעָא דְּהָא כַּד נַפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, בַּחֹדֶשׁ הָרִאשׁוֹן הֲוָה.","רִבִּי יִצְחָק פָּתַח, (תהילים קט״ו:י״ב) יְיָ זְכָרָנוּ יְבָרֵךְ יְבָרֵךְ אֶת בֵּית וְגוֹ'. יְיָ זְכָרָנוּ יְבָרֵךְ, אִלֵּין גּוּבְרִין. דַּהֲווֹ עָאלִין בְּחוּשְׁבָּנָא בְּמַדְבְּרָא, וְקוּדְשָׁא בְּרִיךְ הוּא מְבָרֵךְ לוֹן, וְאוֹסִיף עָלַיְיהוּ בְּכָל זִמְנָא.","תָּא חֲזֵי, הַאי מַאן דְּאָמַר שְׁבָחָא דְּחַבְרֵיהּ, דִּבְנוֹי, אוֹ דְּמָמוֹנֵיהּ, בָּעֵי לְבָרְכָא לֵיהּ, וּלְאוֹדָאָה עָלֵיהּ בִּרְכָאן. מְנָלָן. מִמֹּשֶׁה. דִּכְתִּיב, (דברים א׳:י׳) וְהִנְּכֶם הַיּוֹם כְּכֹכְבֵי הַשָּׁמַיִם לָרוֹב, לְבָתַר מַה כְּתִיב, יְיָ אֱלֹהֵי אֲבוֹתֵיכֶם יוֹסֵף עֲלֵיכֶם כָּכֶם אֶלֶף פְּעָמִים וְגוֹ'. תְּרֵין בִּרְכָאן הֲווֹ, חַד יְיָ אֱלֹהֵי אֲבוֹתֵיכֶם וְגוֹ'. הָא חַד. לְבָתַר וִיבָרֵךְ אֶתְכֶם כַּאֲשֶׁר דִּבֶּר לָכֶם. לְאוֹדָאָה עָלַיְיהוּ, בִּרְכָאן עַל בִּרְכָאן.","וְאִי אִיהוּ מָנֵי שְׁבָחָא דְּחַבְרֵיהּ, וְלָא אוֹדֵי עָלֵיהּ בִּרְכָאן. הוּא נִתְפַּס בְּקַדְמִיתָא מִלְּעֵילָּא. וְאִי אִיהוּ מְבָרֵךְ לֵיהּ, הוּא מִתְבָּרֵךְ מִלְּעֵילָּא. וּבִרְכְתָא בָּעֵי לְבָרְכָא לָהּ בְּעֵינָא טָבָא, וְלָא בְּעֵינָא בִּישָׁא. וּבְכֹלָּא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא רְחִימוּתָא דְּלִבָּא. וּמַה מַאן דִּמְבָרֵךְ לְחַבְרֵיהּ, בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא דִּיְּבָרֵךְ לֵיהּ בְּעֵינָא טָבָא, בְּלִבָּא טָבָא. מַאן דִּמְבָרֵךְ לְּקוּדְשָׁא בְּרִיךְ הוּא, עַל אַחַת כַּמָּה וְכַמָּה, דְּבָעֵי עֵינָא טָבָא, וְלִבָּא טָבָא, וּרְחִימוּתָא דְּלִבָּא. בְּגִין כָּךְ (דברים ו׳:ה׳) וְאָהַבְתָּ אֶת יְיָ אֱלֹהֶיךָ בְּכָל לְבָבְךָ וְגוֹ'.","תָּא חֲזֵי, הָא אוּקְמוּהָ לֵית בִּרְכָתָא דִּלְעֵילָּא שַׁרְיָא, עַל מִלָּה דְּאִתְמְנֵי. וְאִי תֵּימָא, יִשְׂרָאֵל אֵיךְ אִתְמְנוּן. אֶלָּא כּוּפְרָא נַטְלֵי מִנַּיְיהוּ, וְהָא אוּקְמוּהָ, וְחוּשְׁבָּנָא לָא הֲוִי עַד דְּיִתְכְּנִישׁ כָּל הַהוּא כּוּפְרָא, וְסָלִיק לְחוּשְׁבְּנָא, וּבְקַדְמֵיתָא מְבָרְכָן לְהוּ לְיִשְׂרָאֵל, וּלְבָתַר מְנָאָן הַהוּא כּוּפְרָא, וּלְבָתַר מְהַדְּרִין וּמְבָרְכִין לוֹן לְיִשְׂרָאֵל. אִשְׁתְּכָחוּ דְּיִשְׂרָאֵל מִתְבָּרְכִין בְּקַדְמִיתָא וּבְסוֹפָא, וְלָא סָלִיק בְּהוּ מוֹתָנָא.","מוֹתָנָא אֲמַאי סָלִיק בְּמִנְיָינָא. אֶלָּא בְּגִין דְּבִרְכְתָא לָא שַׁרְיָא בְּמִנְיָינָא, כֵּיוָן דְּאִסְתָּלַק בִּרְכָתָא, סִטְרָא אַחֲרָא שָׁארֵי עֲלוֹי, וְיָכִיל לְאַתְזְקָא. בְּגִין דָּא בְּמִנְיָינָא נַטְלִין כּוּפְרָא וּפִדְיוֹנָא, לְסַלְּקָא עָלֵיהּ מִנַּיְיהוּ.","(ס\"א מעליה מותנא) יְבָרֵךְ אֶת בֵּית יִשְׂרָאֵל, אִלֵּין נָשִׁין, דְּלָא סַלְּקִין בְּמִנְיָינָא. יְבָרֵךְ אֶת בֵּית אַהֲרֹן, דְּאִינּוּן מְבָרְכִין לְעַמָּא, בְּעֵינָא טָבָא וּבְלִבָּא טָבָא, וּבִרְחִימוּתָא דְּלִבָּא. אֶת בֵּית אַהֲרֹן, הָכִי נָמֵי נָשִׁין (דלהון), דְּאִתְבָּרְכָן בְּבִרְכָתָא (ס\"א דלהון).","יְבָרֵךְ יִרְאֵי יְיָ. אִלֵּין אִינּוּן לֵיוָאֵי, וְכֻלְּהוּ מִתְבָּרְכִין, בְּגִין דְּדַחֲלִין לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא. הַקְּטַנִים עִם הַגְּדוֹלִים, אַף עַל גַּב דְּלָא עָאלִין בְּמִנְיָינָא.","תָּא חֲזֵי לָא אִשְׁתְּכַח מִנְיָינָא בְּהוּ בְּיִשְׂרָאֵל דְּאִתְבָּרְכָן בֵּיהּ, כְּהַאי מִנְיָינָא. דְּהַאי מִנְיָינָא לְאִתְבָּרְכָא הֲוָה, וּלְאַשְׁלְמָא שְׁלֵימוּתָא דְּעָלְמִין הֲוָה, וּבַאֲתָר דְּבִרְכָּאן נָפְקִין אִתְמְנוּן, דִּכְתִּיב בְּאֶחָד לַחֹדֶשׁ הַשֵּׁנִי, דְּאִיהוּ זִיוָא דְּבִרְכָּאָן דְּעָלְמָא, דְּמִנֵּיהּ נָפִיק זִיוָא לְעָלְמָא. וְעַל דָּא אִקְרֵי חֹדֶשׁ זִי\"ו, דְּזִיוָא דְּכֹלָּא נָפִיק מִנֵּיהּ, וְעַל דָּא כְּתִיב, (תהילים קל״ד:ג׳) יְבָרֶכְךָ יְיָ מִצִּיּוֹן, וְכֹלָּא חַד מִלָּה וּכְתִיב (תהילים קל״ג:ג׳) כִּי שָׁם צִוָּה יְיָ אֶת הַבְּרָכָה וְגוֹ'."],[[0,"כיון דאורייתא ומשכנא","וכו': כיון שהוקמו התורה והמשכן, שהם ז\"א ומלכות, רצה הקב\"ה לספור חיילות התורה, כמה צבאות הם בתורה, בז\"א, כמה צבאות הם במשכן, שהוא מלכות, דהיינו שרצה לספור את ישראל, שהם צבאות ז\"א ומלכות. בוא וראה כל דבר שצריך להתישב במקומו, דהיינו לקשר הענף שלמטה בשרשו למעלה, אינו מתישב עד שנזכר בפה ונתמנה עליו. אף כאן רצה הקב\"ה לספור החיילות של התורה והחיילות של המשכן, כדי לקשר את ישראל בשורשם למעלה, שהם ז\"א ומלכות הנקראים תורה ומשכן. וכולם הם כאחד ואינם נפרדים זה מזה, הכל כעין של מעלה שהרי שורשיהם, תורה ומשכן, הם בזווג, ואינם נפרדים זה מזה, והולכים יחד."],[1,"ובגין כך חייליהון","וכו': ומשום זה ישראל, שהם צבאותיהם של ז\"א ומלכות, עולים בחשבון, שיהיו נודעים אצלם, חוץ מאלו האחרים שאין להם חשבון, דהיינו נשים ושאינם בני עשרים שנה. ומשום זה כתוב, וידבר ה' אל משה במדבר סיני באהל מועד. אם באהל מועד למה צריך לומר במדבר סיני. כי ידוע שאהל מועד לא היה אלא במדבר סיני. ומשיב, אלא אחד הוא לתורה, שהיא ז\"א, ואחד למשכן. שהוא המלכות."],[2,"והאי והאי באחד","וכו': וזה וזה, תורה ומשכן, היו באחד לחדש השני בשנה השנית. שה\"ס גבורה והארת החכמה שבשמאל. כי ניסן הוא קו ימין וחסד, ואייר הוא קו שמאל וגבורה. והכל אחד. כלומר שהיו ימין ושמאל ביחוד אחד. וחדש זה נקרא חדש זיו. רמז לחדש ההוא, והשנה, המאיר אל הלבנה, שהיא המלכות, כי עיקר שלמות המלכות הוא מקו שמאל, שה\"ס חדש שני, ושנה שנית. כי אז נמצאים כל העולמות בשלמות, כמו המלכות שהיא שורשם. \u0003לצאתם מארץ מצרים\u0004. הכתוב מודיענו בזה, אשר, כשיצאו ישראל ממצרים, בחדש הראשון היה. כלומר שיצאו מבחינת חדש הראשון שהוא חסד וקו ימין. ועתה נשלמו גם מבחינת חדש השני, שהוא גבורה וקו שמאל."],[3,"ר' יצחק פתח","וכו': רי\"פ, ה' זכרנו יברך יברך את בית וגו'. \u0003ה' זכרנו יברך\u0004, אלו הגברים שהיו עולים בחשבון במדבר, שהקב\"ה מברך אותם ומוסיף עליהם בכל פעם."],[4,"ת\"ח האי מאן","וכו': בוא וראה, מי שאומר שבחו של חברו, מבניו או מכספו, צריך לברכו, ולהודות על הברכות. מאין לנו. ממשה, שכתוב, והנכם היום כככבי השמים לרוב, לאח\"כ מה כתוב, ה' אלקי אבותיכם יוסיף עליכם ככם אלף פעמים ויברך אתכם כאשר דבר לכם. ב' ברכות היו, אחת, ה' אלקי אבותיכם וגו'. הרי אחת, לאחר כך, ויברך אתכם כאשר דבר לכם. להודות עליהן, וברכות על ברכות."],[5,"ואי איהו מני","וכו': ואם הוא מונה שבחו של חברו, ואינו מודה על הברכות, הוא נתפס תחלה מלמעלה, דהיינו שניזק מחמתו. ואם הוא מברך אותו, הוא עצמו מתברך מלמעלה. וצריך לברכו בעין טובה ולא בעין רעה. ובכל דבר רוצה הקב\"ה אהבת הלב בשעה שמברך. ומה, מי שמברך את חברו, רוצה הקב\"ה שיברכו בעין טובה ובלב טוב, מי שמברך את הקב\"ה על אחת כמה וכמה שצריך עין טובה ולב טוב ואהבת הלב. משום זה, כתוב ואהבת את ה' אלקיך בכל לבבך וגו'."],[6,"ת\"ח הא אוקמוה","וכו': בוא וראה, הרי העמידוהו שאין הברכה שלמעלה שורה על דבר שנמנה. ואם תאמר, ישראל איך נמנו. אלא כופר לקחו מהם, וכבר העמידוהו, והחשבון לא היה עד שנאסף כל אותו הכופר, ועלה לחשבון. ובתחילה היו מברכים את ישראל, ואח\"כ מנו אותו הכופר, ואח\"כ חזרו וברכו את ישראל. נמצא שישראל נתברכו בתחילה ובסוף, ולא היה בהם מות."],[7,"מותנא אמאי סליק","וכו': שואל, למה עולה המות ע\"י המנין. ומשיב, אלא משום שברכה אינה שורה במנין, כיון שמסתלקת הברכה, שורה עליו הסטרא אחרא ויכול להנזק. משום זה במנין לוקחים כופר ופדיון להעביר מעליו המות."],[7,"","פירוש. המנין נמשך מבחי' שמאל בלי ימין, שה\"ס חכמה בלי חסדים שמשם נמשכים המחלוקת, החשך והמות (כנ\"ל ב\"א אות מ\"ד ד\"ה וזה, ו אות ל\"ד ד\"ה נפק). ואין לו תקנה אלא ע\"י קו האמצעי, שע\"י המסך שלו, ממעט הג\"ר דשמאל ומיחדו עם הימין, שאז מתמעטים אורות השמאל לממטה למעלה (כנ\"ל ב\"א אות נ' ד\"ה מחלוקת) שה\"ס ו\"ק בלי ג\"ר, דהיינו מחצית המדרגה. וז\"ס מחצית השקל, אבל הארתו בשלמות, להיותו כלול בחסדים מב' הקוין. וז\"ש \u0003מותנא אמאי סליק במנינא.\u0004 ומשיב \u0003אלא בגין דברכתא לא שריא במנינא,\u0004 משום שאין שם ברכה, שהוא חסדים, להיות אז השמאל בפרוד מימין שהוא ברכה וחסדים, כנ\"ל. וז\"ש, (באות י\"ג) אלא \u0003כופרא נטלי מנייהו,\u0004 וכו' והכופר, שה\"ס מחצית השקל, דהיינו הנמשך ממחצית מדרגת השמאל, להיותו כבר מיוחד עם הימין וקו האמצעי, כנ\"ל. \u0003וסליק לחושבנא,\u0004 כי בדרך זה אין מות בחשבון, אלא אדרבא שכל השלמות בו. וז\"ש, \u0003ובקדמיתא מברכן להו לישראל,\u0004 דהיינו שתחילה ממשיכים החסדים קו ימין, \u0003ולבתר מנאן ההוא כופרא,\u0004 דהיינו שממשיכים מחצית השקל מקו השמאל, שה\"ס ו\"ק דחכמה, \u0003ולבתר מהדרין ומברכין לון לישראל.\u0004 דהיינו שממשיכים חסדים מקו האמצעי, ונמצאים חסדים מקו ימין מצד זה וחסדים מקו אמצעי מצד זה, \u0003ולא סליק בהו מותנא.\u0004 ואז אין שום דינים עוד בקו שמאל. וזה דומה למ\"ש לעיל (אמור אות קצ\"ז) כדין אחידן תרווייהו ביה ביצחק דא מהאי סטרא ודא מהאי סטרא ולא \u0003יכלין תוקפוי לנפקא לבר.\u0004 ע\"ש."],[8,"יברך את בית ישראל:","אלה הן הנקבות הנקראות בית, שלא עלו בחשבון. כי הנקבות לא נמנו במדבר. \u0003יברך את בית אהרן,\u0004 משום שהם הכהנים, ומברכים את העם בעין טובה, ובלב טוב, ובאהבת הלב. \u0003את בית אהרן,\u0004 למה אומר בית. הוא מרמז ג\"כ לנשים, שמתברכין בברכתו של אהרן."],[9,"יברך יראי ה'","וכו': אלו הם הלוים, שכולם מתברכים משום שיראים מה'. \u0003הקטנים עם הגדולים,\u0004 אע\"פ שהקטנים לא נכנסו בחשבון, כי לא נמנו אלא מעשרים ולמעלה, יתברכו יחד עם הגדולים."],[10,"ת\"ח לא אשתכח","וכו': בוא וראה לא נמצא מנין בישראל שיתברכו ממנו, כמנין הזה, שנמנו במחצית השקל, כי מנין הזה להתברך היה, ולהשלים שלמות העולמות היה, שה\"ס השלמות הגדולה של יחוד החכמה בחסדים (כנ\"ל באות י\"ד) ובמקום שהברכות יוצאות נמנו, שכתוב באחד לחדש השני, שהוא זיו, דהיינו הארת חכמה שבשמאל, של ברכות העולם, שהם חסדים, שממנו יוצא הזיו לעולם. ועל כן נקרא החדש השני, שהוא קו שמאל (כנ\"ל באות ט') בשם, זיו, כי זיו הכל יוצא ממנו, שהוא הארת החכמה כלול בחסדים. שבהיותו מאיר רק ממטה למעלה אינו נקרא אור אלא זיו. וע\"כ כתוב, יברכך ה' מציון, שה\"ס המלכות שבה מקום גילוי הארת החכמה (כנ\"ל ב\"א דף רע\"ו אות ש\"מ ד\"ה ועוד כמה) והכל דבר אחד הוא. כי המלכות נבנית מהחדש השני שה\"ס קו שמאל. וכתוב, כי שם צוה ה' את הברכה חיים עד העולם. אשר הברכה ה\"ס חסדים, וחיים ה\"ס חכמה. בסו\"ה החכמה תחיה את בעליה."]],[[0,"","כֵּיוָן שֶׁהַתּוֹרָה וְהַמִּשְׁכָּן הוּקְמוּ, רָצָה הַקָּדוֹשׁ-בָּרוּךְ-הוּא לִפְקֹד הַחֲיָלוֹת שֶׁל הַתּוֹרָה, כַּמָּה צְבָאוֹת הֵם שֶׁל הַתּוֹרָה, כַּמָּה צְבָאוֹת הֵם שֶׁל הַמִּשְׁכָּן. בֹּא רְאֵה, כָּל דָּבָר שֶׁצָּרִיךְ לְהִתְיַשֵּׁב בִּמְקוֹמוֹ, לֹא מִתְיַשֵּׁב עַד שֶׁנִּזְכָּר בַּפֶּה, וּמִתְמַנֶּה עָלָיו. אַף כָּאן - רָצָה הַקָּדוֹשׁ-בָּרוּךְ-הוּא לִפְקֹד חֵילוֹת הַתּוֹרָה וְחֵילוֹת הַמִּשְׁכָּן, וְכֻלָּם הָיוּ כְּאֶחָד וְלֹא נִפְרָדִים זֶה מִזֶּה, הַכֹּל כְּמוֹ לְמַעְלָה, שֶׁהֲרֵי הַתּוֹרָה וְהַמִּשְׁכָּן לֹא נִפְרָדִים זֶה מִזֶּה, וְהוֹלְכִים כְּאֶחָד."],[1,"","וּמִשּׁוּם זֶה חֵילוֹתֵיהֶם עוֹלִים בְּחֶשְׁבּוֹן לְהִוָּדַע אֲלֵיהֶם, פְּרָט לְאוֹתָם אֲחֵרִים שֶׁאֵין לָהֶם חֶשְׁבּוֹן. וְלָכֵן כָּתוּב, וַיְדַבֵּר ה' אֶל מֹשֶׁה בְּמִדְבַּר סִינַי בְּאֹהֶל מוֹעֵד. אִם בְּאֹהֶל מוֹעֵד, לָמָּה בְּמִדְבַּר סִינַי? אֶלָּא אֶחָד לַתּוֹרָה וְאֶחָד לַמִּשְׁכָּן."],[2,"","וְזֶה וָזֶה - בְּאֶחָד לַחֹדֶשׁ הַשֵּׁנִי בַּשָּׁנָה הַשֵּׁנִית, וְהַכֹּל אֶחָד, וְזֶה נִקְרָא חֹדֶשׁ זִיו, רֶמֶז לְאוֹתוֹ חֹדֶשׁ וְשָׁנָה שֶׁמֵּאִיר לַלְּבָנָה, שֶׁהֲרֵי אָז כָּל הָעוֹלָמוֹת נִמְצָאִים בִּשְׁלֵמוּת. לְצֵאתָם מֵאֶרֶץ מִצְרַיִם, לְהוֹדִיעַ שֶׁכְּשֶׁיָּצְאוּ מֵאֶרֶץ מִצְרַיִם, זֶה הָיָה בַּחֹדֶשׁ הָרִאשׁוֹן."],[3,"","רַבִּי יִצְחָק פָּתַח, (תהלים קטו) ה' זְכָרָנוּ יְבָרֵךְ יְבָרֵךְ אֶת בֵּית וְגוֹ'. ה' זְכָרָנוּ יְבָרֵךְ - אֵלֶּה הַגְּבָרִים, שֶׁהָיוּ עוֹלִים בַּחֶשְׁבּוֹן בַּמִּדְבָּר, וְהַקָּדוֹשׁ-בָּרוּךְ-הוּא מְבָרֵךְ אוֹתָם וּמוֹסִיף עֲלֵיהֶם בְּכָל זְמַן."],[4,"","בֹּא רְאֵה, מִי שֶׁאוֹמֵר שֶׁבַח חֲבֵרוֹ, שֶׁל בָּנָיו, אוֹ שֶׁל מָמוֹנוֹ - צָרִיךְ לְבָרְכוֹ וּלְהוֹדוֹת עָלָיו בִּבְרָכוֹת. מִנַּיִן לָנוּ? מִמֹּשֶׁה, שֶׁכָּתוּב (דברים א) וְהִנְּכֶם הַיּוֹם כְּכוֹכְבֵי הַשָּׁמַיִם לָרֹב. אַחַר כָּךְ מַה כָּתוּב? ה' אֱלֹהֵי אֲבוֹתֵכֶם יֹסֵף עֲלֵיכֶם כָּכֶם אֶלֶף פְּעָמִים וְגוֹ'. שְׁתֵּי בְרָכוֹת הָיוּ: אַחַת - ה' אֱלֹהֵי אֲבוֹתֵכֶם, הֲרֵי אַחַת. אַחַר כָּךְ - וִיבָרֵךְ אֶתְּכֶם כַּאֲשֶׁר דִּבֶּר לָכֶם. לְהוֹדוֹת עֲלֵיהֶם, בְּרָכוֹת עַל בְּרָכוֹת."],[5,"","וְאִם הוּא מוֹנֶה אֶת שֶׁבַח חֲבֵרוֹ וְלֹא מוֹדֶה עָלָיו בְּרָכוֹת - הוּא נִתְפָּס בַּתְּחִלָּה מִלְמַעְלָה. וְאִם הוּא מְבָרֵךְ אוֹתוֹ - הוּא מִתְבָּרֵךְ מִלְמַעְלָה. וְהַבְּרָכָה צָרִיךְ לְבָרֵךְ אוֹתָהּ בְּעַיִן טוֹבָה, וְלֹא בְּעַיִן רָעָה. וּבַכֹּל רוֹצֶה הַקָּדוֹשׁ-בָּרוּךְ-הוּא אַהֲבַת הַלֵּב. וּמַה מִּי שֶׁמְּבָרֵךְ אֶת חֲבֵרוֹ, רוֹצֶה הַקָּדוֹשׁ-בָּרוּךְ-הוּא שֶׁיְּבָרֵךְ אוֹתוֹ בְּעַיִן טוֹבָה, בְּלֵב טוֹב - מִי שֶׁמְּבָרֵךְ אֶת הַקָּדוֹשׁ-בָּרוּךְ-הוּא עַל אַחַת כַּמָּה וְכַמָּה שֶׁצָּרִיךְ עַיִן טוֹבָה וְלֵב טוֹב וְאַהֲבַת הַלֵּב. בִּגְלַל זֶה, (שם ו) וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ בְּכָל לְבָבְךְ וְגוֹ'."],[6,"","בֹּא רְאֵה, הֲרֵי פֵּרְשׁוּהָ, אֵין הַבְּרָכָה שֶׁלְּמַעְלָה שׁוֹרָה עַל דָּבָר שֶׁנִּמְנֶה. וְאִם תֹּאמַר, יִשְׂרָאֵל אֵיךְ נִמְנוּ? אֶלָּא כֹּפֶר לָקַח מֵהֶם, וַהֲרֵי פֵּרְשׁוּהָ, וְהַחֶשְׁבּוֹן לֹא הָיָה עַד שֶׁנֶּאֱסַף כָּל אוֹתוֹ הַכֹּפֶר וְעָלָה לַחֶשְׁבּוֹן. וּבַתְּחִלָּה מְבָרְכִים אֶת יִשְׂרָאֵל, אַחַר כָּךְ מוֹנִים אוֹתוֹ כֹּפֶר, אַחַר כָּךְ חוֹזְרִים וּמְבָרְכִים אֶת יִשְׂרָאֵל. נִמְצָא שֶׁיִּשְׂרָאֵל מִתְבָּרְכִים בַּתְּחִלָּה וּבַסּוֹף, וְלֹא עוֹלָה בָהֶם מַגֵּפָה."],[7,"","לָמָּה הַמַּגֵּפָה עוֹלָה בְמִנְיָן? אֶלָּא מִשּׁוּם שֶׁבְּרָכָה לֹא שׁוֹרָה בְמִנְיָן. כֵּיוָן שֶׁמִּסְתַּלֶּקֶת הַבְּרָכָה, הַצַּד הָאַחֵר שׁוֹרֶה עָלָיו, וְיָכוֹל לְהִנָּזֵק. בִּגְלַל זֶה בְּמִנְיָן לוֹקְחִים כֹּפֶר וּפִדְיוֹן, לְסַלֵּק אוֹתוֹ מֵהֶם."],[8,"","יְבָרֵךָ אֶת בֵּית יִשְׂרָאֵל - אֵלּוּ הַנָּשִׁים, שֶׁלֹּא עוֹלוֹת בַּמִּנְיָן. יְבָרֵךְ אֶת בֵּית אַהֲרֹן - שֶׁהֵם מְבָרְכִים אֶת הָעָם בְּעַיִן טוֹבָה וּבְלֵב טוֹב וּבְאַהֲבַת הַלֵּב. אֶת בֵּית אַהֲרֹן - כָּךְ גַּם הַנָּשִׁים (שלהם), שֶׁמִּתְבָּרְכוֹת בַּבְּרָכָה (שלהם)."],[9,"","יְבָרֵךָ יִרְאֵי ה' - אֵלֶּה הֵם הַלְוִיִּם, וְכֻלָּם מִתְבָּרְכִים, כִּי הֵם יְרֵאִים מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. הַקְּטַנִּים עִם הַגְּדלִים - אַף עַל גַּב שֶׁלֹּא עוֹלִים בַּמִּנְיָן."],[10,"","בֹּא רְאֵה, לֹא נִמְצָא מִנְיָן בְּיִשְׂרָאֵל שֶׁהִתְבָּרְכוּ בוֹ כְּמִנְיָן זֶה, שֶׁמִּנְיָן זֶה לְהִתְבָּרֵךְ הָיָה, וּלְהַשְׁלִים שְׁלֵמוּת הָעוֹלָמִים הָיָה, וּבְמָקוֹם שֶׁהַבְּרָכוֹת יוֹצְאוֹת נִמְנוּ, שֶׁכָּתוּב בְּאֶחָד לַחֹדֶשׁ הַשֵּׁנִי, שֶׁהוּא זִיו בִּרְכוֹת הָעוֹלָם, שֶׁמִּמֶּנּוּ יוֹצֵא זִיו לָעוֹלָם. וְעַל זֶה נִקְרָא חֹדֶשׁ זִי\"ו, שֶׁהַזִּיו שֶׁל הַכֹּל יוֹצֵא מִמֶּנּוּ, וְעַל זֶה כָּתוּב (תהלים קלד) יְבָרֶכְךְ ה' מִצִּיּוֹן, וְהַכֹּל דָּבָר אֶחָד, וְכָתוּב (שם קלג) כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה וְגוֹ'."]]],[["רִבִּי יְהוּדָה הֲוָה שְׁכִיחַ קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן, אָמַר לֵיהּ יִשְׂרָאֵל מֵאָן אֲתָר אִתְבָּרְכָן. אָמַר לֵיהּ, וַוי לְעָלְמָא, דְּלָא מַשְׁגִּיחִין וְלָא מִסְתַּכְּלִין בְּנֵי נָשָׁא, בִּיקָרָא דְּמַלְכָּא עִלָּאָה. תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִשְׁתְּכָחוּ יִשְׂרָאֵל זַכָּאִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וַהֲווּ עָלְמִין (ס\"א עמיה) שְׁכִיחִין בְּחַד אִילָנָא עִלָּאָה קַדִּישָׁא, דִּמְזוֹנָא דְּכֹלָּא בֵּיהּ, הֲוָה מִתְבָּרֵךְ מֵאֲתָר דְּכָל בִּרְכָאן כְּנִישִׁין בֵּיהּ. וּבֵיהּ אִתְנְטַע וְאַשְׁתִּילוּ שָׁרְשׁוֹי.","וְיִשְׂרָאֵל לְתַתָּא, הֲווֹ מִתְבָּרְכָן (ואשתילו שרשוי) מֵאֲתָר דְּכָל אִינּוּן בִּרְכָאן נָפְקִין בֵּיהּ, וְלָא מִתְעַכְּבֵי לְמֵיפַּק, הֲדָא הוּא דִכְתִיב יְבָרֶכְךָ יְיָ מִצִּיּוֹן, וּכְתִיב (תהילים קל״ג:ג׳) כְּטַל חֶרְמוֹן שֶׁיּוֹרֵד עַל הַרְרֵי צִיּוֹן כִּי שָׁם צִוָּה יְיָ אֶת הַבְּרָכָה חַיִּים עַד הָעוֹלָם. וְדָא אִיהוּ נְהִירוּ דְּעָלְמָא. דִּכְתִּיב, (תהילים נ׳:ב׳) מִצִּיּוֹן מִכְּלָל יוֹפִי אֱלֹהִים הוֹפִיעַ. הוֹפִיעַ: נָהִיר. כְּמָה דְאַתְּ אָמֵר (דברים ל״ג:ב׳) הוֹפִיעַ מֵהַר פָּארָן (ס\"א ודא נהירו). וְכַד יְנָהֵר, יְנָהֵר לְכֻלְּהוּ עָלְמִין.","וְכַד הַאי נְהִירוּ אִתְּעַר, כֹּלָּא הוּא בְּחַבְרוּתָא (ס\"א כלא הוא בחביבותא), כֹּלָּא הוּא בִּרְחִימוּתָא, כֹּלָּא הוּא בִּשְׁלִימוּ, כְּדֵין הוּא שְׁלָמָא דְּכֹלָּא, שְׁלָמָא דְּעֵילָּא וְתַתָּא, הֲדָא הוּא דִכְתִיב, (תהילים קכ״ב:ז׳) יְהִי שָׁלוֹם בְּחֵילֵךְ שַׁלְוָה בְּאַרְמְנוֹתָיִךְ.","(במדבר ב׳:ב׳) אִישׁ עַל דִּגְלוֹ בְאוֹתוֹת לְבֵית אֲבוֹתָם יַחֲנוּ בְּנֵי יִשְׂרָאֵל וְגוֹ'. רִבִּי אֶלְעָזָר פָּתַח, (ישעיהו ס״ו:י׳) שִׂמְחוּ אֶת יְרוּשָׁלַ ם וְגִילוּ בָּהּ כָּל אֹהֲבֶיהָ וְגוֹ'. כַּמָה חֲבִיבָא אוֹרַיְיתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּהָא בְּכָל אֲתָר דְּמִלֵּי דְּאוֹרַיְיתָא אִשְׁתְּמָעוּ, קוּדְשָׁא בְּרִיךְ הוּא וְכָל חַיָּילִין דִּילֵיהּ כֻּלְּהוּ צַיְיתִין לְמִלוּלֵיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְדַיְּירָא עִמֵּיהּ, הֲדָא הוּא דִכְתִיב, (שמות כ׳:כ״א) בְּכָל הַמָקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי וְגוֹ'. וְלֹא עוֹד, אֶלָּא דְּשַׂנְאוֹי נַפְלִין קַמֵּיהּ, וְהָא אוֹקְמוּהָ.","תָּא חֲזֵי, פִּקּוּדֵי אוֹרַיְיתָא עִלָּאִין אִינּוּן לְעֵילָּא. אָתֵי בַּר נָשׁ וְעָבִיד פִּקּוּדָא חֲדָא, הַהוּא פִּקּוּדָא קַיְּימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּמִתְעַטְּרָא קַמֵּיהּ, וְאָמַר פְּלַנְיָיא עֲבַד לִי, וּמִן פְּלַנְיָיא אֲנָא, בְּגִין דְּאִיהוּ אִתְּעַר לֵיהּ לְעֵילָּא. כְּגַוְונָא דְּאִיהוּ אִתְּעַר לֵיהּ לְתַתָּא, הָכִי נָמֵי אִתְּעַר לְעֵילָּא, וְעָבִיד שְׁלָמָא לְעֵילָּא וְתַתָּא, כְּמָה דְּאַתְּ אָמֵר, (ישעיהו כ״ז:ה׳) אוֹ יַחֲזֵק בְּמָעוּזִּי יַעֲשֶׂה שָׁלוֹם לִי שָׁלוֹם יַעֲשֶׂה לִי. יַעֲשֶׂה שָׁלוֹם לִי, לְעֵילָּא. (לעיל י\"ד ע\"ב) שָׁלוֹם יַעֲשֶׂה לִּי, לְתַתָּא. זַכָּאָה חוּלָקֵיהּ דְּהַהוּא בַּר נָשׁ, דְּעָבִיד פִּקּוּדֵי אוֹרַיְיתָא.","שִׂמְחוּ אֶת יְרוּשָׁלַם וְגוֹ', בְּגִין דְּחֶדְוָה לָא אִשְׁתְּכַח, אֶלָּא בְּזִמְנָא דְּיִשְׂרָאֵל קַיְימֵי בְּאַרְעָא קַדִּישָׁא. דְּתַמָּן אִתְחַבְּרַת אִתְּתָא בְּבַעְלָהּ, וּכְדֵין הוּא חֶדְוָותָא דְּכֹלָּא, חֶדְוָותָא דְּעֵילָּא וְתַתָּא. בְּזִמְנָא דְּיִשְׂרָאֵל לָא אִשְׁתְּכָחוּ בְּאַרְעָא קַדִּישָׁא, אָסִיר לֵיהּ לְבַּר נָשׁ לְמֵחדֵי, וּלְאַחְזָאָה חֵידוּ. דִּכְתִּיב, שִׂמְחוּ אֶת יְרוּשָׁלַם וְגִילוּ בָהּ וְגוֹ', וְגִילוּ בָהּ דַּיְיקָא.","רִבִּי אַבָּא חָמָא חַד בַּר נָשׁ, דְּהֲוָה חַדֵּי בְּבֵי טְרוֹנְיָיא דְּבָבֶל, בָּטַשׁ בֵּיהּ, אָמַר שִׂמְחוּ אֶת יְרוּשָׁלַם כְּתִיב (אמר רבי אבא), בְּזִמְנָא דִּיְרוּשָׁלַ ם בְּחֶדְוָה, בָּעֵי בַּר נָשׁ לְמֶחְדֵּי. רִבִּי אֶלְעָזָר לְטַעְמֵיהּ, דְּאָמַר שִׂמְחוּ אֶת יְרוּשָׁלַם, הַיְינוּ דִּכְתִּיב, (תהילים ק׳:ב׳) עִבְדוּ אֶת יְיָ בְּשִׂמְחָה.","כָּתוּב אֶחָד אוֹמֵר, עִבְדוּ אֶת יְיָ בְּשִׂמְחָה, וְכָתוּב אֶחָד אוֹמֵר, (תהילים ב׳:י״א) עִבְדוּ אֶת יְיָ בְּיִרְאָה וְגִילוּ בִּרְעָדָה. מַה בֵּין הַאי לְהַאי. אֶלָּא, כָּאן בְּזִמְנָא דְּיִשְׂרָאֵל שָׁרָאן בְּאַרְעָא קַדִּישָׁא. כָּאן בְּזִמְנָא דְּיִשְׂרָאֵל שָׁרָאן בְּאַרְעָא אַחֲרָא. (ד\"א) עִבְדוּ אֶת יְיָ בְּיִרְאָה, דָּא כְּנֶסֶת יִשְׂרָאֵל, בְּזִמְנָא דְּאִיהִי בְּגָלוּתָא בֵּינֵי עֲמַמְיָא.","אָמַר רִבִּי יְהוּדָה, וְהָא כְּתִיב (ישעיהו נ״ה:י״ב) כִּי בְּשִׂמְחָה תֵצֵאוּ, וְדָא הִיא כְּנֶסֶת יִשְׂרָאֵל, כֵּיוָן דְּאָמַר תֵצֵאוּ, מִן גָּלוּתָא הוּא, וְאִקְרֵי שִׂמְחָה. אָמַר לֵיהּ, וַדַּאי הָכִי הוּא, דְּכָל זִמְנָא דְּאִיהִי בְּגָלוּתָא וּשְׁכִיבַת לְעַפְרָא, לָא אִקְרֵי שִׂמְחָה, עַד דְקוּדְשָׁא בְּרִיךְ הוּא יֵיתֵי לְגַבָּהּ, וְיוֹקִים לָהּ מֵעַפְרָא, וְיֵימָא (ישעיהו נ״ב:ב׳) הִתְנַעֲרִי מֵעָפָר וְגוֹ'. (ישעיהו ס׳:א׳) קוּמִי אוֹרִי וְגוֹ'. וְיִתְחַבְּרוּן כַּחֲדָא, (ויוקים לה מעפרא) כְּדֵין חֶדְוָותָא אִקְרֵי. חֶדְוָותָא דְּכֹלָּא, וּכְדֵין בְּשִׂמְחָה תֵצֵאוּ וַדַּאי. כְּדֵין כַּמָה חַיָּילִין יִפְּקוּן לָקֳבְלָא דְּמַטְרוֹנִיתָא, לְחֶדְוָותָא דְּהִלּוּלָא דְּמַלְכָּא, כְּמָה דְאַתְּ אָמֵר (ישעיהו נ״ה:י״ב) הֶהָרִים וְהַגְּבָעוֹת יִפְצְחוּ וְגוֹ', וּכְתִיב (ישעיהו נ״ב:י״ב) כִּי הֹלֵךְ לִפְנֵיכֶם יְיָ וּמְאַסִּפְכֶם וְגוֹ'."],[[0,"רבי יהודה הוה","וכו': ר\"י היה מצוי לפני ר' שמעון. אמר לו, ישראל מאיזה מקום הם מתברכים. אמר לו, אוי לעולם שאינם משגיחים, ובני אדם אינם מסתכלים בכבוד מלך העליון. בוא וראה, בשעה שישראל נמצאים זכאים לפני הקב\"ה, היו העולמות נמצאים באילן אחד עליון קדוש, שהוא ז\"א, שבו מזון הכל. והוא היה מתברך ממקום שכל הברכות מקובצים שם, שהוא הבינה, ובו הוא נטוע והושתלו שרשיו. כי מוחין דז\"א הושתלו בבינה, בסוד תלת מחד נפקי חד בתלת קיימא (כנ\"ל ב\"א דף רפ\"ז אות שס\"ג ד\"ה תלת)."],[1,"וישראל לתתא הוו","וכו': וישראל למטה היו מתברכים ממקום שכל אלו הברכות יוצאות בו ואינן מתעכבות לצאת, שהיא מלכות, ז\"ש, יברכך ה' מציון. וכתוב כטל חרמון שיורד על הררי ציון, שהיא מלכות, וכתוב, כי שם צוה ה' את הברכה חיים עד העולם (עי' לעיל בדבור הסמוך). וזה הוא האור של העולם. שכתוב מציון מכלל יופי אלקים הופיע. הופיע, פירושו מאיר. כש\"א, הופיע מהר פארן. וכשמאיר הוא מאיר לכל העולמות."],[2,"וכד האי נהירו","וכו': וכשהאור הזה, דהיינו הברכה וחיים הנ\"ל, מתעורר, הכל הוא בחבור, דהיינו בסוד הזווג, הכל הוא באהבה, הכל הוא בשלמות, אז הוא שלום הכל, שלום שלמעלה ושלמטה. ז\"ש, יהי שלום בחילך שלוה בארמנותיך."],[3,"איש על דגלו באותות","וגו': רבי אלעזר פתח. שמחו את ירושלים וגילו בה כל אהביה וגו'. כמה חביבה התורה לפני הקב\"ה כי בכל מקום שדברי תורה נשמעים, הקב\"ה וכל צבאותיו כולם מקשיבים לדבריו. והקב\"ה בא לדור עמו. ז\"ש בכל מקום אשר אזכיר את שמי וגו'. ולא עוד אלא ששונאיו נופלים לפניו. וכבר העמידוהו."],[4,"ת\"ח פקודי אורייתא","וכו': בוא וראה, מצוות התורה עליונות הן למעלה. בא אדם ועשה מצוה אחת, המצוה ההיא עומדת לפני הקב\"ה ומתעטרת לפניו, ואומרת פלוני עשה אותי, ומן פלוני אני, משום שהוא עורר אותה למעלה. כי כמו שהוא עורר את המצוה למטה כן היא מתעוררת למעלה, ועושה שלום למעלה ולמטה, דהיינו שגורם זווג לז\"א ומלכות, המכונים מעלה ומטה. כמש\"א, או יחזק במעוזי יעשה שלום לי שלום יעשה לי. \u0003יעשה שלום לי\u0004, הוא למעלה, בז\"א, \u0003שלום יעשה לי\u0004, הוא למטה במלכות. אשרי חלקו של אותו האדם העושה מצות התורה."],[5,"שמחו את ירושלים","וגו': הוא, משום ששמחה אינה נמצאת אלא בזמן שישראל נמצאים בארץ הקדושה, ששם מתחברת אשה בבעלה. דהיינו ז\"א ומלכות, ואז הוא שמחת, שמחה של מעלה ושל מטה. ובזמן שישראל אינם נמצאים בארץ הקדושה, אסור לאדם לשמוח ולהראות שמחה. שכתוב, שמחו את ירושלים וגילו בה וגו'. \u0003וגילו בה,\u0004 הוא בדיוק, דהיינו בזמן שישראל נמצאים בה."],[6,"רבי אבא חמא","וכו': ר\"א ראה אדם אחד, שהיה שמח בבי טרוניא שבבבל, בעט בו. אמר, כתוב. בזמן שירושלים בשמחה צריך האדם לשמוח. ולא בזמן הגלות. ר' אלעזר הולך לטעמו, שאמר, שמחו את ירושלים היינו שכתוב, עבדו את ה' בשמחה. דהיינו שירושלים היא השכינה, וצריכים לעבוד ולשמח אותה."],[7,"כתוב אחד אומר","וכו': כתוב אחד אומר, עבדו את ה' בשמחה. וכתוב אחד אומר עבדו את ה' ביראה וגילו ברעדה. מה בין זה לזה. ומשיב. כאן בזמן שישראל שורים בארץ הקדושה, שאז עובדים לפני ה' בשמחה. וכאן בזמן שישראל שורים בארץ אחרת. אז צריכים לעבוד ביראה ולשמוח ברעדה. עבדו את ה' ביראה. זו כנסת ישראל, דהיינו המלכות, בזמן שהיא בגלות בין העמים."],[8,"א\"ר יהודה והא","וכו': אר\"י, והרי כתוב, כי בשמחה תצאו, שזו היא כנסת ישראל, וכיון שאמר תצאו, הרי מן גלות היא, ונקראת שמחה, הרי שגם בגלות היא נקראת שמחה. אמר לו, ודאי כך הוא. שבכל זמן שהיא בגלות ושוכבת לעפר, אינה נקראת שמחה, עד שהקב\"ה יבא אליה ויקים אותה מן העפר, ויאמר, התנערי מעפר וגו'. קומי אורי וגו' ויתחברו יחד, אז היא נקראת שמחה. שהיא שמחת הכל, ואז בשמחה תצאו ודאי. אז כמה צבאות יצאו לקבל את המטרוניתא לשמחה של סעודת המלך, כש\"א ההרים והגבעות יפצחו וגו'. וכתוב, כי הלך לפניכם ה' ומאספכם וגו'."]],[[0,"","רַבִּי יְהוּדָה הָיָה מָצוּי לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לוֹ, יִשְׂרָאֵל, מֵאֵיזֶה מָקוֹם הֵם מִתְבָּרְכִים? אָמַר לוֹ, אוֹי לָעוֹלָם שֶׁלֹּא מַשְׁגִּיחִים וְלֹא מִסְתַּכְּלִים בְּנֵי אָדָם בִּכְבוֹד הַמֶּלֶךְ הָעֶלְיוֹן. בֹּא רְאֵה, בְּשָׁעָה שֶׁנִּמְצְאוּ יִשְׂרָאֵל צַדִּיקִים לִפְנֵי הַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְהָעוֹלָמוֹת הָיוּ (עמו) מְצוּיִים בְּעֵץ אֶחָד עֶלְיוֹן קָדוֹשׁ, שֶׁהַמָּזוֹן שֶׁל הַכֹּל בּוֹ, הָיָה מִתְבָּרֵךְ מִמָּקוֹם שֶׁכָּל הַבְּרָכוֹת כְּנוּסוֹת בּוֹ, וּבוֹ נִנְטַע וְנִשְׁתְּלוּ שָׁרָשָׁיו."],[1,"","וְיִשְׂרָאֵל לְמַטָּה הָיוּ מִתְבָּרְכִים (ונשתלו שרשיו) מִמָּקוֹם שֶׁכָּל אוֹתָן בְּרָכוֹת יוֹצְאוֹת בּוֹ וְלֹא מִתְעַכְּבוֹת לָצֵאת. זֶהוּ שֶׁכָּתוּב יְבָרֶכְךְ ה' מִצִּיּוֹן, וְכָתוּב כְּטַל חֶרְמוֹן שֶׁיֹּרֵד עַל הַרְרֵי צִיּוֹן כִּי שָׁם צִוָּה ה' אֶת הַבְּרָכָה חַיִּים עַד הָעוֹלָם. וְזֶהוּ אוֹר הָעוֹלָם, שֶׁכָּתוּב (תהלים נ) מִצִּיּוֹן מִכְלַל יֹפִי אֱלֹהִים הוֹפִיעַ. הוֹפִיעַ - הֵאִיר, כְּמוֹ שֶׁנֶּאֱמַר (דברים לג) הוֹפִיעַ מֵהַר פָּארָן. (וזה אור) וּכְשֶׁמֵּאִיר, מֵאִיר לְכָל הָעוֹלָמוֹת."],[2,"","וּכְשֶׁאוֹר זֶה מִתְעוֹרֵר, הַכֹּל הוּא בַּחֲבֵרוּת (הכל הוא בחביבות), הַכֹּל הוּא בְּאַהֲבָה, הַכֹּל הוּא בִּשְׁלֵמוּת, וְאָז הוּא שְׁלוֹם הַכֹּל, שָׁלוֹם שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה. זֶהוּ שֶׁכָּתוּב (תהלים קכב) יְהִי שָׁלוֹם בְּחֵילֵךְ שַׁלְוָה בְּאַרְמְנוֹתָיִךְ."],[3,"","אִישׁ עַל דִּגְלוֹ יַחֲנוּ בְאֹתֹת לְבֵית אֲבֹתָם יַחֲנוּ בְּנֵי יִשְׂרָאֵל וְגוֹ' (במדבר א). רַבִּי אֶלְעָזָר פָּתַח, (ישעיה סו) שִׂמְחוּ אֶת יְרוּשָׁלם וְגִילוּ בָהּ כָּל אֹהֲבֶיהָ וְגוֹ'. כַּמָּה חֲבִיבָה הַתּוֹרָה לִפְנֵי הַקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁהֲרֵי בְּכָל מָקוֹם שֶׁדִּבְרֵי תוֹרָה נִשְׁמָעִים, הַקָּדוֹשׁ-בָּרוּךְ-הוּא וְכָל חֵילוֹתָיו, כֻּלָּם מַקְשִׁיבִים לִדְבָרָיו, וְהַקָּדוֹשׁ-בָּרוּךְ-הוּא בָּא לָדוּר עִמּוֹ. זֶהוּ שֶׁכָּתוּב (שמות כ) בְּכָל הַמָּקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי וְגוֹ'. וְלֹא עוֹד, אֶלָּא שֶׁשּׂוֹנְאָיו נוֹפְלִים לְפָנָיו, וַהֲרֵי פֵּרְשׁוּהָ."],[4,"","בֹּא רְאֵה, מִצְווֹת הַתּוֹרָה הֵן עֶלְיוֹנוֹת לְמַעְלָה. בָּא אָדָם וְעָשָׂה מִצְוָה אַחַת - אוֹתָהּ הַמִּצְוָה עוֹמֶדֶת לִפְנֵי הַקָּדוֹשׁ-בָּרוּךְ-הוּא, וּמִתְעַטֶּרֶת לְפָנָיו וְאוֹמֶרֶת: פְּלוֹנִי עָשָׂה אוֹתִי, וּמִפְּלוֹנִי אֲנִי. מִשּׁוּם שֶׁהוּא עוֹרֵר אוֹתָהּ לְמַעְלָה. כְּמוֹ שֶׁהוּא עוֹרֵר אוֹתָהּ לְמַטָּה, כָּךְ גַּם עוֹרֵר אוֹתָהּ לְמַעְלָה, וְעָשָׂה שָׁלוֹם לְמַעְלָה וּלְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כז) אוֹ יַחֲזֵק בְּמָעֻזִּי יַעֲשֶׂה שָׁלוֹם לִי שָׁלוֹם יַעֲשֶׂה לִּי. יַעֲשֶׂה שָׁלוֹם לִי - לְמַעְלָה. שָׁלוֹם יַעֲשֶׂה לִּי - לְמַטָּה. אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁעוֹשֶׂה מִצְווֹת הַתּוֹרָה."],[5,"","שִׂמְחוּ אֶת יְרוּשָׁלם וְגוֹ', מִשּׁוּם שֶׁחֶדְוָה לֹא נִמְצֵאת אֶלָּא בִּזְמַן שֶׁיִּשְׂרָאֵל עוֹמְדִים בָּאָרֶץ הַקְּדוֹשָׁה, שֶׁשָּׁם מִתְחַבֶּרֶת אִשָּׁה בְּבַעְלָהּ, וְאָז זוֹהִי שִׂמְחַת הַכֹּל, הַשִּׂמְחָה שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה. בִּזְמַן שֶׁיִּשְׂרָאֵל לֹא נִמְצָאִים בָּאָרֶץ הַקְּדוֹשָׁה, אָסוּר לָאָדָם לִשְׂמֹחַ וּלְהַרְאוֹת שִׂמְחָה, שֶׁכָּתוּב שִׂמְחוּ אֶת יְרוּשָׁלַם וְגִילוּ בָהּ וְגוֹ', וְגִילוּ בָהּ דַּוְקָא."],[6,"","רַבִּי אַבָּא רָאָה אִישׁ שֶׁהָיָה שָׂמֵחַ בְּבֵית טְרוֹנְיָא שֶׁבְּבָבֶל. הִכָּה בּוֹ וְאָמַר, שִׂמְחוּ אֶת יְרוּשָׁלם כָּתוּב (אמר רבי אבא), בִּזְמַן שֶׁיְּרוּשָׁלַיִם בְּשִׂמְחָה צָרִיךְ אָדָם לִשְׂמֹחַ. רַבִּי אֶלְעָזָר לְטַעְמוֹ, שֶׁאָמַר שִׂמְחוּ אֶת יְרוּשָׁלם, הַיְנוּ שֶׁכָּתוּב (תהלים ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה."],[7,"","כָּתוּב אֶחָד אוֹמֵר, עִבְדוּ אֶת ה' בְּשִׂמְחָה. וְכָתוּב אֶחָד אוֹמֵר, (שם ב) עִבְדוּ אֶת ה' בְּיִרְאָה וְגִילוּ בִּרְעָדָה. מַה בֵּין זֶה לָזֶה? אֶלָּא, כָּאן בִּזְמַן שֶׁיִּשְׂרָאֵל שְׁרוּיִים בָּאָרֶץ הַקְּדוֹשָׁה - כָּאן בִּזְמַן שֶׁיִּשְׂרָאֵל שְׁרוּיִים בְּאֶרֶץ אַחֶרֶת. (ד\"א) עִבְדוּ אֶת ה' בְּיִרְאָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל בִּזְמַן שֶׁהִיא בַּגָּלוּת בֵּין הָעַמִּים."],[8,"","אָמַר רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב (ישעיה נה) כִּי בְשִׂמְחָה תֵצֵאוּ, וְזוֹ הִיא כְּנֶסֶת יִשְׂרָאֵל. כֵּיוָן שֶׁאָמַר תֵּצֵאוּ, מֵהַגָּלוּת הוּא, וְנִקְרֵאת שִׂמְחָה. אָמַר לוֹ, וַדַּאי כָּךְ הוּא זֶה, שֶׁכָּל זְמַן שֶׁהִיא בַּגָּלוּת וְשׁוֹכֶבֶת לֶעָפָר, לֹא נִקְרֵאת שִׂמְחָה, עַד שֶׁהַקָּדוֹשׁ-בָּרוּךְ-הוּא יָבא אֵלֶיהָ, וִיקִימָהּ מֵהֶעָפָר וְיֹאמַר, (שם נב) הִתְנַעֲרִי מֵעָפָר קוּמִי וְגוֹ', (שם ס) קוּמִי אוֹרִי וְגוֹ', וְיִתְחַבְּרוּ כְאֶחָד, (ויקימה מעפרה) וְאָז חֶדְוָה נִקְרֵאת, חֶדְוַת הַכֹּל, וְאָז בְּשִׂמְחָה תֵצֵאוּ וַדַּאי. אָז כַּמָּה חֲיָלוֹת יֵצְאוּ מוּל הַגְּבִירָה לְחֶדְוַת הִלּוּלַת הַמֶּלֶךְ, כְּמוֹ שֶׁנֶּאֱמַר (שם נה) הֶהָרִים וְהַגְּבָעוֹת יִפְצְחוּ וְגוֹ', וְכָתוּב (שם נב) כִּי הֹלֵךְ לִפְנֵיכֶם ה' וּמְאַסִּפְכֶם וְגוֹ'."]]],[["(במדבר ב׳:ב׳) אִישׁ עַל דִּגְלוֹ בְאוֹתוֹת. אִלֵּין אַרְבַּע מַשִּׁרְיָין דִּכְנֶסֶת יִשְׂרָאֵל, דְּאִינּוּן תְּרֵיסָר שְׁבָטִין, תְּרֵיסָר תְּחוּמִין, סְחוֹר סְחוֹר לָהּ. כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא, כְּתִיב (תהילים קכ״ב:ד׳) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ וְגוֹ'. שֶׁשָּׁם עָלוּ שְׁבָטִים, אִלֵּין י\"ב שְׁבָטִין, י\"ב תְּחוּמִין דִּלְתַתָּא.","שִׁבְטֵי יָהּ, הָא אוּקְמוּהָ בְּגִין דְּיָ\"הּ עֵדוּת לְיִשְׂרָאֵל וַדַּאי. וּבְגִין דָּא, הָראוּבֵנִי, הַשִּׁמְעוֹנִי, יָ\"הּ בְּכָל חַד וְחַד. אֲבָל וַדַּאי הָכִי הוּא, דְּהָא אִילָנָא עִלָּאָה קַדִּישָׁא, בְּהוּ אַחְתָּם בְּחוֹתָמוֹי. וְאוֹקְמוּהָ דִּכְתִּיב, (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם וּפְנֵי אַרְיֵה אֶל הַיָּמִין וְגוֹ'. דִּיּוּקְנָא דְּאָדָם אִתְכְּלִיל בְּכֻלְּהוּ, וְאַפִּין הֲווֹ לְד' סִטְרִין דְּעָלְמָא, וּמִתְפָּרְשָׁן בְּדִיּוּקְנֵיהוֹן, וְכֻלְהוֹן כְּלִילָן בֵּיהּ בְּאָדָם.","מִיכָאֵל מִימִינָא, גַּבְרִיאֵל מִשְּׂמָאלָא, אוּרִיאֵל לְקַדְמַיְיהוּ, רְפָאֵל לַאֲחוֹרַיְיהוּ, שְׁכִינְתָּא עָלַיְיהוּ. תְּרֵין מִכָּאן, וּתְרֵין מִכָּאן, וְהִיא בְּאֶמְצָעִיתָא. כְּגַוְונָא דָּא בְּאַרְעָא דִּלְתַתָּא, תְּרֵי מִכָּאן, וּתְרֵי מִכָּאן, וְיָ\"הּ בֵּינַיְיהוּ.","כֵּיוָן דְּנַטְלִין תְּרֵין דְּגָלִים, מַה כְּתִיב. וְנָסַע אֹהֶל מוֹעֵד מַחֲנֵה הַלְוִיִּם וְגוֹ'. וּלְבָתַר, אִינּוּן תְּרֵין אַחֲרָנִין ד' מַשִּׁרְיָין אִינּוּן לְד' סִטְרֵי עָלְמָא, וְאִשְׁתְּכָחוּ תְּרֵיסָר. אוּף הָכִי לְתַתָּא כְּגַוְונָא דִּלְעֵילָּא.","וְנָסַע בָּרִאשׁוֹנָה דֶּגֶל מַחֲנֵה יְהוּדָה, לָקֳבֵיל מַשִּׁרְיָיא דְּאוּרִיאֵל. וּמַחֲנֶה דִּרְאוּבֵן לָקֳבֵיל מַשִּׁרְיָיא דְּמִיכָאֵל. דָּא לַדָּרוֹם, וְדָא לְמִזְרָח. מִזְבֵּחַ הָכִי נָמֵי דְּרוֹמִית מִזְרָחִית. וּמַחֲנֵה דָּן לַצָּפוֹן. מַחֲנֵה אֶפְרַיִם יָמָה. מַחֲנֵה דָּן לָקֳבֵיל מַשִּׁרְיָיא דְּגַבְרִיאֵל. מַחֲנֶה אֶפְרַיִם לְמַעֲרָב, לָקֳבֵיל מַשִּׁרְיָיא דִּרְפָאֵל מִזְבֵּחַ הָכִי נָמֵי צְפוֹנִית מַעֲרָבִית. כֹּלָּא אָחִיד דָּא בְּדָא, עַד דְּסַלְּקָא כֹּלָּא וְאִתְאֲחָד בִּשְׁמָא קַדִּישָׁא, דְּאִיהוּ שֵׁירוּתָא דְּכֹלָּא. עִלָּאָה דְּכֹלָּא קַדִּישָׁא דְּכֹלָּא. כֹּלָּא אִתְכְּלִיל בֵּיהּ.","י' מִזְרָח הוּא שֵׁירוּתָא דִּנְהוֹרָא, אָזִיל וְשָׁאט וְאַפִּיק לְדָרוֹם. וְדָרוֹם נָפִיק וְתַלְיָיא בְּשֵׁירוּתָא דְּמִזְרָח. ה' דָּרוֹם. מִנֵּיהּ נָפִיק דָּרוֹם בְּעָלְמָא. וְעָיִיל י' בְּשֵׁירוּתָא דְּמִזְרָח, וְאַפִּיק לֵיהּ.","וּמִן ה' תַּלְיָיא דָּרוֹם וְצָפוֹן, וְהַהוּא (אד\"ג) דְּבֵינַיְיהוּ, י' מִזְרָח יָ\"הּ דָּרוֹם וְצָפוֹן תַּלְיָיאן בֵּיהּ. ו' בְּאֶמְצָעִיתָא. וְדָא הוּא בֵּן דְּכָר. בְּגִין כָּךְ אִיהוּ בֵּין צָפוֹן לְדָרוֹם. וְעַל דָּא תָּנֵינָן, מַאן דְּיָהִיב מִטָּתוֹ בֵּין צָפוֹן לְדָרוֹם, הַוְיָין לֵיהּ בָּנִים זְכָרִים. דְּהַאי בֵּן דְּכַר אִיהוּ בֵּין צָפוֹן לְדָרוֹם. ה' עִלָּאָה בָּהּ תַּלְיָא צָפוֹן וְדָרוֹם, וּבֵן דְּכָר בֵּינַיְיהוּ, בְּרָזָא דְּיו\"ה. ה' בַּתְרָאָה מַעֲרָב.","וְעַל דָּא דָּרוֹם אָחִיד מִזְרָח, דְּאִיהוּ שֵׁירוּתָא דְּשִׁמְשָׁא וְתַלְיָיא בֵּיהּ. וְעַל דָּא תָּנֵינָן, מִסִּטְרָא דְּאַבָּא אָחִיד וְתַלְיָיא חֶסֶד עִלָּאָה. מִסִּטְרָא דְּאִימָא תַּלְיָיא גְּבוּרָה. כְּגַוְונָא דָּא אָחִיד כֹּלָּא דָּא בְּדָא.","זַוְויָין דְּמַדְבְּחָא הָכִי נָמֵי אִסְתַּחֲרָן, וּבָא לוֹ לְקֶרֶן דְּרוֹמִית מִזְרָחִית. דְּדָרוֹם תּוּקְפֵּיהּ בְּמִזְרָח, דְּאִיהוּ שֵׁירוּתָא דְּשִׁמְשָׁא, וְתּוּקְפָּא דְּשִׁמְשָׁא לָא שַׁרְיָיא אֶלָּא בְּשֵׁירוּתָא. מִזְרָחִית צְפוֹנִית. כֵּיוָן דְּדָרוֹם נָטִיל תּוּקְפֵּיהּ דְּמִזְרָח, הוּא אַנְהִיר לַצָּפוֹן וְצָפוֹן אִתְכְּלִיל בְּדָרוֹם, דְּהָא שְׂמָאלָא אִתְכְּלִיל בִּימִינָא.","צְפוֹנִית מַעֲרָבִית, דְּהָא מַעֲרָב דְּאִיהִי בְּה' בַּתְרָאָה, נַטְלָא מִצָּפוֹן. וְעַל דָּא צָפוֹן אָזִיל לְמַעֲרָב. מַעֲרָבִית דְּרוֹמִית, הִיא אַזְלָא (ס\"א לאתחבקא) לְאִתְחַבְּרָא בְּדָרוֹם, כְּמָה דְּדָרוֹם תַּלְיָיא בְּמִזְרָח, וְתוּקְפֵּיהּ אָזִיל בְּשֵׁרוּתָא. הָכִי נָמֵי מַעֲרָב, אַזְלָא (ס\"א לאתחבקא) לְאִתְאַחֲדָא בְּדָרוֹם, הֲדָא הוּא דִכְתִיב, (שיר השירים ב׳:ו׳) וִימִינוֹ תְּחַבְּקֵנִי. יְמִינָא דָּא הוּא דָּרוֹם. בְּגִין כָּךְ יַנְקָא מִתְּרֵין סִטְרִין, מִצָּפוֹן וּמִדָּרוֹם. הֲדָא הוּא דִכְתִיב, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. שְׂמֹאלוֹ דָּא הוּא צָפוֹן, וִימִינוֹ דָּא הוּא דָּרוֹם.","וְרָזָא דָּא אוֹלִיפְנָא, קוּדְשָׁא בְּרִיךְ הוּא יָהִיב מִטָּתֵיהּ, בֵּין צָפוֹן לְדָרוֹם. וַאֲחִידַת לְהַאי בֵּן ודַּאי. וְעַל דָּא אִית לְהוּ לִבְנֵי נָשָׁא לְמֵיהַב מִטָּתַיְיהוּ בֵּין צָפוֹן לְדָרוֹם. וְהָכִי אוֹלִיף לִי אַבָּא. דְּיַהֲבִין לְהוּ בְּנִין דִּכְרִין. דְּהָא אִיהוּ אִתְכְּוָון כְּלַפֵּי מְהֵימְנוּתָא שְׁלֵימָא עִלָּאָה, בִּשְׁלֵימוּתָא דְּכֹלָּא. לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ בֵּין צָפוֹן לְדָרוֹם, וּלְגַבֵּי כְּנֶסֶת יִשְׂרָאֵל דְאַנְהִירִין (ס\"א דאיהי) בֵּין צָפוֹן לְדָרוֹם. וַדַּאי יֶהֶוְוָן לֵיהּ בְּנִין דִּכְרִין."],[[0,"איש על דגלו באותות",": אלו הם ארבע מחנות של כנסת ישראל, שה\"ס חו\"ג תו\"מ, והם מיכאל גבריאל אוריאל רפאל, שהם י\"ב שבטים וי\"ב גבולים סביב סביב לה. כי בכל אחד מחו\"ג תו\"מ יש ג' קוין, והם י\"ב. הכל הוא כעין שלמעלה כמו י\"ב גבולים דז\"א. כתוב, ששם עלו שבטים שבטי יה וגו'. \u0003ששם עלו שבטים,\u0004 אלו הם י\"ב שבטים, שהם י\"ב גבולים שלמטה במלכות. שעלו לי\"ב גבולים דז\"א. (כמ\"ש לעיל פקודי אות קע\"ד)."],[1,"שבטי יה:","העמידוהו, בשביל ש \u0003י\"ה\u0004 שה\"ס חו\"ב, עדות לישראל ודאי (כנ\"ל פקודי אות כ\"א). ומשום זה כתוב \u0003ה\u0004 ראובני \u0003ה\u0004 שמעוני שיש \u0003י\"ה\u0004 בכל אחד ואחד. \u0003ה'\u0004 מתחלה ו \u0003י'\u0004 בסוף. אבל ודאי כך הוא, כי אילן העליון הקדוש, שהוא שם הויה, חתם אותם בחותם שלו, והעמידוהו שכתוב, ודמות פניהם פני אדם ופני אריה אל הימין וגו'. אשר דמות אדם, שהיא מלכות, כלולה בכולם וד' פנים היו לד' רוחות העולם, ונבדלים בצורתם, דהיינו אריה שור נשר, וכולן היו כלולות באדם. שה\"ס מלכות. כי אריה שור נשר הם חג\"ת, ופני אדם הם מלכות, המקבלת מכולם וכולם כלולים בה."],[2,"מיכאל מימינא גבריאל","וכו': מיכאל לימין שהוא דרום, גבריאל משמאל, לצפון, אוריאל לפניהם, שהוא מזרח, רפאל לאחוריהם, שהוא מערב, השכינה עליהם. שנים מכאן, מדרום וצפון, ושנים מכאן, ממזרח וממערב, והיא המלכות, באמצע. כעין זה בארץ שלמטה, בדגלים, שנים מכאן שהם דגל מחנה יהודה ודגל מחנה ראובן. ושנים מכאן, שהם דגל מחנה אפרים ודגל מחנה דן. וי\"ה באמצע, שה\"ס ב' לוחות העדות שבארון, שהלך באמצעם. והשינוי שיש כאן בדגלים, שמזרח הולך תחילה, שהוא ת\"ת, יתבאר להלאה (באות ל\"ה)."],[3,"כיון דנטלין תרין","וכו': כיון שנסעו ב' דגלים, של יהודה ושל ראובן, מה כתוב, ונסע אהל מועד מחנה הלוים וגו'. ולאחר כך אלו שני דגלים אחרים, של אפרים ושל דן, שהם ד' מחנות לד' רוחות העולם, מזרח דרום מערב צפון. ונמצאים י\"ג. כי כל דגל כולל ג' שבטים, כי למטה הוא גם כן כמו למעלה. במלכות (כמ\"ש באות כ\"ז)."],[4,"ונסע בראשונה","וכו': ובתחילה נסע דגל מחנה יהודה, שהוא כנגד המחנה של אוריאל. ואח\"כ דגל מחנה ראובן כנגד המחנה של מיכאל. זה ראובן לדרום, שהוא חסד, וזה, יהודה, למזרח, שהוא ת\"ת. וההזאה שעל המזבח היתה ג\"כ תחילה בקרן דרומית מזרחית. שהם חסד ות\"ת. ומחנה דן לצפון, ומחנה אפרים ימה. מחנה דן לצפון, הוא כנגד המחנה של גבריאל. ומחנה אפרים למערב, הוא כנגד המחנה של רפאל. וההזאה שעל המזבח היתה ג\"כ צפונית מערבית. שה\"ס גבורה ומלכות. הכל אחוז זה בזה עד שהכל עולה ומתאחד בשם הקדוש \u0003הויה,\u0004 שהוא תחלת הכל, דהיינו \u0003י'\u0004 דהויה שהוא חכמה עליון על הכל \u0003ה'\u0004 ראשונה, שהיא בינה. קדושת הכל \u0003ו'\u0004 שהוא ת\"ת. הכל נכלל בו, היא \u0003ה'\u0004 אחרונה שהיא מלכות."],[4,"","פירוש, ארבע הדגלים שבארבע רוחות הם כנגד ארבעה מחנות שכינה, אוריאל, מיכאל, רפאל, גבריאל, שדגל מחנה יהודה הוא במזרח שהוא ת\"ת, וקו האמצעי. ואחריו ראובן בדרום שהוא חסד וקו ימין. ואחריו אפרים במערב, שהוא מלכות. ואחריו דן בצפון, שהוא גבורה וקו שמאל. וכל דגל כולל ג' שבטים, הרי הם י\"ב. כנגד י\"ב גבולים שבמלכות, הנחתמים מי\"ב גבולים שבהויה. וז\"ש \u0003עד דסלקא כלא ואתאחד בשמא קדישא,\u0004 דהיינו הוי\"ה."],[5,"י' מזרח הוא","וכו': ה \u0003י'\u0004 דהויה דז\"א, היא מזרח, והיא התחלת האור. הולך ומשוטט ומוציא הדרום, שהוא חסד. ודרום יוצא ותלוי בתחילת המזרח, שהוא \u0003י'\u0004 דהויה, שהוא חכמה. \u0003ה'\u0004 דהויה דז\"א היא דרום. כלומר, שממנה יוצא הדרום בעולם. כי \u0003ה'\u0004 היא בינה ומבינה נמשך החסד, שהוא דרום. אלא ה \u0003י',\u0004 שהיא חכמה, נכנסת בתחילת המזרח, ומוציאה את החסד, והוא משתלשל ויוצא דרך הבינה לז\"א."],[6,"ומן ה' תלייא","וכו': ומן \u0003ה'\u0004 תלויה דרום וצפון ואותו שביניהם, שהוא קו האמצעי המיחדם. \u0003י'\u0004 מזרח. \u0003י\"ה\u0004, דרום וצפון תלוים בהם, דרום מן \u0003י',\u0004 וצפון מן \u0003ה', ו'\u0004 באמצע, המיחדם. וזה הוא בן זכר, דהיינו ת\"ת שהוא בן \u0003י\"ה\u0004, משום זה הוא בין צפון לדרום. וע\"כ למדנו, מי שנותן מטתו בין צפון לדרום יהיו לו בנים זכרים. כי בן זכר הזה שהוא ת\"ת, הוא בין צפון לדרום, כי \u0003ה'\u0004 עלאה, בינה, בה תלוים צפון ודרום, שהם ב' הקוין שבה, ובן הזכר שהוא ת\"ת הוא ביניהם, המיחדם, בסוד \u0003יו\"ה\u0004. אשר \u0003י'\u0004 היא קו ימין, בדרום. \u0003ו'\u0004 היא קו האמצעי, שימינו לדרום, ושמאלו לצפון. \u0003ה'\u0004 היא קו שמאל, בצפון. \u0003ה'\u0004 אחרונה דהויה, היא מערב. דהיינו מלכות."],[7,"וע\"ד דרום אחיד","וכו': וע\"כ דרום נאחז במזרח, שהיא התחלת השמש, ותלוי בו. וע\"כ למדנו, מצד אבא, שהוא \u0003י',\u0004 נאחז ותלוי חסד עליון. מצד אמא שהיא \u0003ה',\u0004 תלויה גבורה. כעין זה נאחז הכל זה בזה."],[8,"זוויין דמדבחא ה\"נ","וכו': הקרנות של המזבח מסובבים גם כן כך, ובא לו לקרן דרומית מזרחית, כי הדרום חיזוקו היא במזרח, בקו האמצעי שהוא תחלת השמש, וכחו של השמש אינו שורה אלא בתחילתו. ואח\"כ הוא בא לקרן מזרחית צפונית. כי אחר שהדרום, שהוא חסד, קבל חזקתו של המזרח, דהיינו אחר שקו אמצעי יחד דרום וצפון, האיר המזרח לצפון, והצפון נכלל בדרום כי השמאל נכלל בימין, על ידי קו האמצעי."],[9,"צפונית מערבית","וכו': ואח\"כ בא לו לקרן צפונית מערבית, כי המערב שהוא בה' אחרונה, דהיינו מלכות, נוטל מצפון. וע\"כ הצפון הולך למערב, כי המלכות נבנית מקו שמאל. ואח\"כ בא לו לקרן מערבית דרומית, שהמלכות הולכת להתחבר בדרום, דהיינו להלביש החכמה בחסדים, כמו שהדרום תלוי במזרח, בקו האמצעי, וע\"כ החיזוק שלו, שהוא מזרח, הולך תחלה, אף המערב כך הוא הולך להתאחז בדרום, והדרום שהוא החיזוק שלו, הולך תחלה. ז\"ש וימינו תחבקני, ימין זה הוא דרום. משום זה היא יונקת מב' הצדדים מצפון ומדרום. משמאל ומימין. ז\"ש שמאלו תחת לראשי וימינו תחבקני שמאלו זהו צפון וימינו זהו דרום."],[9,"","ביאור המאמר. כי הוקשה לו להזהר למה נשתנה כאן בדגלים, סדר המדרגות מבכל המקומות, אשר יהודה שבמזרח שהוא ת\"ת הלך בראש כולם, ואחריו ראובן שבדרום שהוא חסד, ואחריו אפרים שבמערב שהוא מלכות, ואחריו דן שבצפון שהוא גבורה. ולמה לא הלכו לפי סדר המדרגה, תחילה ראובן שהוא חסד, ואחריו דן שבצפון, שהוא גבורה, ואחריו יהודה שבמזרח שהוא ת\"ת, ואחריו אפרים שבמערב, שהוא מלכות. וכדי לתרץ את זה, מביא כל המאמר שלפנינו."],[9,"","והענין הוא. כי סוד הנסיעות שבמדבר היו לגלות הארת החכמה, כי אין הארת החכמה מתגלה אלא בזמן הנסיעה בלבד, שה\"ס גילוי הקוין בזה אחר זה, וכשגמרו נסיעתם, או הם נחים, והארת החכמה אינה מתגלה יותר. (כנ\"ל בשלח דף ל\"ט ד\"ה וג'). שזסו\"ה, ויהי בנסוע הארון ויאמר משה קומה ה' ויפוצו אויביך וגו'. כי גילוי הארת חכמה ה\"ס קימה, ועם גילויה נפוצים כל הקליפות, כי הארת החכמה מבריחה אותם. אבל כשנגמרה הנסיעה, נאמר, ובנחה יאמר שובה ה' רבבות אלפי ישראל. שה\"ס הארת החסדים המכונים \u0003רבבות,\u0004 אלא מתוך שנקלטה בהם הארת החכמה מזמן הנסיעה, הם מכונים \u0003רבבות אלפי,\u0004 כי אלפים רומזים על הארת חכמה, בסו\"ה ואאלפך חכמה. ולפי שהנסיעות האלו היו במדבר שהוא מקום החצונים, היו צריכים לשמירה יתרה, שלא יינקו מהם החצונים. ונודע שכל זמן שלא נגלה קו האמצעי יש יניקה לדינים וחצונים הן בקו ימין והן בקו שמאל, כי אז יש מחלוקת ביניהם, והימין הוא בבחינת ו\"ק בחסרון ג\"ר, והשמאל הוא בחכמה בלי חסדים שהוא חשך וכל החצונים והדינים נמשכים ממנו. וע\"כ לא נגלו מקודם הימין והשמאל, שהם דרום צפון, אלא האמצעי נגלה תחילה, בבחינת מה שהוא מיחד הדרום והצפון זה בזה ומשלים את שניהם, שקו הימין שהוא חסדים קונה ג\"ר מהתכללות השמאל, וקו השמאל שהוא חכמה קונה חסדים מהתכללות הימין, ואז יכול להאיר, ומבריח כל החצונים. אמנם הכרעה זו של קו האמצעי נעשתה בין ב' קוין ימין שמאל של הבינה, שת\"ת עלה אל הבינה, ויחד אותם בסוד הדעת, ואז יצאו ג' קוין, ימין שמאל ואמצע בבינה, שהם נקראים שם חכמה בינה דעת. וכיון \u0003דתלת מחד נפקי,\u0004 שיצאו ג' קוין חב\"ד בבינה מן אחד שהוא ת\"ת, ע\"כ \u0003חד בתלת קיימא,\u0004 זכה הת\"ת ג\"כ בג' קוין אלו (כנ\"ל ב\"א דף רפ\"ז ד\"ה תלת ע\"ש) ומטעם הזה \u0003הלך תחילה דגל מחנה יהודה,\u0004 במזרח, שה\"ס קו האמצעי, שהתחלתו היא בדעת הנעלם. ביחוד ימין ושמאל דאו\"א. ואח\"כ ביחוד ימין ושמאל דישסו\"ת שה\"ס דעת המגולה המיחד ימין ושמאל, שלא תהיה בהם אחיזה לדינים וחצונים. ואחריו יצא החסד. שהוא עיקר פעולת קו האמצעי, להכריע את הימין ולהמשיך החסדים, להלביש החכמה שבשמאל, שהיתה חשך מחסרון חסדים. וכיון שגילה החסדים שה\"ס נסיעת \u0003דגל מחנה ראובן\u0004 יצאה אחריהם המלכות להכלל בימין, כי המלכות נבנית תחילה מחכמה בלי חסדים והיתה חשך, ע\"כ אחר שנגלו החסדים עם נסיעת מחנה ראובן בדרום, יצאה אחריו המלכות, שהיא \u0003דגל מחנה אפרים,\u0004 להתלבש בחסדים. וכיון שעיקר בנינה של המלכות הוא משמאל, ע\"כ הלך אחריה \u0003דגל מחנה דן\u0004 שהוא משמאל. ולפיכך הקדים המזרח לדרום, משום שהמזרח מחזק את הדרום ומיחדו עם הצפון, וכיון שהוא המשלים את הדרום הלך תחילה. ולפיכך הקדים המערב את הצפון, כדי שיהיו החסדים של דרום לפניו, והחכמה של צפון לאחריו. כי כן היא המלכות בבחינת גדלותה, שחסדים הם בחינת פנים שלה, וחכמה בבחינת אחורים שלה. ולפיכך הלך דרום לפניה, והצפון לאחריה."],[9,"","ובדברים אלו מתבארים כל דברי המאמר. כי תחלה מבאר בדרך כלל, שי\"ב גבולים שבמלכות נחתמים מי\"ב גבולים דהויה דז\"א, וז\"ש (באות כ\"ז) \u0003אלין ארבע משריין\u0004 וכו' \u0003כלא כגוונא דלעילא\u0004 וכו' שי\"ב גבולים שבמלכות הם כעין שלמעלה בז\"א. דהיינו שהם חו\"ג תו\"מ שבכל אחת ג' קוין וכו'. ואח\"כ (באות כ\"ט) מבאר בפרטות שה\"ס ד' החיות וד' המלאכים שהם מרכבה להשכינה, דהיינו שעליהם מתגלה הארת החכמה שבמלכות. ואח\"כ (באות ל') מבאר היחס מד' דגלים שלמטה, להמרכבה של המלכות שלמעלה, ואח\"כ (באות ל\"א) מבאר סדר הלוכם של הדגלים ביחס המרכבה של המלכות, שמזרח ודרום הולכים תחלה ואח\"כ מערב וצפון. ואח\"כ (מאות ל\"ב והלאה) מתרץ את השינוי הזה שנעשה בדגלים, שהסדר היה, מזרח דרום מערב צפון, ולא כדרכו תמיד, דרום צפון מזרח מערב. ואומר, שדבר זה נמשך משורש י\"ב גבולים שבז\"א שה\"ס הוי\"ה, ששורשו הוא ת\"ת שעלה והכריע בין ב' קוי הבינה ונעשה שם דעת, כנ\"ל בסוד תלת מחד נפקי. ות\"ת הזה שנעשה לדעת נקרא ג\"כ \u0003מזרח,\u0004 להיותו מעיקרו ת\"ת."],[9,"","וכבר ידעת ההפרש בין חכמה דימין לחכמה שבשמאל, שהחכמה דימין היא עצם החכמה הנמשכת מחכמה סתימאה, שהיא בחינת חכמה דע\"ס דאור ישר. אבל חכמה זו נסתמה ואינה מגיעה לעולמות כלל. ודכר ונוקבא שבחכמה זו נקראים או\"א עלאין. וה\"ס \u0003י'\u0004 דהויה. וכל הארת החכמה המתפשטת בעולמות היא רק מבינה דע\"ס דאור ישר השבה להיות חכמה, שדכר ונוקבא שלה נקראים ישסו\"ת, וה\"ס \u0003ה'\u0004 דהויה (עי' לעיל ב\"א דף רנ\"א ד\"ה נחית). ובדרך כלל נבחנים י\"ה דהויה לימין ושמאל, והו' שה\"ס קו אמצעי מכריע ומיחד אותם, אמנם בדרך פרט, כשעולה הת\"ת להכריע בין י\"ה, עולה תחילה ליחד ימין ושמאל שבי' דהויה, שה\"ס או\"א עלאין. ומיחודם זה אין החכמה נמשכת כנ\"ל, אלא חסד לבד. ולפיכך מכונה דעת זו המיחדת או\"א עלאין בשם \u0003דעת הנעלם.\u0004 ואח\"כ בא ומיחד ימין ושמאל שב \u0003ה'\u0004 דהויה, שה\"ס ישסו\"ת, שה\"ס בינה השבה לחכמה, וע\"י הדעת המיחדת אותם נמשכים חסדים וחכמה ביחד, כי בהם מתגלה החכמה, ולפיכך נקראת דעת זו \u0003דעת המגולה.\u0004"],[9,"","וזה אמרו (באות ל\"ב) \u0003י' מזרח,\u0004 שהי' דהויה שה\"ס או\"א עלאין, מאירים על ידי המזרח, שה\"ס דעת הנעלם המיחדם, הוא \u0003שירותא דנהורא,\u0004 כי תחילת האור היוצא על ידי יחוד הדעת הוא בי' דהויה כנ\"ל. \u0003אזיל ושאט ואפיק לדרום,\u0004 שמזווגם זה יוצא הדרום שה\"ס החסד, משא\"כ הצפון, שה\"ס חכמה, נעלם כאן. כנ\"ל. וז\"ש \u0003ודרום נפיק ותלייא בשירותא דמזרח,\u0004 שירותא דמזרח הוא דעת הנעלם. המתחיל מאו\"א עלאין, וע\"י זווגו יוצא החסד לבד. אמנם החסד אינו יוצא ישר מאו\"א עלאין לז\"א, אלא \u0003ה' דרום,\u0004 כלומר, \u0003מניה נפיק דרום בעלמא,\u0004 כי החסד יוצא מבינה לז\"א, אלא \u0003ועייל י' בשירותא דמזרח,\u0004 שאו\"א שה\"ס \u0003י'\u0004 נכנסים ומזדווגים על ידי דעת הנעלם, הנקרא שירותא דמזרח, \u0003ואפיק ליה,\u0004 ומוציא החסד לז\"א, דרך \u0003ה'\u0004 דהויה, שהיא בינה. כי כל מדרגה לא תוכל לקבל משהו אלא ממדרגה הסמוכה לה, ולא מעלי עליונה. ונתבאר, שהחסד. שה\"ס דרום וקו ימין מתגלה ע\"י שירותא דמזרח. שהוא \u0003דעת הנעלם\u0004 שב \u0003י'\u0004 דהויה. ונמצא שהיחוד דג' קוין לגלות חכמה וחסדים, אינו נוהג באו\"א עלאין, שהוא \u0003י'\u0004 דהויה, שהרי אינו מגלה שם רק קו ימין בלבד. אלא בישסו\"ת מתגלה היחוד דג' קוין כנ\"ל. וז\"ש (באות ל\"ג), \u0003ומן ה' תלייא דרום וצפון וההוא דבינייהו,\u0004 שמן \u0003ה'\u0004 דהויה, שה\"ס בינה וישסו\"ת מתגלים ג' קוין שהם דרום צפון ואמצעי, שקו אמצעי כאן הוא \u0003דעת המגולה,\u0004 וממשיך חכמה וחסדים יחדיו, ע\"י יחוד צפון ודרום זה בזה."],[9,"","ונתבאר שהיחוד ע\"י שירותא דמזרח, המתגלה ב \u0003י'\u0004 דהויה, אינה מגלה רק קו ימין בלבד, שהוא חסד, דרום. והיחוד הנעשה ב \u0003ה'\u0004 דהויה ע\"י דעת המגולה מגלה גם הצפון שה\"ס קו השמאל, שה\"ס חכמה. וז\"ש, \u0003י' מזרח,\u0004 ה \u0003י'\u0004 מגלה החסד בכח מזרח, שהוא דעת הנעלם. ונמצא \u0003י\"ה, דרום וצפון. תלייאן ביה.\u0004 שמזווג ה \u0003י'\u0004 תלוי החסד, שהוא קו ימין, והוא מקור החסדים, אבל קו שמאל נעלם בו. ומזווג ה \u0003ה'\u0004 מתגלה קו השמאל שה\"ס צפון. כי בו יש גילוי חכמה דשמאל, ונמצא שהצפון תלוי ב \u0003ה',\u0004 ומבחינה זו נבחנים או\"א שהם קו ימין, וישסו\"ת שהם קו שמאל, שה\"ס י\"ה, וה \u0003ו' באמצעיתא,\u0004 שה \u0003ו'\u0004 דהויה מזווגת אותם זה בזה. וז\"ש (באות ל\"ד) \u0003וע\"ד, דרום אחיד מזרח, דאיהו שירותא דשמשא,\u0004 שדרום שה\"ס חסד, אחוז במזרח ותלוי בו כמו ענף בשורשו. כי דעת הנעלם, שהוא שירותא דשמשא, שעקרו הוא ת\"ת הנקרא שמש ומזרח, אלא בסוד עליתו לי\"ה נעשה דעת. ובסוד התחלת הדעת שהוא באו\"א עלאין נעשה שורש לגילוי החסד, שעל ידו מזדווגים או\"א עלאין ומוציאים החסד כנ\"ל. ובזה מובן למה הלך דגל מחנה יהודה שבמזרח, שה\"ס ת\"ת, קודם דגל מחנה ראובן שבדרום, שה\"ס החסד. והיינו כאמור, משום שהמזרח הזה, ה\"ס שירותא דמזרח, שהוא דעת הנעלם, שהוא השורש של גילוי החסד, והחסד שה\"ס דרום הוא ענף שלו. וע\"כ הלך השורש תחלה ואח\"כ הענף, וז\"ש, \u0003וע\"ד תנינן מסטרא דאבא,\u0004 שה\"ס \u0003י'\u0004 דהויה, \u0003אחיד ותליא חסד עלאה,\u0004 כי מזווגם יוצא החסד. שה\"ס קו ימין, \u0003ומסטרא דאמא תליא גבורה,\u0004 שמזווגם מתתקן ומתגלה קו שמאל, שהוא גבורה."],[9,"","ומביא דוגמא מהזאות שעל המזבח. וז\"ש, (באות ל\"ה) שבתחילה מקדים הקרן של דרומית מזרחית. משום \u0003דדרום תוקפיה במזרח\u0004 שהחיזוק של דרום, שהוא חסד, הוא במזרח, שהוא ת\"ת. \u0003דאיהו שירותא דשמשא,\u0004 שהוא התחלת השמש, דהיינו דעת הנעלם שע\"י זווגו מתגלה אור החסד, \u0003ותוקפא דשמשא לא שריא אלא בשרותא,\u0004 שעיקר כח קו האמצעי, שנקרא שמש, נמצא בהתחלתו, כשהוא בסוד הדעת המיחד או\"א עלאין, להמשיך אור החסד. ואח\"כ, \u0003מזרחית צפונית, כיון דדרום נטיל תוקפיה דמזרח,\u0004 אחר שהדרום לקח חיזוקו מן המזרח, דהיינו שנתגלה על ידו בסוד היחוד דדעת הנעלם ב \u0003י'\u0004 דהויה, \u0003אנהיר לצפון,\u0004 מאיר המזרח, לגלות הצפון שה\"ס השמאל, דהיינו שהדעת שה\"ס המזרח, בא ומיחד ימין ושמאל שבה' דהויה שה\"ס ישסו\"ת, שמיחוד הזה מתגלה ומאיר הצפון. כנ\"ל. בסוד דעת הנגלה. \u0003וצפון אתכליל בדרום.\u0004 שע\"י המזרח שה\"ס דעת הנגלה נכללים ב' הקוין זה בזה, וחכמה דשמאל מתלבשת בחסדים דימין. \u0003ואח\"כ צפונית מערבית, דהא מערב דאיהו, בה' בתראה נטלא מצפון.\u0004 שהמלכות שהיא מערב נבנית בעיקר מקו שמאל. ואח\"כ, \u0003מערבית דרומית היא אזלא לאתחברא בדרום,\u0004 כי החכמה שבה צריכה להתלבש בחסדים, שהוא דרום. וע\"כ המערב מקבל מן הדרום. ונמצא עכשיו שהמערב, שה\"ס המלכות \u0003פניה אל הדרום,\u0004 בסוד הזאה אחרונה דמערבית דרומית, כדי שמלכות תקבל חסד מן הדרום. \u0003ואחוריה אל הצפון,\u0004 כדי שתקבל הארת החכמה שהוא בצפון. והרי זה דומה לנסיעת הדגלים, שדגל מחנה אפרים שבמערב, שהיא מלכות, פניה לדרום, כי נוסע אחר דגל מחנה ראובן שבדרום, כדי לקבל ממנו חסד, \u0003ולאחורי\u0004 הדגל של המלכות נוסע דגל מחנה דן שבצפון, שהוא גבורה וקו שמאל, שהמלכות מקבלת ממנו חכמה. ונמצא דגל מחנה אפרים שבמערב, \u0003פניו לדרום ואחוריו לצפון,\u0004 כנ\"ל בהזאות המזבח. והטעם הוא כי אין המלכות מקבלת מצפון שהוא קו שמאל אלא בכלים דאחורים שלה. ובכלים דפנים הוא מקבלת חסדים מקו ימין (כמ\"ש לעיל ויקהל דף ל' ד\"ה פירוש)."],[9,"","והנה נתבאר היטב טעם הליכת הדגלים שהיו מזרח תחילה, שה\"ס דעת הנעלם שה\"ס שירותא דנהורא, שהוא שורש לאור החסד הנגלה מאו\"א, וע\"כ הולך אחריו הדרום שהוא ענף שלו, ואחריו המערב, שהוא המלכות שפניה צריכים להיות לדרום, ואחריו הצפון, שאחוריה של המלכות צריכים להיות לצפון. בסו\"ה שמאלו \u0003תחת\u0004 לראשי וימינו תחבקני, ותחת בכל מקום, פירושו אחורים."],[10,"ורזא דא אוליפנא","וכו': וסוד זה למדתי, שהקב\"ה נותן מטתו בין צפון לדרום, שמטתו, ה\"ס המלכות. ונאחזת בבן הזה ודאי, שהוא ז\"א, שהוא שם בין דרום לצפון. וע\"כ יש לבני אדם לתת מטתם בין צפון לדרום, שימין המטה יהיה לדרום, ושמאל המטה לצפון. כמו עמידת ז\"א בין דרום לצפון (כנ\"ל באות ל\"ג) וכך לימד אותי אבי, שנותנים להם בנים זכרים, משום שהוא נתכוון כלפי אמונה השלמה העליונה בשלמות הכל, דהיינו אל הקב\"ה שהוא בין צפון לדרום, ואל כנסת ישראל, שהיא המלכות, שנקראת מטה, שהיא בין צפון לדרום, ודאי יהיו לו בנים זכרים."]],[[0,"","אִישׁ עַל דִּגְלוֹ בְאֹתֹת - אֵלּוּ אַרְבַּע מַחֲנוֹת שֶׁל כְּנֶסֶת יִשְׂרָאֵל, שֶׁהֵם שְׁנֵים עָשָׂר שְׁבָטִים, שְׁנֵים עָשָׂר תְּחוּמִים סָבִיב סָבִיב לָהּ. הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה, כָּתוּב (תהלים קכב) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ וְגוֹ'. שֶׁשָּׁם עָלוּ שְׁבָטִים - אֵלּוּ שְׁנֵים עָשָׂר שְׁבָטִים, שְׁנֵים עָשָׂר תְּחוּמִים שֶׁלְּמַטָּה."],[1,"","שִׁבְטֵי יָהּ - הֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם שֶׁיָּ\"הּ עֵדוּת לְיִשְׂרָאֵל וַדַּאי. וְלָכֵן (במדבר כו) הָראוּבֵנִי, הַשִּׁמְעוֹנִי, יָ\"הּ בְּכָל אֶחָד וְאֶחָד. אֲבָל וַדַּאי כָּךְ הוּא, שֶׁהֲרֵי הָעֵץ הָעֶלְיוֹן הַקָּדוֹשׁ, בּוֹ חוֹתֵם בְּחוֹתָמוֹ. וּפֵרְשׁוּהָ שֶׁכָּתוּב, (יחזקאל א) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם וּפְנֵי אַרְיֵה אֶל הַיָּמִין וְגוֹ'. דְּמוּת אָדָם נִכְלֶלֶת בְּכֻלָּם, וְהַפָּנִים הָיוּ לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְנִפְרָדִים בִּדְמֻיּוֹתֵיהֶם, וְכֻלָּם כְּלוּלִים בּוֹ בָּאָדָם."],[2,"","מִיכָאֵל מִיָּמִין, גַּבְרִיאֵל מִשְּׂמֹאל, אוּרִיאֵל לִפְנֵיהֶם, רְפָאֵל לַאֲחוֹרֵיהֶם, הַשְּׁכִינָה מֵעֲלֵיהֶם. שְׁנַיִם מִכָּאן, וּשְׁנַיִם מִכָּאן, וְהִיא בָּאֶמְצַע. כְּמוֹ זֶה בָּאָרֶץ שֶׁלְּמַטָּה - שְׁנַיִם מִכָּאן, וּשְׁנַיִם מִכָּאן, וְיָ\"הּ בֵּינֵיהֶם."],[3,"","כֵּיוָן שֶׁלּוֹקְחִים שְׁנֵי דְגָלִים, מַה כָּתוּב? וְנָסַע אֹהֶל מוֹעֵד מַחֲנֵה הַלְוִיִּם וְגוֹ'. וְאַחַר כָּךְ אוֹתָם שְׁנַיִם אֲחֵרִים אַרְבַּע מַחֲנוֹת הֵן לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְנִמְצָאִים שְׁנֵים עָשָׂר. אַף כָּךְ לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה."],[4,"","וְנָסַע בָּרִאשׁוֹנָה דֶּגֶל מַחֲנֵה יְהוּדָה מוּל מַחֲנֵה אוּרִיאֵל. וּמַחֲנֵה רְאוּבֵן מוּל מַחֲנֵה מִיכָאֵל. זֶה לַדָּרוֹם, וְזֶה לַמִּזְרָח. כָּךְ גַּם הַמִּזְבֵּחַ דְּרוֹמִית מִזְרָחִית. וּמַחֲנֵה דָן לַצָּפוֹן. מַחֲנֵה אֶפְרַיִם יָמָּה. מַחֲנֵה דָן מוּל מַחֲנֵה גַבְרִיאֵל. מַחֲנֵה אֶפְרַיִם לַמַּעֲרָב מוּל מַחֲנֵה רְפָאֵל. כָּךְ גַּם הַמִּזְבֵּחַ צְפוֹנִית מַעֲרָבִית. הַכֹּל אָחוּז זֶה בָּזֶה, עַד שֶׁהַכֹּל עוֹלֶה וְנֶאֱחָז בַּשֵּׁם הַקָּדוֹשׁ, שֶׁהוּא הָרֵאשִׁית שֶׁל הַכֹּל, הָעֶלְיוֹן שֶׁל הַכֹּל, הַקָּדוֹשׁ שֶׁל הַכֹּל, הַכֹּל כָּלוּל בּוֹ."],[5,"","י' מִזְרָח הוּא רֵאשִׁית הָאוֹר, הוֹלֵךְ וּמְשׁוֹטֵט וּמוֹצִיא לַדָּרוֹם, וְדָרוֹם יוֹצֵא וְתָלוּי בְּרֵאשִׁית הַמִּזְרָח. ה' דָּרוֹם, מִמֶּנּוּ יוֹצֵא דָרוֹם בָּעוֹלָם. וְנִכְנָס י' בְּרֵאשִׁית הַמִּזְרָח, וּמוֹצִיא אוֹתוֹ."],[6,"","וּמֵה' תְּלוּיִים דָּרוֹם וְצָפוֹן, וְאוֹתוֹ שֶׁבֵּינֵיהֶם, י' מִזְרָח, יָ\"הּ - דָּרוֹם וְצָפוֹן תְּלוּיִים בּוֹ. ו' בָּאֶמְצַע, וְזֶה הוּא בֵּן זָכָר. בִּגְלַל זֶה הוּא בֵּין צָפוֹן לְדָרוֹם. וְעַל זֶה שָׁנִינוּ, מִי שֶׁנּוֹתֵן מִטָּתוֹ בֵּין צָפוֹן לְדָרוֹם, יִהְיוּ לוֹ בָּנִים זְכָרִים. שֶׁהֲרֵי בֵּן זָכָר הוּא בֵּין צָפוֹן לְדָרוֹם. ה' עֶלְיוֹנָה, בָּהּ תָּלוּי צָפוֹן וְדָרוֹם, וּבֵן זָכָר בֵּינֵיהֶם, בְּסוֹד שֶׁל יו\"ה. ה' הָאַחֲרוֹנָה - מַעֲרָב."],[7,"","וְעַל זֶה הַדָּרוֹם אָחוּז בַּמִּזְרָח, שֶׁהוּא רֵאשִׁית הַשֶּׁמֶשׁ וְתָלוּי בּוֹ. וְעַל זֶה לָמַדְנוּ, מִצַּד אַבָּא אָחוּז וְתָלוּי הַחֶסֶד הָעֶלְיוֹן, מִצַּד הָאִמָּא תְּלוּיָה גְבוּרָה. כְּמוֹ זֶה אָחוּז הַכֹּל זֶה בָּזֶה."],[8,"","זָוִיּוֹת הַמִּזְבֵּחַ גַּם כֵּן מְסוֹבְבִים, וּבָא לוֹ לְקֶרֶן דְּרוֹמִית מִזְרָחִית. שֶׁהַדָּרוֹם כֹּחוֹ בַּמִּזְרָח, שֶׁהוּא רֵאשִׁית הַשֶּׁמֶשׁ, וְחֹזֶק הַשֶּׁמֶשׁ אֵן שׁוֹרֶה אֶלָּא בָּרֵאשִׁית. מִזְרָחִית צְפוֹנִית - כֵּיוָן שֶׁדָּרוֹם נוֹטֵל תָּקְפּוֹ שֶׁל הַמִּזְרָח, הוּא מֵאִיר לַצָּפוֹן, וְהַצָּפוֹן נִכְלָל בַּדָּרוֹם, שֶׁהֲרֵי שְׂמֹאל נִכְלָל בַּיָּמִין."],[9,"","צְפוֹנִית מַעֲרָבִית - שֶׁהֲרֵי הַמַּעֲרָב, שֶׁהוּא בְּה' אַחֲרוֹנָה, נוֹסֵעַ מֵהַצָּפוֹן. וְעַל זֶה הַצָּפוֹן נוֹסֵעַ לַמַּעֲרָב. מַעֲרָבִית דְּרוֹמִית - הִיא הוֹלֶכֶת (להתחבק) לְהִתְחַבֵּר בַּדָּרוֹם כְּמוֹ שֶׁדָּרוֹם תָּלוּי בַּמִּזְרָח, וְחָזְקוֹ הוֹלֵךְ בָּרֵאשִׁית. כָּךְ גַּם הַמַּעֲרָב הוֹלֵךְ (להתחבק) לְהֵאָחֵז בַּדָּרוֹם. זֶהוּ שֶׁכָּתוּב וִימִינוֹ תְּחַבְּקֵנִי. הַיָּמִין הַזֶּה הוּא הַדָּרוֹם, בִּגְלַל זֶה יוֹנֵק מִשְּׁנֵי צְדָדִים - מִצָּפוֹן וּמִדָּרוֹם. זֶהוּ שֶׁכָּתוּב שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. שְׂמֹאלוֹ - זֶהוּ צָפוֹן, וִימִינוֹ - זֶהוּ דָּרוֹם."],[10,"","וְסוֹד זֶה לָמַדְנוּ, שֶׁהַקָּדוֹשׁ-בָּרוּךְ-הוּא נוֹתֵן מִטָּתוֹ בֵּין צָפוֹן לְדָרוֹם, וְאוֹחֶזֶת הַבֵּן הַזֶּה בְּוַדַּאי, וְעַל זֶה יֵשׁ לִבְנֵי אָדָם לָתֵת מִטָּתָם בֵּין צָפוֹן לְדָרוֹם. וְזֶה לִמֵּד אוֹתִי אַבָּא, שֶׁנּוֹתְנִים לוֹ בָּנִים זְכָרִים. שֶׁהֲרֵי הוּא הִתְכַּוֵּן כְּלַפֵּי הָאֱמוּנָה הַשְּׁלֵמָה הָעֶלְיוֹנָה, בִּשְׁלֵמוּת הַכֹּל, לְגַבֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא בֵּין צָפוֹן לְדָרוֹם, וּלְגַבֵּי כְּנֶסֶת יִשְׂרָאֵל שֶׁמְּאִירִים (שהיא) שֶׁהִיא בֵּין צָפוֹן לְדָרוֹם - וַדַּאי יִהְיו לוֹ בָּנִים זְכָרִים."]]],[["וּבְכֹלָּא בָּעֵי לְאַחֲזָאָה עוֹבָדָא כְּגַוְונָא דִּלְעֵילָּא, וּכְמָּה דְּאַחְזֵי עוֹבָדָא לְתַתָּא, הָכִי נָמֵי אִתְּעַר לְעֵילָּא, וְאוֹקְמוּהָ. שָׁמַע רִבִּי פִּנְחָס, וּנְשָׁקֵיהּ לְרִבִּי אֶלְעָזָר, וּבָכָה וְחַיִיךְ אָמַר, זַכָּאָה חוּלָקִי בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי.","פָּתַח וְאָמַר, (תהילים כ״ז:א׳) יְיָ אוֹרִי וְיִשְׁעִי מִמִּי אִירָא וְגוֹ'. יְיָ אוֹרִי וְיִשְׁעִי, כֵּיוָן דְּבַר נָשׁ אִסְתָּכַּל (נ\"א אתאחד) בִּנְהוֹרָא דִּלְעֵילָּא, וְקוּדְשָׁא בְּרִיךְ הוּא אַנְהִיר עָלֵיהּ, לָא דָּחִיל מֵעִלָאִין וְתַתָּאִין. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ס׳:ב׳) וְעָלַיִךְ יִזְרַח יְיָ וּכְבוֹדוֹ עָלַיִךְ יֵרָאֶה. יְיָ מָעוֹז חַיַי, כֵּיוָן דְקוּדְשָׁא בְּרִיךְ הוּא אָחִיד בֵּיהּ בְּבַר נָשׁ, לָא מִסְתָּפֵי בְּהַהוּא עָלְמָא מִכָּל מָארֵיהוֹן דְּדִינִין. אוּף אֲנָא כְּהַאי גַּוְונָא, כֵּיוָן דְּאַחִידְנָא בְּאָבוּךְ וּבָךְ לָא אֶסְתַּפֵינָא בְּהַאי עָלְמָא וּבְעָלְמָא אַחֲרָא.","וְעָלָךְ כְּתִיב, (משלי כ״ג:כ״ה) יִשְׂמַח אָבִיךָ וְגוֹ'. כֵּיוָן דִּכְתִּיב יִשְׂמַח אָבִיךָ וְאִמֶּךָ, מַאי וְתָגֵל יוֹלַדְתֶּךָ, דְּהָא בְּאִמֶּךָ סַגְיָא. אֶלָּא יִשְׂמַח אָבִיךָ: דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְאִמֶּךָ: דָּא כְּנֶסֶת יִשְׂרָאֵל. וְתָגֵל יוֹלַדְתֶּךָ: יוֹלַדְתֶּךָ דִּלְתַּתָּא. רִבִּי שִׁמְעוֹן אָבוּךְ אָן חֶדְוָותָא דִּילֵיהּ. אֶלָּא קְרָא הוּא בִּלְחוֹדוֹי דִּכְתִּיב, (משלי כ״ג:כ״ד) גִּיל יָגִיל אֲבִי צַדִּיק: דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְיוֹלֵד חָכָם יִשְׂמַח בּוֹ: דָּא אָבִיךָ דִּלְתַּתָּא. דָּבָר אַחֵר, גִּיל יָגִיל אֲבִי צַדִּיק: דָּא אָבִיךָ דִּלְתַּתָּא. וְיוֹלֵד חָכָם יִשְׂמַח בּוֹ, כְּתִיב בְּתוֹסֶפֶת וָא\"ו, דָּא קוּדְשָׁא בְּרִיךְ הוּא הוּא לְעֵילָּא.","אָמַר רִבִּי אֶלְעָזָר, כְּתִיב (תהילים ל״א:ו׳) בְּיָדְךָ אַפְקִיד רוּחִי פָּדִיתָה אוֹתִי יְיָ אֵל אֱמֶת. הַאי קְרָא אִית לֵיהּ לְאִסְתַּכְּלָא בֵּיהּ, חֲמִיתּוּן מַאן דְּאַפְקִיד בִּידָא דְּמַלְכָּא מִידִי. אֶלָּא, וַדַּאי זַכָּאָה הוּא בַּר נָשׁ, דְּאָזִיל בְּאוֹרְחוֹי דְּמַלְכָּא קַדִּישָׁא, וְלָא חָטֵי קַמֵּיהּ תָּא חֲזֵי, כֵּיוָן דְּעָאל לֵילְיָא, אִילָנָא דְּמוֹתָא שַׁלִּיט בְּעָלְמָא, וְאִילָנָא דְּחַיֵּי אִסְתַּלָּק לְעֵילָּא לְעֵילָּא. וְכֵיוָן דְּאִילָנָא דְּמוֹתָא שַׁלִּיט בְּעָלְמָא בִּלְחוֹדוֹי, כָּל בְּנֵי עָלְמָא טַעֲמִין טַעֲמָא דְּמוֹתָא. מַאי טַעְמָא. בְּגִין דְּהַהוּא אִילָנָא גָּרִים.","וּבַר נָשׁ בָּעֵי לְאַקְדְּמָא וּלְמִפְקַד בִּידֵיהּ נַפְשֵׁיהּ בְּפִקְדוֹנָא. כְּפִקְדוֹנָא דְּבַר נָשׁ, דְּיָהִיב פִּקְדוֹנָא לְאַחֲרָא, דְּאַף עַל גַּב דְּאִיהוּ אִתְחַיָּיב לְגַבֵּיהּ יַתִּיר מֵהַהוּא פִּקְדוֹנָא, לָאו כְּדַאי לְאִתְאַחֲדָא בֵּיהּ, הוֹאִיל וּפִקְדוֹנָא אִתְמְסַר לְגַבֵּיהּ, וְאִי יְסָרֵב בֵּיהּ, וַדַּאי נִבְדוּק אֲבַתְרֵיהּ, דְּלָאו מִזַּרְעָא קַדִּישָׁא הוּא, וְלָאו מִבְּנֵי מְהֵימְנוּתָא.","כַּךְ הַהוּא אִילָנָא, בְּנֵי נָשָׁא אַקְדִּימוּ וְיָהֲבִין לֵיהּ פִּקְדוֹנָא דְּנַפְשַׁיְיהוּ, וְכָל נִשְׁמָתִין דִּבְנֵי עָלְמָא נָטִיל. וְכֻלְּהוּ טַעֲמִין טַעֲמָא דְּמוֹתָא, בְּגִין דְּהַאי אִילָנָא דְּמוֹתָא הוּא. וּבְגִין דְּכָל אִינּוּן נַפְשָׁתָא, אַף עַל גַּב דְּכֻלְּהוּ אִתְחָיְיבוּ לְגַבֵּיהּ, וְלָאו כְּדַאי הוּא לְאָתָבָא פִּקְדוֹנָא לְגַבֵּיהּ דְּבַר נָשׁ, אֶלָּא כֵּיוָן דְּכֻלְּהוּ אִתְמְסָרִי לֵיהּ בְּפִקְדוֹנָא, אָתִיב כָּל פִּקְדוֹנִין לְמָארֵיהוֹן.","תָּא חֲזֵי, לָאו כְּדַאי הוּא הַאי אִילָנָא דְּמוֹתָא לְאָתָבָא פִּקְדוֹנָא לְגַבֵּיהּ דְּבַר נָשׁ. אֶלָּא בְּשַׁעֲתָא דְּאִילָנָא דְּחַיֵּי אִתְּעַר בְּעָלְמָא. וְאֵימָתַי אִתְּעַר הַהוּא אִילָנָא דְּחַיֵּי. בְּשַׁעֲתָא דְּסָלִיק צַפְרָא. וּכְדֵין, כֵּיוָן דְּהַאי אִתְּעַר בְּעָלְמָא, כָּל בְּנֵי עָלְמָא חַיִּין, וְשָׁבִיק וְאַהְדָּר הַהוּא אִילָנָא דְּמוֹתָא כָּל פִּקְדוֹנִין דְּאִתְפְּקָדוּ לְגַבֵּיהּ, וְאָזִיל לֵיהּ. מַאי טַעְמָא חַיִּין. בְּגִין דְּהַהוּא אִילָנָא דְּחַיֵּי גָּרִים.","וְאִי תֵּימָא, הָא בְּנֵי נָשָׁא סַגִּיאִין אִינּוּן דְּמִתְעֲרִין בְּלֵילְיָא, בְּעוֹד דְּאִילָנָא דְּמוֹתָא שַׁלִּיט. אֶלָּא, וַדַּאי הַהוּא אִילָנָא דְּחַיֵּי קָא עָבִיד. מַאי טַעְמָא. בְּגִין דִּכְתִּיב, (תהילים י״ד:ב׳) לִרְאוֹת הֲיֵשׁ מַשְׂכִּיל דּוֹרֵשׁ אֶת אֱלֹהִים. וְלָא יְהֵא לֵיהּ פִּתְחוֹן פֶּה לְבַר נָשׁ, דְּיֵימָּא, אִלְמָלֵי שְׁלִיטְנָא בְּנַפְשָׁאי בְּלֵילְיָא אִשְׁתָּדַּלְנָא בְּאוֹרַיְיתָא. אָמַר רִבִּי יְהוּדָה, הַאי בְּיִשְׂרָאֵל וַדַּאי וְהָכִי הוּא. אֲבָל בְּאוּמוֹת הָעוֹלָם דַּחֲמֵינָא כְּהַאי גַּוְונָא, מַאי טַעְמָא. אָמַר לֵיהּ וַדַּאי שַׁפִּיר הוּא דְּקָא אַמָרְת.","פָּתַח וְאָמַר, (במדבר כ״ג:ח׳) מָה אֶקּוֹב לֹא קַבֹּה אֵל וּמָה אֶזְעוֹם לֹא זָעַם יְיָ. תָּא חֲזֵי, כְּגַוְונָא דְּאִית לְעֵילָּא, אִית לְתַתָּא. לְעֵילָּא אִית יְמִינָא וְאִית שְׂמָאלָא. לְתַתָּא יִשְׂרָאֵל וְעַמִּין. יִשְׂרָאֵל אִתְאַחֲדָן לִימִינָא, בִּקְדוּשָּׁא דְּמַלְכָּא קַדִּישָׁא. עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת לִשְׂמָאלָא, לְסִטְרָא דְּרוּחַ מִסְאֲבָא. וְכֻלְּהוּ לְתַתָּא מִכֻּלְּהוּ דַּרְגִּין דִּשְׂמָאלָא. וְכֻלְּהוּ דַּרְגִּין אֲחִידָן דָּא בְּדָא, עַד דְּתַּלְיָין מִן רֵישָׁא. וּכְגַוְונָא דְּרֵישָׁא נָטִיל, בְּהַהוּא גַּוְונָא נָטִיל זַנְבָא, דְּאִיהִי תַּתָּאָה. מַאי טַעְמָא. בְּגִין דְּאָחִיד בֵּיהּ. וּבְגִין כַּךְ, עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, בְּהַהוּא סְטָר מִסְאֲבָא דִּלְהוֹן, הָכִי אִתְדְּבָּרוּ."],[[0,"ובכלא בעי לאחזאה","וכו': ובכל דבר צריכים להראות מעשה שיהיה כעין של מעלה, וכמו שמראה המעשה למטה, כך מתעורר עליו למעלה. והעמידוהו. שמע ר' פנחס ונשק לר' אלעזר, ובכה וצחק. אמר אשרי חלקי בעולם הזה ובעולם הבא."],[1,"פתח ואמר ה'","וגו': פו\"א ר' פנחס, ה' אורי וישעי ממי אירא וגו'. \u0003ה' אורי וישעי,\u0004 היינו, כיון שאדם הסתכל באור העליון, והקב\"ה האיר עליו, אינו מתירא מעליונים ותחתונים. כש\"א, ועליך יזרח ה' וכבודו עליך יראה. \u0003ה' מעוז חיי,\u0004 היינו כיון שהקב\"ה אוחז בו באדם, אינו מתירא בעולם ההוא מכל בעלי דינים. ואף אני כמו זה, כיון שאני נאחז באביך ובך, איני מתירא בעולם הזה ובעולם האחר."],[2,"ועלך כתיב, ישמח","וגו': ועליך כתוב, ישמח אביך וגו'. שואל, כיון שכתוב ישמח אביך ואמך, מהו, ותגל יולדתך, הרי די במה שאמר ואמך. ומשיב, אלא \u0003ישמח אביך,\u0004 זהו הקב\"ה, \u0003ואמך\u0004 זוהי כנסת ישראל, שהיא מלכות. \u0003ותגל יולדתך,\u0004 היינו יולדתך שלמטה דהיינו אמך, בעולם הזה. וא\"כ, ר' שמעון אביך איפה הוא שמחה שלו שאינו מרומז בכתוב הזה. ומשיב, אלא יש לו מקרא בפני עצמו, שכתוב, \u0003גיל יגיל אבי צדיק,\u0004 זהו הקב\"ה. ויולד חכם ישמח בו, זהו אביך של מטה. דהיינו ר' שמעון. פירוש אחר. גיל יגיל אבי צדיק, זהו אביך שלמטה. ויולד חכם ישמח בו, כתוב בתוספת \u0003ו',\u0004 שהיה די שיאמר יולד חכם. הוא על הקב\"ה למעלה. שנקרא \u0003ו'.\u0004"],[3,"א\"ר אלעזר","וכו': אר\"א כתוב, בידך אפקיד רוחי פדיתה אותי ה' אל אמת. מקרא זה יש להסתכל בו, הראיתם מי שיפקיד משהו בידי המלך שהוא הקב\"ה. ומשיב, אלא ודאי, אשרי הוא האדם ההולך בדרכיו של המלך הקדוש, ואינו חוטא לפניו. בוא וראה כיון שנכנס הלילה אילן המות שולט בעולם, ועץ החיים מסתלק למעלה למעלה, וכיון שאילן המות שולט בעולם לבדו, וכל בני העולם טועמים טעם מות. כי השינה היא אחד מששים במיתה. מהו הטעם. הוא משום שהאילן הזה גורם. שהיא מלכות השולטת לבדה בלי ז\"א גורמת את זה. כי המלכות נקראת לילה."],[4,"ובר נש בעי","וכו': ואדם צריך להקדים עצמו ולהפקיד בידו הנפש שלו, בפקדון. כפקדון של אדם הנותן פקדון לאחר, דהיינו משכון, שאע\"פ שהוא מחויב לו יותר ממחירו של הפקדון ההוא, אינו חשוב לו להתאחז בריב עמו, כיון שמסר לו פקדון. ואם ממאן לתת לו פקדון, ודאי נבדוק אחריו, כי אינו מזרע קדוש, ואינו מבני אמונה."],[5,"כך ההוא אילנא","וכו': כך הוא אילן הזה, שהוא מלכות, שבני אדם מקדימים ונותנים לו נפשם בפקדון, וכל נשמות של בני העולם לוקח. וכולם טועמים טעם מיתה. משום שאילן זה הוא של מות. שבשעה שהמלכות היא בפירוד מז\"א שהוא עץ החיים, הוא אילן המות. ומשום שכל אלו הנפשות, אע\"פ שכולן מתחייבות אליו, ואין ראוי להשיב הפקדון אל האדם, עם כל זה, כיון שכולן נמסרו לו בפקדון, הוא משיב כל הפקדונות לבעליהם."],[6,"ת\"ח לאו כדאי","וכו': בוא וראה, אילן המות הזה אינו ראוי להשיב הפקדון לאדם בבוקר: אלא בשעה שעץ החיים מתעורר בעולם, ומתי מתעורר עץ החיים ההוא. בשעה שבא הבוקר, ואז כיון שעץ החיים הזה מתעורר בעולם, ויוצאים כל בני העולם חיים, ואותו אילן המות עוזב ומחזיר כל הפקדונות שנפקדו אצלו, והולך לו. מהו הטעם הם חיים. הוא משום שאותו עץ החיים גורם, שהוא ז\"א השולט ביום."],[7,"ואי תימא הא","וכו': ואם תאמר, הרי בגי אדם רבים הם שמקיצים משנתם בלילה, והוחזרו להם החיים, בעוד שאילן המות שולט. ומשיב, אלא ודאי אותו עץ החיים עושה זאת. מהו הטעם, משום שכתוב, לראות היש משכיל דורש את אלקים. ולא יהיה לאדם פתחון פה, שיאמר, אם הייתי שולט בנפשי בלילה, הייתי קם ועוסק בתורה, א\"ר יהודה. זהו ודאי נכון בישראל, וכך הוא. אבל באומות העולם, שאנו רואים גס כן כמו זה, שמקיצים משנתם בלילה, מהו הטעם. אמר לו, ודאי יפה הוא מה שאמרת."],[8,"פתח ואמר מה","וגו': פו\"א, מה אקוב לא קבה אל ומה אזעם לא זעם ה'. בוא וראה, כמו שיש למעלה כן יש למטה, למעלה במלכות, יש ימין, ויש שמאל אף למטה, יש ישראל ועמים. ישראל נאחזים בימין, בקדושת המלך הקדוש, עמים עכו\"ם נאחזים בשמאל, והיינו רק בצד רוח הטומאה, שהוא למטה מכל המדרגות דשמאל. וכל המדרגות אחוזות זו בזו, מלמטה, עד שתלויות בראש, דהיינו בצד שמאל שלמעלה במלכות, ובאותו אפן שהראש נוסע למעלה, כמו זה נוסע גם כן הזנב, שהוא המדרגה האחרונה למטה, שהוא רוח הטומאה, מהו הטעם. הוא משום שאחוז בו, כי הם אחוזים זה בזה ממטה עד למעלה כמו שלשלת, ומשום זה, עמים עכו\"ם, באותו אפן שהוא צד הטומאה שלהם, כך הם מונהגים."]],[[0,"","וּבַכֹּל צָרִיךְ לְהַרְאוֹת מַעֲשֶׂה כְּמוֹ שֶׁלְּמַעְלָה. וּכְמוֹ שֶׁמַּרְאֶה מַעֲשֶׂה לְמַטָּה, כָּךְ מְעוֹרֵר לְמַעְלָה, וּפֵרְשׁוּהָ. שָׁמַע רַבִּי פִּנְחָס וְנָשַׁק לְרַבִּי אֶלְעָזָר, וּבָכָה וְצָחַק וְאָמַר, אַשְׁרֵי חֶלְקִי בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[1,"","פָּתַח וְאָמַר, (תהלים כז) ה' אוֹרִי וְיִשְׁעִי מִמִּי אִירָא וְגוֹ'. ה' אוֹרִי וְיִשְׁעִי, כֵּיוָן שֶׁאָדָם הִסְתַּכֵּל (נאחז) בָּאוֹר שֶׁלְּמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֵאִיר עָלָיו, לֹא פוֹחֵד מֵעֶלְיוֹנִים וְתַחְתּוֹנִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ס) וְעָלַיִךְ יִזְרַח ה' וּכְבוֹדוֹ עָלַיִךְ יֵרָאֶה. ה' מָעוֹז חַיַּי, כֵּיוָן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹחֵז בָּאָדָם, לֹא יִפְחַד בְּאוֹתוֹ עוֹלָם מִכָּל בַּעֲלֵי הַדִּינִים. גַּם אֲנִי כְּמוֹ זֶה, כֵּיוָן שֶׁאָחַזְתִּי בְּאָבִיךְ וּבְךְ, לֹא אֶפְחַד בָּעוֹלָם הַזֶּה וּבָעוֹלָם הָאַחֵר."],[2,"","וְעָלֶיךָ כָּתוּב, (משלי כג) יִשְׂמַח אָבִיךְ וְגוֹ'. כֵּיוָן שֶׁכָּתוּב יִשְׂמַח אָבִיךְ וְאִמֶּךְ, מַה זֶּה וְתָגֵל יוֹלַדְתֶּךְ? שֶׁהֲרֵי בְּאִמֶּךְ מַסְפִּיק. אֶלָּא יִשְׂמַח אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְתָגֵל יוֹלַדְתֶּךְ - יוֹלַדְתְּךְ שֶׁלְּמַטָּה. אֵיפֹה שִׂמְחָתוֹ שֶׁל רַבִּי שִׁמְעוֹן אָבִיךְ? אֶלָּא פָּסוּק הוּא לְבַדּוֹ, שֶׁכָּתוּב (שם) גִּיל יָגִיל אֲבִי צַדִּיק - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְיוֹלֵד חָכָם יִשְׂמַח בּוֹ - זֶה אָבִיךְ שֶׁלְּמַטָּה. דָּבָר אַחֵר, גִּיל יָגִיל אֲבִי צַדִּיק - זֶה אָבִיךְ שֶׁלְּמַטָּה. וְיוֹלֵד חָכָם יִשְׂמַח בּוֹ, כָּתוּב בְּתוֹסֶפֶת וָא\"ו - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה."],[3,"","אָמַר רַבִּי אֶלְעָזָר, כָּתוּב (תהלים לא) בְּיָדְךְ אַפְקִיד רוּחִי פָּדִיתָה אוֹתִי ה' אֵל אֱמֶת. יֵשׁ לְהִסְתַּכֵּל בַּפָּסוּק הַזֶּה. רְאִיתֶם מִי שֶׁמַּפְקִיד דָּבָר בִּידֵי הַמֶּלֶךְ? אֶלָּא, וַדַּאי אַשְׁרֵי הָאִישׁ שֶׁהוֹלֵךְ בְּדַרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ וְלֹא חוֹטֵא לְפָנָיו. בֹּא רְאֵה, כֵּיוָן שֶׁנִּכְנָס הַלַּיְלָה, עֵץ הַמָּוֶת שׁוֹלֵט בָּעוֹלָם, וְעֵץ הַחַיִּים מִסְתַּלֵּק לְמַעְלָה לְמַעְלָה. וְכֵיוָן שֶׁעֵץ הַמָּוֶת שׁוֹלֵט בָּעוֹלָם לְבַדּוֹ, כָּל בְּנֵי הָעוֹלָם טוֹעֲמִים טַעַם מָוֶת. מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹתוֹ עֵץ גּוֹרֵם."],[4,"","וְהָאָדָם צָרִיךְ לְהַקְדִּים וּלְהַפְקִיד בְּיָדוֹ אֶת נַפְשׁוֹ בְּפִקָּדוֹן, כְּפִקָּדוֹן שֶׁל אָדָם שֶׁנּוֹתֵן פִּקָּדוֹן לְאַחֵר. שֶׁאַף עַל גַּב שֶׁהוּא הִתְחַיֵּב אֵלָיו יוֹתֵר מֵאוֹתוֹ פִּקָּדוֹן - לֹא כְּדַאי לְהֵאָחֵז בּוֹ, הוֹאִיל וְהַפִּקָּדוֹן נִמְסַר לוֹ, וְאִם יְסָרֵב בּוֹ - וַדַּאי נִבְדֹּק אַחֲרָיו, שֶׁאֵין הוּא מִזֶּרַע קֹדֶשׁ וְלֹא מִבְּנֵי הָאֱמוּנָה."],[5,"","כָּךְ אוֹתוֹ עֵץ, בְּנֵי אָדָם מַקְדִּימִים וְנוֹתְנִים לוֹ פִּקְדוֹן נַפְשָׁם, וְלוֹקֵחַ כָּל נִשְׁמוֹת בְּנֵי הָעוֹלָם. וְכֻלָּם טוֹעֲמִים טַעַם מָוֶת, מִשּׁוּם שֶׁזֶּה עֵץ הַמָּוֶת הוּא. וּמִשּׁוּם שֶׁכָּל נְפָשׁוֹת אֵלּוּ, אַף עַל גַּב שֶׁכֻּלָּם הִתְחַיְּבוּ לוֹ, וְלֹא כְּדַאי הוּא לְהָשִׁיב הַפִּקָּדוֹן לָאָדָם. אֶלָּא כֵּיוָן שֶׁכֻּלָּם נִמְסְרוּ לוֹ בְּפִקָּדוֹן, מַחֲזִיר כָּל הַפִּקְדוֹנוֹת לְבַעְלֵיהֶם."],[6,"","בֹּא רְאֵה, לֹא כְּדַאי לְעֵץ הַמָּוֶת הַזֶּה לְהַחֲזִיר פִּקְדוֹנוֹ לָאָדָם אֶלָּא בְּשָׁעָה שֶׁעֵץ הַחַיִּים מִתְעוֹרֵר בָּעוֹלָם. וּמָתַי מִתְעוֹרֵר אוֹתוֹ עֵץ חַיִּים? בְּשָׁעָה שֶׁעוֹלֶה הַבֹּקֶר. וְאָז, כֵּיוָן שֶׁזֶּה מִתְעוֹרֵר בָּעוֹלָם, כָּל בְּנֵי הָעוֹלָם חַיִּים, וּמַשְׁאִיר וּמַחֲזִיר אוֹתוֹ עֵץ הַמָּוֶת כָּל הַפִּקְדוֹנוֹת שֶׁהֻפְקְדוּ אֶצְלוֹ, וְהוֹלֵךְ לוֹ. מָה הַטַּעַם הֵם חַיִּים? מִשּׁוּם שֶׁאוֹתוֹ עֵץ הַחַיִּים גָּרַם."],[7,"","וְאִם תֹּאמַר, הֲרֵי בְּנֵי אָדָם רַבִּים הֵם מִתְעוֹרְרִים בַּלַּיְלָה בְּעוֹד שֶׁעֵץ הַמָּוֶת שׁוֹלֵט? אֶלָּא וַדַּאי אוֹתוֹ עֵץ הַחַיִּים עוֹשֶׂה אֶת זֶה. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (תהלים יד) לִרְאוֹת הֲיֵשׁ מַשְׂכִּיל דֹּרֵשׁ אֶת אֱלֹהִים. וְלֹא יִהְיֶה פִּתְחוֹן פֶּה לְאָדָם שֶׁיֹּאמַר: אִלְמָלֵא שָׁלַטְתִּי בְנַפְשִׁי בַּלַּיְלָה, הָיִיתִי מִשְׁתַּדֵּל בַּתּוֹרָה. אָמַר רַבִּי יְהוּדָה, זֶה בְּיִשְׂרָאֵל בְּוַדַּאי, וְכָךְ הוּא! אֲבָל בְּאֻמּוֹת הָעוֹלָם שֶׁרָאִינוּ כָּזֶה, מָה הַטַּעַם? אָמַר לוֹ: יָפֶה מַה שֶּׁאָמַרְתָּ."],[8,"","פָּתַח וְאָמַר, (במדבר כג) מָה אֶקֹּב לֹא קַבֹּה אֵל וּמָה אֶזְעֹם לֹא זָעַם ה'. בּא רְאֵה, כְּמוֹ שֶׁיֵּשׁ לְמַעְלָה יֵשׁ לְמַטָּה. לְמַעְלָה יֵשׁ יָמִין וְיֵשׁ שְׂמֹאל - לְמַטָּה יִשְׂרָאֵל וְהָעַמִּים. יִשְׂרָאֵל אֲחוּזִים לְיָמִין בִּקְדֻשַּׁת הַמֶּלֶךְ הַקָּדוֹשׁ. הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת לִשְׂמֹאל, לְצַד רוּחַ הַטֻּמְאָה. וְכֻלָּם לְמַטָּה מִכָּל דַּרְגוֹת הַשְּׂמֹאל. וְכָל הַדְּרָגוֹת אֲחוּזוֹת זוֹ בָּזוֹ עַד שֶׁתְּלוּיוֹת מֵהָרֹאשׁ. וּכְמוֹ שֶׁהָרֹאשׁ נוֹסֵעַ, בְּאוֹתוֹ הַגָּוֶן נוֹסֵעַ הַזָּנָב, שֶׁהוּא תַחְתּוֹן. מָה הַטַּעַם? מִשּׁוּם שֶׁאָחוּז בּוֹ. וּמִשּׁוּם זֶה הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, בְּאוֹתוֹ צַד הַטֵּמְאָה שֶׁלָּהֶם כָּךְ מֻנְהָגִים."]]],[["בִּלְעָם הוּא אִשְׁתָּמַּשׁ בְּכֻלְּהוּ כִּתְרִין (נ\"א דרגין) תַּתָּאִין. וְהוּא הֲוָה חָמֵי בְּהַאי תַּתָּאָה דְּאִיהוּ זַנְבָא, דְּלָא יָכִיל לְאִתְדַּבְּרָא אֶלָּא בְּרֵישָׁא. בְּגִין כַּךְ אָמַר, מָה אֶקּוֹב לֹא קַבֹּה אֵל, (דאיהו רישא בגין) דְּהַהוּא רֵישָׁא עִלָּאָה, לָא אִשְׁתְּכַח בְּדִינָא בְּאִינּוּן יוֹמִין.","וְאַף עַל גַּב דְּהַאי אֵל אוֹקִימְנָא, הַאי מַלְכוּתָא קַדִּישָׁא נָטִיל שְׁמָא כְּגַוְונָא דְּכֹלָּא, וְהַאי טַב וְחֶסֶד דְּהַאי עָלְמָא (ס\"א אוקימנא באתר אחרא עלאה והוא טב וחסד עלמא האי מלכותא קדישא נטיל שמא כגוונא דעילא) וּבְגִין כַּךְ אִקְרֵי אֵל, אֶלָּא דְּאִיהוּ (לעיל ל\"ב) זוֹעֵם בְּכָל יוֹם, דְּאִשְׁתְּכַח בֵּיהּ דִּינָא.","וְתָּא חֲזֵי, אֵל שַׁדַּי (שמות רנ\"ג ע\"א) הָא אוֹקִימְנָא דְּבֵיהּ סִפּוּקָא דְּעָלְמָא וְאִיהוּ אָמַר לַעוֹלָם דַּי, דְּהָא הַאי אֵל הוּא דְּאִזְדְּוַּוג בַּהֲדֵיהּ, וּבְגִין כַּךְ אִקְרֵי אֵל שַׁדַּי, אֵל דְּשַׁדַּי. וְעַל דָּא מַה אֶקּוֹב לֹא קַבֹּה אֵל. בְּגִין כַּךְ, כְּגַוְונָא דְּאִתְּעַר רֵישָׁא, הָכִי נָמֵי אִתְּעַר תַּתָּאָה.","בָּכָה רִבִּי אֶלְעָזָר, פָּתַח וְאָמַר (ירמיהו מ״ו:כ״ב) קוֹלָהּ כַּנָּחָשׁ יֵלֵךְ וְגוֹ'. הַשְׁתָּא (כהאי גוונא) דְּיִשְׂרָאֵל בְּגָלוּתָא, אִיהִי וַדַּאי אַזְלָא כְּנָחָשׁ. חִוְיָא כַּד אִיהוּ (ד\"א בדינא) כָּפִיף רֵישָׁא לְעַפְרָא, סָלִיק זַנְבָא, שַׁלִּיט וּמָחֵי לְכָל אִינּוּן דְּאִשְׁתְּכָחוּ קַמֵּיהּ. אוּף הָכִי הַשְׁתָּא בְּגָלוּתָא, כְּהַאי גַּוְונָא, רֵישָׁא כָּפִיף לְעַפְרָא, וְזַנְבָא שַׁלִּיט. מַאן עָבִיד לְזַנְבָא דְּיִסְתְּלִיק לְעֵילָּא וְשָׁלִיט וּמָחֵי, רֵישָׁא דְּאִתְכַּפְיָא לְתַתָּא. וְעִם כָּל דָּא, מַאן מַדְבָּר לֵיהּ לְזַנְבָא, וּמַאן נָטִיל לֵיהּ לְמַטַלְנוֹי. הַאי רֵישָׁא. אַף עַל גַּב דְּאִיהוּ כָּפִיף לְעַפְרָא, הוּא מַדְבָּר לְמַטַלְנוֹי, בְּגִין דָּא קוֹלָהּ כַּנָּחָשׁ יֵלֵךְ.","וְהַשְׁתָּא שְׁאַר עַמִּין דְּאִינּוּן אֲחִידָן בִּזְנָבָא, סַלְּקִין לְעֵילָּא, וְשַׁלְטִין וּמַחְיָין, וְרֵישָׁא כָּפִיף לְעַפְרָא, כְּמָה דְאַתְּ אָמֵר (עמוס ה׳:ב׳) נָפְלָה לֹא תוֹסִיף קוּם וְגוֹ'. וְעִם כָּל דָּא, הַאי רֵישָׁא מַדְבַּר לְזַנְבָא וְנָטִיר (ס\"א ונטיל) לֵיהּ, כְּמָה דְאַתְּ אָמֵר (שיר השירים א׳:ו׳) שָׂמוּנִי נוֹטֵרָה אֶת הַכְּרָמִים, אִלֵּין עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, דְּאִינּוּן זַנְבָא. אָתָא רִבִּי יְהוּדָה וְנָשִׁיק יְדוֹי, אָמַר אִלְמָלֵי לָא שָׁאִילְנָא מִלָּה בְּעָלְמָא, אֶלָּא דְּשָׁאִילְנָא דָּא וְרַוַוחְנָא לֵיהּ, דַּי לִי. דְּהַשְׁתָּא יְדַעְנָא עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, וְשׁוּלְטָנוּתָא דִּלְהוֹן הֵיךְ מִתְדַּבָּר. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּעָלַיְיהוּ כְּתִיב, (תהילים קל״ה:ד׳) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ וְגוֹ'.","אָמַר לֵיהּ רִבִּי אֶלְעָזָר, מַהוּ לִסְגוּלָּתוֹ. אָמַר לֵיהּ, תְּלַת אֲבָהָן אִלֵּין אִקְרוּן סְגוּלָה, בֵּין לְעֵילָּא בֵּין לְתַתָּא, כְּגַוְונָא דָּא כֹּהֲנִים לְוִיִּים וְיִשְׂרְאֵלִים, וְכֹלָּא חַד. וְאִלֵּין סְגּוּלָּתוֹ שֶׁל קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָּא, וּסְגּוּלָּתוֹ לְתַתָּא, וְדָא הוּא דִּכְתִּיב (שמות י״ט:ה׳) וִהְיִיתֶם לִי סְגוּלָּה מִכָּל הָעַמִּים.","(במדבר ב׳:י״ז) וְנָּסַע אֹהֶל מוֹעֵד מַחֲנֵה הַלְּוִיִּם וְגוֹ'. לְבָתַר מַה כְּתִיב, וְנָסַע דֶּגֶל מַחֲנֵה אֶפְרַיִם לְצִבְאוֹתָם יָמָּה. הַיְינוּ שְׁכִינָה שְׁרוּיָה בְּמַּעֲרָב, וְאוֹקְמוּהָ. כְּתִיב (בראשית מ״ח:כ׳) וַיְבָרַכֵם בַּיוֹם הַהוּא לֵאמֹר בְּךָ יְבָרֵךְ יִשְׂרָאֵל לֵאמֹר וְגוֹ'. וַיָּשֶׂם אֶת אֶפְרַיִם וְגוֹ'. בְּךָ יְבָרֵךְ יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא. מַאי קָא מַשְׁמַע לָן.","אֶלָּא בְּךָ יִתְבָּרֵךְ יִשְׂרָאֵל לָא כְּתִיב, אוֹ בְּךָ יְבוֹרָךְ יִשְׂרָאֵל, מַהוּ יְבָרֵךְ יִשְׂרָאֵל. אֶלָּא, יִשְׂרָאֵל קַדִּישָׁא לָא יְבָרֵךְ לְעָלְמָא, אֶלָּא בְּךָ, דְּאַנְתְּ בְּמַּעֲרָב. וּכְתִיב (בראשית ל״ה:י״א) אֲנִי אֵל שַׁדַּי פְּרֵה וּרְבֵה. אוֹלִיפְנָא דְּחָמָא עִמֵּיהּ שְׁכִינְתָּא, וּכְדֵין אָמַר בְּךָ יְבָרֵךְ יִשְׂרָאֵל לֵאמֹר. בְּךָ יְבָרֵךְ לְעָלְמָא.","וְהֵיאַךְ חָמָא, וְהָכְּתִיב (בראשית מ״ח:י׳) וְעֵינֵי יִשְׂרָאֵל כָּבְדוּ מִזּוֹקֶן וְגוֹ'. אֶלָּא שִׂכֵּל אֶת יָדָיו כְּתִיב. מַאי שִׂכֵּל. אֶלָּא יְמִינָא הֲוָה זָקִיף, וְסָטֵי לֵיהּ שְׁכִינְתָּא כְּלַפֵּי אֶפְרַיִם, וְאָרַח רֵיחָא דִּשְׁכִינְתָּא עַל רֵישֵׁיהּ, כְּדֵין אָמַר בְּךָ יְבָרֵךְ יִשְׂרָאֵל. וְחָמָא דְּאִיהוּ לְמַעֲרָב.","וַדַּאי שְׁכִינְתָּא בְּמַּעֲרָב, וְהָא אוֹקִימְנָא בְּגִין דְּלִהֱוֵי בֵּין צָפוֹן לְדָרוֹם, וּלְאִתְחַבְּרָא בְּגוּפָא, וּלְמֶהֱוִי בְּזִוּוּגָא חַד. וְצָפוֹן מְקַבְּלָא לָהּ תְּחוֹת רֵישָׁא, וְדָרוֹם מְחַבְּקָא לָהּ, הֲדָא הוּא דִכְתִיב, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. וְהָא אוֹקִימְנָא וַדַּאי, מִטָּתוֹ שֶׁלִּשְׁלֹמֹה בֵּין צָפוֹן לְדָרוֹם, וּלְאִתְחַבְּרָא בְּגוּפָא, וּכְדֵין כְּלָלָא חַד לְאִתְבָּרְכָא עָלְמָא. תְּנָן, כָּל הָאוֹמֵר תְּהִלָּה לְדָוִד ג' פְּעָמִים בְּכָל יוֹמָא, מוּבְטַח לוֹ שֶׁהוּא בֶּן הַעוֹלָם הַבָּא, וְהָא אוֹקִימְנָא בְּגִין לְזַוְּוגָא לָהּ לְהַאי תְּהִלָּה, וּלְאִשְׁתַּכְּחָא בְּכָל יוֹמָא בֵּין צָפוֹן לְדָרוֹם."],[[0,"בלעם הוא אשתמש","וכו': בלעם השתמש בכל המדרגות התחתונות היורדות מצד שמאל של המלכות, והוא היה מסתכל באותה המדרגה התחתונה שהיא זנב, והיה יודע מה שלמעלה, כי התחתונה אינה יכולה להתנהג אלא על ידי הראש. משום זה אמר מה אקוב לא קבה אל, שראה למטה, וידע שאותו ראש העליון, שהוא השמאל שבמלכות, אינו נמצא בדין באלו הימים."],[1,"ואע\"ג דהאי אל","וכו': ואע\"פ ששם הזה, \u0003אל,\u0004 העמדנו (לעיל צו אות צ\"א) שהוא חסד עליון, הרי מלכות הקדושה לוקחת שם הזה כעין שלמעלה, והיא טוב וחסד בעולם הזה, ומשום זה היא נקראת בשם, \u0003אל.\u0004 אלא שהוא זועם בכל יום, בסו\"ה, ואל זועם בכל יום, משום שנמצא בו דין. ובאותם הימים לא היה בו דין, ע\"כ אמר בלעם מה אקוב לא קבה אל."],[2,"ות\"ח אל שדי","וכו': ובוא וראה, \u0003אל שדי,\u0004 הרי העמדנו, שבו ספוק העולם והוא אמר לעולם די, שהוא יסוד, המשפיע די למלכות הנקראת עולם. כי \u0003אל\u0004 הזה, שהוא מלכות, מזדווגת עמו, ומשום זה נקרא, אל שדי דהיינו אל דשדי. כי אל, שהוא מלכות מזדווגת עם שדי, שהוא יסוד. וע\"כ אמר, מה אקוב לא קבה אל, על המלכות הנקראת אל, וידע זה, משום שכמו שמתעורר הראש, שהוא מלכות, כך מתעורר התחתון שהוא הזנב, דהיינו רוח הטומאה. ובלעם הסתכל בזנב, וידע מה בראש."],[3,"בכה ר' אלעזר","וכו': בכה ר\"א, פתח ואמר, קולה כנחש ילך וגו'. כי עתה שישראל הם בגלות, ודאי שהמלכות הולכת כנחש, כי דרך הנחש הוא, כשהוא כופף ראשו לעפר, הוא מעלה זנבו, והזנב שולט ומכה כל אלו הנמצאים לפניו. אף כך עתה כשישראל הם בגלות, עושה המלכות ג\"כ. כאפן הזה של הנחש, שהראש כפוף לעפר, והזנב, דהיינו המדרגה התחתונה הנ\"ל, שולט. מי עשה שהזנב יתעלה למעלה וישלוט ויכה, הוא הראש שנתכופף למטה. ועם כל זה, מי מנהיג את הזנב, ומי מסיע את הזנב לנסיעותיו, הוא הראש הזה, אע\"פ שהוא כפוף לעפר, הוא מנהיג נסיעותיו של הזנב. משום זה אוה\"כ, קולה כנחש ילך."],[4,"והשתא שאר עמין","וכו': ועתה שאר העמים שהם נאחזים בזנב (כנ\"ל אות מ'\"ו) של המלכות, עולים למעלה ושולטים ומכים, והראש כפוף לעפר. כש\"א נפלה לא תוסיף קום וגו'. ועם כל זה, הראש מנהיג את הזנב, ושומר אותו, כש\"א, שמוני נוטרה את הכרמים, שהם עמים העכו\"ם שהם בזנב. בא ר' יהודה ונשק ידיו. אמר, אם לא הייתי שואל דבר בעולם, אלא מה ששאלתי זה, והרוחתי אותו, די לי. כי עתה ידעתי בחינת עמים העכו\"ם, ואיך מתנהגת השליטה שלהם. אשרי חלקם של ישראל, שעליהם כתוב, כי יעקב בחר לו יה ישראל לסגולתו."],[5,"א\"ל רבי אלעזר","וכו': א\"ל ר\"א, מהו לסגולתו. שאומר, ישראל לסגולתו. אמר לו שלשה אבות אלו נקראים סגולה, בין למעלה, שהם חג\"ת, ובין למטה, שהם אברהם יצחק יעקב. וכעין זה, כהנים לוים ישראלים, שהם ג\"כ כנגד חג\"ת, והכל אחד. ואלו הם סגולתו של הקב\"ה למעלה, וסגולתו של הקב\"ה למטה. וזהו שכתוב, והייתם לי סגולה מכל העמים, דהיינו מפני שיש בהם נהנים לוים ישראלים הנקראים סגולה."],[5,"","פירוש עיקר ההפרש מישראל לעמים הוא מפני שהעמים דבוקים בקו שמאל בלבד בלי ימין. וישראל דבוקים בג' קוין. שה\"ס חג\"ת. ומשום זה הם סגולה מכל העמים. כי יחוד ג' קוין נקראים סגולה."],[6,"ונסע אהל מועד מחנה הלוים","וגו': ואחר זה, מה כתוב, ונסע דגל מחנה אפרים לצבאותם ימה. היינו השכינה השרויה במערב, והעמידוהו, לעיל (באות ל\"א) שאפרים שנסע במערב ה\"ס המלכות, וע\"כ נסע אחר דגל מחנה ראובן שהוא בדרום שהוא חסד. וכו'. ע\"ש. כתוב, ויברכם ביום ההוא לאמר, בך יברך ישראל. שואל, לאמר וגו' וישם את אפרים וגו'. בך יברך ישראל, הוא ישראל סבא. שואל מה מלמדנו בזה."],[7,"אלא בך יתברך","וכו': ומשיב, אלא, בך יתברך לא כתוב, או בך יבורך ישראל, מהו יברך ישראל, שהוא לאחרים. אלא פירושו, ישראל הקדוש, שהוא ז\"א, לא יברך לעולם אלא בך, באפרים, שאתה במערב, שהוא השכינה. וכתוב, אני אל שדי פרה ורבה. הרי שהברכה היא בשכינה שנקראת אל שדי (כנ\"ל אות מ\"ט) ולמדנו שראה עמו השכינה, ואז אמר, בך יברך ישראל לאמר. שפירושו בך, בהשכינה, יברך לעולם."],[8,"והאיך חמא והכתיב","וכו': שואל, ואיך ראה, השכינה, והרי כתוב, ועיני ישראל כבדו מזוקן וגו'. הרומז גם לעינים הרוחניות. ומשיב, אלא שכל את ידיו כתוב, מהו שכל. ומשיב, אלא יד ימין היתה זקופה כנגד אפרים, ונטתה השכינה כלפי אפרים, וישראל הריח ריח השכינה על ראשו, אז אמר בך יברך ישראל, וראה שהיא במערב. כלומר, שלא ראה בבחינת העינים, אלא שראה בבחינת הריח, שפירושו ממטה למעלה."],[9,"ודאי שכינתא במערב","וכו': ודאי הוא שהשכינה במערב, והעמדנו שהיא כדי שתהיה בין צפון ודרום, כי המערב הוא בין צפון לדרום, ותתחבר בהגוף, שה\"ס ז\"א שנקרא גוף, שפירושו ז\"ס תחתונות, ולהיות עמו בזווג אחד, והצפון, שהוא קו שמאל דז\"א, מקבל אותה תחת ראשה, והדרום, שהוא קו ימין דז\"א, מחבק אותה. ז\"ש שמאלו תחת לראשי, שמן השמאל שה\"ס הארת החכמה שבו, מקבלת ג\"ר שנקרא ראש. וימינו תחבקני, ומן הימין, שה\"ס חסדים מקבלת הארת ז\"ת שלה שנקראות גוף. והעמדנו, ודאי שמטתו שלשלמה, שה\"ס המלכות הנקראת מטה (כנ\"ל באות ל\"ו) היא בין צפון לדרום. שהם חסד וגבורה, כדי שתתחבר בגוף, שהוא ת\"ת, ואז הם כלל אחד שיתברך העולם. למדנו כל האומר תהלה לדוד ג' פעמים בכל יום מובטח לו שהוא בן העולם הבא. והעמדנו, שפירושו הוא, דהיינו שמזווג תהלה זו, שהיא המלכות, שתמצא, עם ז\"א, בכל יום בין צפון לדרום."]],[[0,"","בִּלְעָֹם הִשְׁתַּמֵּשׁ בְּכָל הַדְּרָגוֹת הַתַּחְתּוֹנוֹת, וְהוּא הָיָה רוֹאֶה בַּתַּחְתּוֹן הַזֶּה, שֶׁהוּא הַזָּנָב, שֶׁלֹּא יָכוֹל לְהִתְנַהֵג אֶלָּא בָּרֹאשׁ. מִשּׁוּם כָּךְ אָמַר מָה אֶקֹּב לֹא קַבּה אֵל, (שהוא הראש משום) שֶׁאוֹתוֹ הָרֹאשׁ הָעֶלְיוֹן אֵינוֹ נִמְצָא בְדִין בְּאוֹתָם הַיָּמִים."],[1,"","וְאַף עַל גַּב שֶׁהָאֵל הַזֶּה בֵּאַרְנוּ, הַמַּלְכוּת הַקְּדוֹשָׁה הַזּוֹ לוֹקַחַת שֵׁם כְּמוֹ הַכֹּל, וְהַטּוֹב וְהַחֶסֶד שֶׁל הָעוֹלָם הַזֶּה, (בארנו במקום אחר עליון, והוא טוב וחסד של העולם, המלכות הקדושה הזו לוקחת שם כמו שלמעלה) וּמִשּׁוּם זֶה נִקְרֵאת אֵל, אֶלָּא שֶׁהוּא זוֹעֵם בְּכָל יוֹם, שֶׁנִּמְצָא בּוֹ דִין."],[2,"","וּבֹא רְאֵה, אֵל שַׁדַּי בֵּאַרְנוּ שֶׁבּוֹ הֲנָאַת הָעוֹלָם, וְהוּא אָמַר לָעוֹלָם דַּי. שֶׁהֲרֵי הָאֵל זֶה הוּא שֶׁמִּזְדַּוֵּג עִמּוֹ, וּמִשּׁוּם כָּךְ נִקְרָא אֵל שַׁדַּי, אֵל שֶׁל שַׁדַּי. וְעַל זֶה מָה אֶקֹּב לֹא קַבֹּה אֵל. מִשּׁוּם כָּךְ, כְּמוֹ שֶׁמִּתְעוֹרֵר הָרֹאשׁ - כָּךְ מִתְעוֹרֵר הַתַּחְתּוֹן."],[3,"","בָּכָה רַבִּי אֶלְעָזָר, פָּתַח וְאָמַר, (ירמיה מו) קוֹלָהּ כַּנָּחָשׁ יֵלֵךְ וְגוֹ'. כָּעֵת (כמו זה) שֶׁיִּשְׂרָאֵל בַּגָּלוּת, הִיא וַדַּאי הוֹלֶכֶת כַּנָּחָשׁ. נָחָשׁ, כְּשֶׁהוּא (בדין) כּוֹפֵף רֹאשׁוֹ לֶעָפָר, עוֹלֶה הַזָּנָב, שׁוֹלֵט וּמַכֶּה אֶת כָּל אוֹתָם שֶׁנִּמְצָאִים לְפָנָיו. אַף כָּךְ כָּעֵת בַּגָּלוּת - כְּגוֹן זֶה הָרֹאשׁ כָּפוּף לֶעָפָר, וְהַזָּנָב שׁוֹלֵט. מִי עָשָׂה שֶׁהַזָּנָב יַעֲלֶה לְמַעְלָה, יִשְׁלֹט וְיַכֶּה? הָרֹאשׁ שֶׁמִּתְכּוֹפֵף לְמַטָּה. וְעִם כָּל זֶה, מִי מַנְהִיג אֶת הַזָּנָב וּמִי מַסִּיעוֹ לְמַסָּעָיו? זֶה הָרֹאשׁ. אַף עַל גַּב שֶׁהוּא כָּפוּף לֶעָפָר, הוּא מַנְהִיג אֶת מַסָּעָיו. בִּגְלַל זֶה, קוֹלָהּ כַּנָּחָשׁ יֵלֵךְ."],[4,"","וְעַכְשָׁו, שְׁאָר הָעַמִּים שֶׁהֵם אֲחוּזִים בַּזָּנָב, עוֹלִים לְמַעְלָה, וְשׁוֹלְטִים וּמַכִּים, וְהָרֹאשׁ כָּפוּף לֶעָפָר, כְּמוֹ שֶׁנֶּאֱמַר (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם וְגוֹ'. וְעִם כָּל זֶה, הָרֹאשׁ הַזֶּה מַנְהִיג אֶת הַזָּנָב וְשׁוֹמֵר (ומסיע) אוֹתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים א) שָׂמֻנִי נֹטֵרָה אֶת הַכְּרָמִים. אֵלֶּה עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, שֶׁהֵם הַזָּנָב. בָּא רַבִּי יְהוּדָה, וְנָשַׁק יָדָיו וְאָמַר, אִלְמָלֵא לֹא שָׁאַלְתִּי דָבָר בָּעוֹלָם, אֶלָּא שֶׁשָּׁאַלְתִּי זֶה וְהִרְוַחְתִּי אוֹתוֹ - דַּי לִי, שֶׁעַכְשָׁו יָדַעְתִּי עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת וְשִׁלְטוֹנָם אֵיךְ מֻנְהָג. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁעֲלֵיהֶם כָּתוּב (תהלים קלה) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ וְגוֹ'."],[5,"","אָמַר לוֹ רַבִּי אֶלְעָזָר, מַה זֶּה לִסְגֻלָּתוֹ? אָמַר לוֹ, שְׁלֹשֶׁת הָאָבוֹת הַלָּלוּ נִקְרְאוּ סְגֻלָּה, בֵּין לְמַעְלָה בֵּין לְמַטָּה, כְּמוֹ זֶה כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים, וְהַכֹּל אֶחָד. וְאֵלֶּה סְגֻלָּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה וּסְגֻלָּתוֹ לְמַטָּה, וְזֶהוּ שֶׁכָּתוּב (שמות יט) וִהְיִיתֶם לִי סְגֻלָּה מִכָּל הָעַמִּים."],[6,"","וְנָסַע אֹהֶל מוֹעֵד מַחֲנֵה הַלְוִיִּם וְגוֹ'. אַחַר כָּךְ מַה כָּתוּב? (ונסע) דֶּגֶל מַחֲנֵה אֶפְרַיִם לְצִבְאֹתָם יָמָּה. הַיְנוּ שְׁכִינָה שְׁרוּיָה בַּמַּעֲרָב, וּפֵרְשׁוּהָ. כָּתוּב (בראשית מח) וַיְבָרֲכֵם בַּיּוֹם הַהוּא לֵאמוֹר בְּךְ יְבָרֵךְ יִשְׂרָאֵל לֵאמֹר וְגוֹ', וַיָּשֶׂם אֶת אֶפְרַיִם וְגוֹ'. בְּךְ יְבָרֵךְ יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא. מַה מַּשְׁמִיעֵנוּ?"],[7,"","אֶלָּא בְּךְ יִתְבָּרֵךְ יִשְׂרָאֵל לֹא כָתוּב, אוֹ בְּךְ יְבֹרַךְ יִשְׂרָאֵל. מַה זֶּה יְבָרֵךְ יִשְׂרָאֵל? אֶלָּא יִשְׂרָאֵל הַקָּדוֹשׁ לֹא יְבָרֵךְ אֶת הָעוֹלָם אֶלָּא בְּךְ, שֶׁאַתָּה בַּמַּעֲרָב, וְכָתוּב (שם לה) אֲנִי אֵל שַׁדַּי פְּרֵה וּרְבֵה. לָמַדְנוּ שֶׁרָאָה עִמּוֹ שְׁכִינָה, וְאָז אָמַר בְּךְ יְבָרֵךְ יִשְׂרָאֵל לֵאמֹר. בְּךְ יְבָרֵךְ אֶת הָעוֹלָם."],[8,"","וְאֵיךָ רָאָה? וַהֲרֵי כָּתוּב (שם) וְעֵינֵי יִשְׂרָאֵל כָּבְדוּ מִזֹּקֶן וְגוֹ'? אֶלָּא כָּתוּב, שִׂכֵּל אֶת יָדָיו. מַה זֶּה שִׂכֵּל? אֶלָּא הַיָּמִין הָיָה זָקוּף, וְהַשְּׁכִינָה הֵסִיטָה כְּלַפֵּי אֶפְרַיִם, וְהֵרִיחַ רֵיחַ שְׁכִינָה עַל רֹאשׁוֹ, וְאָז אָמַר בְּךְ יְבָרֵךְ יִשְׂרָאֵל, וְרָאָה שֶׁהוּא בַּמַּעֲרָב."],[9,"","וַדַּאי שְׁכִינָה בַּמַּעֲרָב, וַהֲרֵי בֵּאַרְנוּ, כְּדֵי שֶׁיִּהְיֶה בֵּין צָפוֹן לְדָרוֹם, וּלְהִתְחַבֵּר בְּגוּף וְלִהְיוֹת בְּזִוּוּג אֶחָד. וְצָפוֹן מְקַבֵּל אוֹתָהּ תַּחַת הָרֹאשׁ, וְהַדָּרוֹם מְחַבֵּק אוֹתָהּ. זֶהוּ שֶׁכָּתוּב (שיר השירים ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. וַהֲרֵי בֵּאַרְנוּ וַדַּאי, (שם ג) מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, בֵּין צָפוֹן לְדָרוֹם, וּלְהִתְחַבֵּר בְּגוּף, וְאָז כְּלָל אֶחָד לְהִתְבָּרֵךְ הָעוֹלָם. לָמַדְנוּ, כָּל הָאוֹמֵר תְּהִלָּה לְדָוִד שָׁלֹשׁ פְּעָמִים בְּכָל יוֹם, מֻבְטָח לוֹ שֶׁהוּא בֶּן הָעוֹלָם הַבָּא. וַהֲרֵי בֵּאַרְנוּ, כְּדֵי לְזַוֵּג אֶת הַתְּהִלָּה הַזּוֹ, וְשֶׁתִּמָּצֵא בְּכָל יוֹם בֵּין צָפוֹן לְדָרוֹם."]]],[["אָתֵי בַּר נָשׁ בְּצַפְרָא, מְקַבֵּל עָלֵיהּ עוֹל מַלְכוּת שָׁמַיִם (כמה דאתמר מסדר שבחא) בְּאִינּוּן תּוּשְׁבְּחָן דְּקָאָמַר (עם) תְּהִלָּה לְדָוִד, וְכֻלְּהוּ הַלְלוּיָהּ דְּאִינּוּן סִדּוּרָא דַּעַשְׂרָה תּוּשְׁבְּחָן, דַּעַשְׂרָה כִּתְרִין קַדִּישִׁין דִּשְׁמָא קַדִּישָׁא. וּבְגִין כַּךְ עַשְׂרָה אִינּוּן הַלְלוּיָהּ. לְבָתַר סִיֵּים בַּעַשְׂרָה תּוּשְׁבְּחָן, דְּאִינּוּן (תהילים ק״נ:א׳) הַלְלוּיָהּ הַלְלוּ אֵל בְּקָדְשׁוֹ וְגוֹ'. הַלְלוּהוּ וְגוֹ'. מַאן אִינּוּן עַשְׂרָה הַלְלוּיָהּ, וְהָא חֲמִשָּׁה אִינּוּן. אֶלָּא שָׁרֵי שְׁבָחָא בְּהַלְלוּיָהּ, וְסִיֵּים בְּהַלְלוּיָהּ.","לְבָתַר עִלּוּיָא דְּסִדּוּר שְׁבָחָא, בְּאָז יָשִׁיר מֹשֶׁה, דְּאִית בֵּיהּ כֹּלָּא. וּבְדָא מְקַבֵּל עָלֵיהּ עוֹל מַלְכוּתָא קַדִּישָׁא. לְבָתַר אַשְׁרֵי לֵהּ בְּחֶסֶד, בְּסִיוּמָא דִּצְלוֹתָא, לְאִתְקַדְּשָׁא בֵּיהּ. לְבָתַר בִּצְלוֹתָא דְּמִנְחָה דִּגְבוּרָה תַּלְיָיא, וְדִינָא שָׁארֵי. אִשְׁתְּכַח בְּכָל דָּרוֹמָא (ס\"א יומא) דָּא מִטָּה דְּאִתְיְהִיבַת בֵּין צָפוֹן לְדָרוֹם. לְאִתְחַבְּרָא בְּזִוּוּגָא דָּא בְּגוּפָא כְּדְקָא יָאוּת. וּמַאן דִּמְסַדֵּר וּמְחַבֵּר לָהּ בְּכָל יוֹמָא כְּהַאי גַּוְונָא, וַדַּאי הוּא בֶּן העוֹלָם הַבָּא.","בְּגִין כַּךְ הַאי דֶּגֶל מַחֲנֵה אֶפְרַיִם יָמָּה, וְאִיהוּ בֵּין צָפוֹן לְדָרוֹם. דָּרוֹם רְאוּבֵן מִן סִטְרָא חַד, דִּכְתִּיב דֶּגֶל מַחֲנֵה רְאוּבֵן תֵּימָנָה. צָפוֹן דָּן מִסִּטְרָא אַחֲרָא, דִּכְתִּיב דֶּגֶל מַחֲנֵה דָן צָפוֹנָה. אֶפְרַיִם, בֵּין דָּא לְדָא. אִשְׁתְּכַח מַעֲרָב דְּאִיהוּ אֶפְרַיִם, בֵּין צָפוֹן לְדָרוֹם, כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא.","רָזָא לְיַתְבֵי דְּרוֹמָא אֲחוּנָא. וְהָכִי שָׁדַר לוֹן אֲחוּנָא, מִסִּטְרָא דְּבּוּצִינִין (ס\"א מסדרי בוצינין) בְּרָזִין קְטִירִין, דְּבָעִיתוּ לְיַחֲדָא יִחוּדָא בְּטוּפְסְרָא דְּקִטְרָא עִלָּאָה, קַבִּילוּ עָלַיְיכוּ עוֹל מַלְכוּתָא קַדִּישָׁא בְּכָל יוֹמָא בְּקַדְמִיתָא, וּבְדָא תַּעֲלוּן (ס\"א בקשורא) בְּקִסוּרָא (ס\"א בקסטרא) קַדִּישָׁא דְּדָרוֹם, וְאַסְחֲרוּ סִטְרֵי עָלְמָא, עַד דְּמִתְקַשְּׁרָן בְּקִטוּרָא חֲדָא, וּבְדָרוֹם תְּקִיפוּ (ס\"א תקיעו) דּוּכְתָּא, וְתַמָּן תִּשְׁרוּן.","רִבִּי אֶלְעָזָר שָׁאִיל לְרַבִּי שִׁמְעוֹן אֲבוֹי, אָמַר לֵיהּ, סִימָנָא לְזִוּוּגָא דְּיִחוּדָא מִנַּיִן. אָמַר לֵיהּ בְּרִי, אַף עַל גַּב דְּאוֹקִימְנָא מִלִּין לְכָל סְטָר וּסְטָר, וְאִתְבָּדָרוּ הָכָא מִלָּה וְהָכָא מִלָּה סִימָנָא דָּא נְקוֹט בִּידָךְ, וְהָכִי הוּא, כְּעֵין סָחֲרָא דְּמַדְבְּחָא, דִּתְנָן, וּבָא לוֹ לְקֶרֶן דְּרוֹמִית מִזְרָחִית, מִזְרָחִית צְפוֹנִית, צְפוֹנִית מַעֲרָבִית, מַעֲרָבִית דְּרוֹמִית. אָמַר לֵיהּ וְהָא לָא יָכִיל עַד דִּמְקַבָּל עָלֵיהּ בַּר נָשׁ עוֹל מַלְכוּתָא קַדִּישָׁא בְּקַדְמִיתָא, וְיָהִיב עָלֵיהּ עוֹל דָּא, וְאַתְּ אַמְרַת דְּיֵיתֵי לְדָּרוֹם בְּקַדְמִיתָא.","אָמַר לֵיהּ, כֹּלָּא הָא אֲמֵינָא לָךְ, דְּהָא וּבָא לוֹ לְקֶרֶן, אֲמֵינָא בְּקַדְמִיתָא, וְהָא יַדְעַתָא רָזָא דְּקֶרֶן, וְדָא הוּא עוֹל מַלְכוּתָא קַדִּישָׁא. לְבָתַר דְּרוֹמִית מִזְרָחִית, דְּתַמָּן הוּא אִילָנָא דְּחַיֵּי. וְדָא לְאִזְדַּוְּוגָא לֵיהּ בְּמִזְרָח דְּאִיהוּ אַבָּא עִלָּאָה. דְּהָא בֵּן מִסִּטְרָא דְּאַבָּא קָא אָתֵי. וּבְגִין כַּךְ, מִדָּרוֹם לְמִזְרָח, דְּתּוּקְפָּא דְּדָרוֹם בְּמִזְרָח הוּא, וּבָעֵי לְאִתְקַשְּׁרָא כַּחֲדָא, דָּרוֹם בְּמִזְרָח.","וּמִזְרָח דְּאִתְקְשַׁר בְּצָּפוֹן, (כמה דאת אמר (תהילים י״ז:י״ד) וצפונך תמלא בטנם) בְּגִין דְּהַאי אַשְׁלִים וּמַלֵּי נַחֲלִין וּמַבּוּעִין, וְעַל דָּא מִזְרָחִית צְפוֹנִית, אִלֵּין אַבָּא וְאִמָא דְּלָא מִתְפָּרְשָׁן לְעָלְמִין, וְהָא אוֹקִימְנָא. וּמַה דְּאִתְּמַר צְפוֹנִית, דְּאִיהוּ טְמִירָא עִלָּאָה, וּמִסְטַר דִּילָהּ נָפִיק צָפוֹן, וְדִינִין מִסִּטְרָא דִּילָהּ מִתְעָרִין, אַף עַל גַּב דְּהִיא רַחֲמֵי וְחֵידוּ. וְהָא אוֹקִימְנָא. וְכַד אִיהִי נָפְקַת, צָפוֹן נָפְקַת בֵּיהּ, דְּאִיהוּ אִתְכְּלִיל וְאִתְקְשַׁר בַּדָרוֹם.","לְבָתַר צְפוֹנִית מַעֲרָבִית, דְּהָא מִסִּטְרָא דְּאַבָּא נָפִיק בֵּן, וּמִסִּטְרָא דְּאִמָא נְפִיקַת בַּת. וּבְגִין כַּךְ צְפוֹנִית מַעֲרָבִית, וְדָא הוּא קֶרֶן דְּקַדְמֵיתָא, (ס\"ה ע\"א) דְּהַשְׁתָּא אִתְקְשַׁר בַּצָּפוֹן סְתָם. לְבָתַר בָּעֵי לְקַשְּׁרָא לָהּ בַּדָרוֹם, דְּתַמָּן הוּא קִשּׁוּרָא דְּכֹלָּא, וְגוּפָא בֵּיהּ אִשְׁתְּכַח, וְעַל דָּא מַעֲרָבִית דְּרוֹמִית.","אִשְׁתְּכַח הַאי קֶרֶן ג' זִמְנִין, חַד לְקַבְּלָא לֵיהּ בַּר נָשׁ בְּקַדְמִיתָא, וּלְבָתַר הָכִי לְקַשְּׁרָא לָהּ בִּתְרֵי דְּרוֹעֵי, לְאִתְחַבְּרָא בְּגוּפָא, וּלְמֶהֱוִי כֹּלָּא חַד. וְדָא הוּא סִדּוּרָא דְּיִחוּדָא שְׁלִים. וְכָל סְטָר וּסְטָר בְּהַהוּא קִשּׁוּרָא דְּאִתְחֲזֵי לֵיהּ, וְלָא יַחְלִיף סִטְרָא בְּסִטְרָא אַחֲרָא דְּלָא אִיתְחֲזֵי לֵיהּ, בְּגִין דְּלָא יִתְעַנָשׁ. מַאן דְּעָבִיד יִחוּדָא דָּא כַּדְקָא חֲזֵי כְּמָה דַּאֲמֵינָא, זַכָּאָה חוּלָקֵיהּ בְּהַאי עָלְמָא וּבְעָלְמָא דְּאָתֵי, דְּהָא יָדַע לְסַדְּרָא שְׁבָחָא דְּמָארֵיהּ, וְיִחוּדָא דְּמָארֵיהּ, וְלָא עוֹד אֶלָּא דְקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתְּבַּח בֵּיהּ. עָלֵיהּ כְּתִיב (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר."],[[0,"אתי בר נש","וכו': בא אדם בבוקר, מקבל עליו עול מלכות שמים באלו התשבחות שאומר, דהיינו, תהלה לדוד וכל אלו הללויה, שהם סדר של עשר תשבחות, של עשר ספירות הקדושות של השם הקדוש. ומשום זה יש עשר פעם הללויה. ואח\"כ מסיים בעשר תשבחות, שהם, הללויה הללו אל בקדשו וגו' הללוהו וגו'. שואל, איפה הם עשרה הללויה, והרי רק חמשה הם. כי אין רק ה' מזמורים שמתחילים בהללויה. ומשיב, אלא כל תשבחה מתחילה בהללויה ומסתיימת בהללויה. והם עשרה."],[1,"לבתר עלויא דסדור","וכו': ואח\"כ ערך סדור השבח של אז ישיר משה, שיש בו הכל. ובזה מקבל עליו עול מלכות הקדוש. אח\"כ משרה אותה בחסד, עם סיום התפלה, שתתקדש בו. כי תפלת שחרית היא כנגד אברהם שהוא חסד, וקו ימין. ואח\"כ בתפלת המנחה תלויה הגבורה והדין שורה. שהוא כנגד יצחק שהוא גבורה וקו שמאל. נמצא מטה זו, שהיא מלכות, נתונה בכל יום בין צפון לדרום, בין תפלת שחרית שה\"ס דרום לבין תפלת מנחה שה\"ס צפון. שתתחבר בזווג הזה בגוף שהוא ז\"א, קו האמצעי. כראוי. ומי שמסדר ומחבר המלכות בכל יום באפן הזה, ודאי הוא בן העולם הבא. כלומר שע\"ז אמרו כל האומר תהלה לדוד בכל יום מובטח לו שהוא בן עולם הבא (כנ\"ל אות נ\"ו)."],[2,"בגין כך האי","וכו': ומשום זה, דגל מחנה אפרים הוא ימה, במערב, והוא בין צפון לדרום, דרום הוא ראובן, הוא מצד אחד, שכתוב, דגל מחנה ראובן תימנה, צפון הוא דן מצד האחר, שכתוב, דגל מחנה דן צפונה. אפרים, בין זה לזה, כי ראובן שהוא דרום, לפניו, ודן, שהוא צפון, לאחריו, נמצא המערב שהוא אפרים, שהוא בין צפון לדרום, הכל כעין המלכות שלמעלה."],[3,"רזא ליתבי דרומא","וכו': סוד זה הוא לאחינו יושבי הדרום. וכך שלחו לנו אחינו, מסדרי המאורות, בסודות הקשרים, דהיינו היחודים, שאתם רוצים ליחד יחוד בסדר של קשר העליון, קבלו עליכם בכל יום עול מלכות הקדושה תחילה, ובזה תעלו עמה בקשר הקדוש של דרום, שהוא חסד, ותסבבו ד' רוחות העולם חו\"ג תו\"מ, עד שמתקשרים בקשר אחד, ובדרום, תקבעו המקום, ושם תשכנו. דהיינו כעין סבוב המזבח, כמ\"ש לפנינו."],[4,"ר' אלעזר שאיל","וכו': ר\"א שאל את ר\"ש אביו, אמר לו, סימן לזווג היחוד, כדי שלא נטעה, מאין, אמר לו, בני, אע\"פ שהעמדנו דברים לכל צד וצד, ונתפזרו הדברים, דבר כאן, ודבר כאן, סימן זה החזק בידך, וכך הוא, כעין סיבוב המזבח שלמדנו, ובא לו לקרן דרומית מזרחית, מזרחית צפונית, צפונית מערבית, מערבית דרומית. כמ\"ש לפנינו. אמר לו, והרי אינו יכול לעשות כלום עד שמקבל אדם עליו עול מלכות הקדושה בתחילה, ונותן על עצמו עול הזה, ואתה אמרת, שיבא לדרום תחילה. שהוא חסד."],[5,"א\"ל בלא הא אמינא","וכו': אמר לו, הרי אמרתי לך הכל. כי ובא לו לקרן, אמרתי בתחילה, והרי ידעת סוד הקרן, שהוא מלכות, וזה הוא עול מלכות הקדושה. ואח\"כ דרומית מזרחית, שיקשר הדרום שהוא חסד, במזרח שהוא ת\"ת, קו האמצעי, כי שם במזרח הוא עץ החיים, שהוא ת\"ת, וזה לזווג אותו, את הדרום, במזרח, שהוא אבא עלאה, דהיינו חכמה, הנקראת או\"א עלאין, כי בן, שהוא ת\"ת, מצד אבא בא, ששורש ת\"ת הוא בדעת הנעלם של או\"א עלאין ומשום זה ייחד מדרום למזרח, כי חיזוקו של דרום במזרח הוא, דהיינו בדעת הנעלם של או\"א, שהוא שירותא דמזרח וע\"כ צריך שיתקשרו יחד דרום ומזרח (כמ\"ש לעיל אות ל\"ו בהסולם, ע\"ש כל ההמשך)."],[6,"ומזרח דאתקשר בצפון","וכו': ומזרח המתקשר בצפון, שהוא באמא, שהיא בינה הנקראת ישסו\"ת שממנה נמשך צפון שהוא קו שמאל, משום שזה, דהיינו בינה, משלים וממלא הנחלים והמבועים של מזרח, שהוא דעת הנגלה והת\"ת, וע\"כ צריך ליחד מזרחית צפונית, דהיינו לקשר המזרח בבינה, ואלו מזרח וצפון, הם אבא ואמא שאינם מתפרשים לעולם, כי מזרח הוא דעת דאבא עלאה, שה\"ס או\"א עלאין. והדעת דאבא עלאה מתדבקת בדעת דאמא עלאה ובקו שמאל המתגלה בה שנקרא צפון (כמ\"ש שם). וכבר העמדנו. ומה שנאמר בה, באמא עלאה, צפונית, הוא משום שהיא צפונה העליונה, ומן הצד שלה יוצא הצפון שהוא קו שמאל. כי מצד אבא הצפון נסתר ונעלם (כמ\"ש שם) והדינים מתעוררים מן הצד שלה, אע\"פ שהיא רחמים ושמחה. וכבר העמדנו. וכשהיא אמא, יוצאת, הצפון יוצא בה, שממנה הצפון מתגלה. כי הוא, אבא, נכלל ונקשר בדרום. והצפון נעלם בו (כמ\"ש כל זה היטב בהסולם אות ל\"ו)."],[7,"לבתר צפונית מערבית","וכו': ואח\"כ, יבא לקרן צפונית מערבית. כי מצד אבא יוצא הבן, שהוא ת\"ת, מזרח. ומצד אמא, שהיא צפון יוצאת הבת, שהיא מלכות, מערב. ומשום זה צפונית מערבית, מצפון שהיא אמא למערב שהיא מלכות. וזו היא קרן שבתחילה, שקרן ה\"ס מלכות, שצריך לקבל עליו מקודם כל (כנ\"ל באות ס\"ב) ועתה היא נקראת בצפון סתם, דהיינו באמא ובקו שמאל, ולאח\"כ צריך לקשר אותה בדרום, שהוא חסד, וקו ימין, ששם הוא קשר הכל, והגוף, שהוא ז\"א, נמצא בו, כי ז\"א נמשך מאבא כנ\"ל, וע\"כ הוא נכלל כולו בדרום כמו אבא, והצפון נעלם בו. וע\"כ מערבית דרומית."],[8,"אשתכח האי קרן","וכו': ונמצאת קרן זו הרומזת על מלכות, ג' פעמים, אחד הוא, שהאדם צריך לקבל עליו תחילה (כנ\"ל אות ס\"ב) והקרן שלאחר כך, הוא לקשר המלכות בב' זרועות, שהם דרום וצפון, ימין ושמאל, להתחבר בגוף, שהוא ת\"ת קו האמצעי, ושיהיה הכל אחד. וזה הוא הסדר של יחוד השלם, וכל צד וצד ייחד בקשר ההוא הראוי לו, ולא יחליף צד בצד אחר שאינו ראוי לו, כדי שלא יענש. מי שעושה יחוד הזה כראוי כמו שאמרתי, אשרי חלקו בעולם הזה ובעולם הבא, להיותו יודע לסדר שבחו של אדונו ויחוד אדונו. ולא עוד, אלא שהקב\"ה משתבח בו. עליו כתוב, ויאמר לי עבדי אתה ישראל אשר בך אתפאר."]],[[0,"","בָּא אָדָם בַּבֹּקֶר - מְקַבֵּל עָלָיו עֹל מַלְכוּת שָׁמַיִם (כמו שנתבאר, מסדר שבח) בְּאוֹתָן תִּשְׁבָּחוֹת שֶׁאוֹמֵר תְּהִלָּה לְדָוִד, וְכָל הַהַלְלוּיָהּ, שֶׁהֵם סִדּוּר שֶׁל עֶשֶׂר תִּשְׁבָּחוֹת שֶׁל עֲשָׂרָה כְתָרִים קְדוֹשִׁים שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וּמִשּׁוּם זֶה עֲשָׂרָה הֵם הַלְלוּיָהּ. אַחַר כָּךְ סִיֵּם בְּעֶשֶׂר תִּשְׁבָּחוֹת, שֶׁהֵן: (תהלים קנ) הַלְלוּיָהּ הַלְלוּ אֵל בְּקָדְשׁוֹ וְגוֹ', הַלְלוּהוּ וְגוֹ'. מִי אֵלֶּה עֲשָׂרָה הַלְלוּיָהּ, וַהֲרֵי חֲמִשָּׁה הֵם? אֶלָּא מַתְחִיל שֶׁבַח בְּהַלְלוּיָהּ, וּמְסַיֵּם בְּהַלְלוּיָהּ."],[1,"","לְאַחַר הָעִלּוּי שֶׁל סִדּוּר הַשֶּׁבַח בְּאָז יָשִׁיר מֹשֶׁה, שֶׁיֵּשׁ בּוֹ הַכֹּל, וּבָזֶה מְקַבֵּל עָלָיו עֹל מַלְכוּת הַקְּדוֹשָׁה. אַחַר כָּךְ מַשְׁרֶה אוֹתָהּ בְּחֶסֶד בְּסוֹף הַתְּפִלָּה, לְהִתְקַדֵּשׁ בּוֹ. אַחַר כָּךְ בִּתְפִלַּת מִנְחָה, שֶׁהַגְּבוּרָה תְלוּיָה וְהַדִּין שׁוֹרֶה. נִמְצָא בְּכָל הַדָּרוֹם (היום) הַמִּטָּה הַזּוֹ שֶׁנְּתוּנָה בֵּין צָפוֹן לְדָרוֹם, לְהִתְחַבֵּר בְּזִוּוּג זֶה בַּגּוּף כָּרָאוּי. וּמִי שֶׁמְּסַדֵּר וּמְחַבֵּר אוֹתָהּ בְּכָל יוֹם כָּךְ, וַדַּאי הוּא בֶּן הָעוֹלָם הַבָּא."],[2,"","מִשּׁוּם כָּךְ דֶּגֶל שֶׁל מַחֲנֵה אֶפְרַיִם יָמָּה, וְהוּא בֵּין צָפוֹן לְדָרוֹם. דָּרוֹם רְאוּבֵן מִצַּד אֶחָד, שֶׁכָּתוּב דֶּגֶל מַחֲנֵה רְאוּבֵן תֵּימָנָה. צָפוֹן דָּן מִצַּד אַחֵר, שֶׁכָּתוּב דֶּגֶל מַחֲנֵה דָן צָפֹנָה. אֶפְרַיִם בֵּין זֶה לָזֶה. נִמְצָא מַעֲרָב, שֶׁהוּא אֶפְרַיִם, בֵּין צָפוֹן לְדָרוֹם, הַכֹּל כְּמוֹ לְמַעְלָה."],[3,"","סוֹד לְיוֹשְׁבֵי הַדָּרוֹם אַחֵינוּ. וְכָךְ שָׁלַח לָהֶם: אַחֵינוּ, מִצַּד הַמְּנוֹרוֹת (מסדרים מנורות) בְּסוֹדוֹת קְשׁוּרִים, שֶׁרְצִיתֶם לְיַחֵד יִחוּד בַּטֹּפֶס שֶׁל קֶשֶׁר עֶלְיוֹן, קַבְּלוּ עֲלֵיכֶם עֹל מַלְכוּת הַקְּדוֹשָׁה בְּכָל יוֹם בַּהַתְחָלָה, וּבָזֶה תַעֲלוּ (בקשר) בְּהֶעְלֵם (בהיכל) קָדוֹשׁ שֶׁל הַדָּרוֹם, וְסוֹבְבוּ צִדְדֵי הָעוֹלָם עַד שֶׁיִּתְקַשְּׁרוּ בְּקֶשֶׁר אֶחָד, וּבַדָּרוֹם (התחזקו) (תקבעו) מָקוֹם, וְשָׁם תִּהְיוּ."],[4,"","רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, סִימָן לְזִוּוּג הַיִּחוּד מִנַּיִן? אָמַר לוֹ, בְּנִי, אַף עַל גַּב שֶׁבֵּאַרְנוּ דְבָרִים לְכָל צַד וְצַד, וְהִתְפַּזְּרוּ כָּאן דָּבָר וְכָאן דָּבָר - סִימָן זֶה נְקֹט בְּיָדְךְ, וְכָךְ זֶה, כְּמוֹ סְבִיב הַמִּזְבֵּחַ. שֶׁלָּמַדְנוּ, וּבָא לוֹ לְקֶרֶן דְּרוֹמִית מִזְרָחִית, מִזְרָחִית צְפוֹנִית, צְפוֹנִית מַעֲרָבִית, מַעֲרָבִית דְּרוֹמִית. אָמַר לוֹ, וַהֲרֵי לֹא יָכוֹל עַד שֶׁמְּקַבֵּל עָלָיו אָדָם עֹל מַלְכוּת הַקְּדוֹשָׁה בַּתְּחִלָּה וְנוֹתֵן עָלָיו עֹל זֶה, וְאַתָּה אָמַרְתָּ שֶׁיָּבא לַדָּרוֹם בַּתְּחִלָּה?!"],[5,"","אָמַר לוֹ, הַכֹּל אָמַרְתִּי לְךְ, שֶׁהֲרֵי וּבָא לוֹ לְקֶרֶן, אָמַרְתִּי בַּהַתְחָלָה, וַהֲרֵי יָדַעְתָּ סוֹד הַקֶּרֶן, וְזֶהוּ עֹל מַלְכוּת הַקְּדוֹשָׁה. אַחַר כָּךְ דְּרוֹמִית מִזְרָחִית, שֶׁשָּׁם הוּא עֵץ הַחַיִים, וְזֶה לְזַוֵּג אוֹתוֹ בַּמִּזְרָח, שֶׁהוּא הָאָב הָעֶלְיוֹן, שֶׁהֲרֵי הַבֵּן מִצַּד אַבָּא הוּא בָּא. וְלָכֵן מִדָּרוֹם לַמִּזְבֵּחַ, שֶׁכֹּחַ הַדָּרוֹם הוּא בַּמִּזְרָח, וְצָרִיךְ לְהִתְקַשֵּׁר כְּאֶחָד, דָּרוֹם בְּמִזְרָח."],[6,"","וְהַמִּזְרָח שֶׁמִּתְקַשֵּׁר בַּצָּפוֹן, (כמו שנאמר (תהלים יז) וצפונך תמלא בטנם) מִשּׁוּם שֶׁזֶּה מַשְׁלִים וּמְמַלֵּא נְחָלִים וּמַעְיָנוֹת, וְעַל זֶה מִזְרָחִית צְפוֹנִית, אֵלּוּ אַבָּא וְאִמָּא שֶׁלֹּא נִפְרָדִים לְעוֹלָם, וַהֲרֵי בֵּאַרְנוּ. וּמַה שֶּׁנֶּאֱמַר צְפוֹנִית, שֶׁהוּא סֵתֶר עֶלְיוֹן, וּמִצִּדָּהּ יוֹצֵא צָפוֹן, וּמִצִּדָּהּ מִתְעוֹרְרִים הַדִּינִים, אַף עַל גַּב שֶׁהִיא רַחֲמִים וְשִׂמְחָה. וַהֲרֵי בֵּאַרְנוּ. וּכְשֶׁהִיא יוֹצֵאת - צָפוֹן יוֹצֵא עִמָּהּ, שֶׁהוּא נִכְלָל וְנִקְשָׁר בַּדָּרוֹם."],[7,"","אַחַר כָּךְ צְפוֹנִית מַעֲרָבִית, שֶׁהֲרֵי מִצַּד הָאַבָּא יוֹצֵא בֵּן, וּמִצַּד הָאִמָּא יוֹצֵאת בַּת, וּמִשּׁוּם כָּךְ צְפוֹנִית מַעֲרָבִית, וְזוֹהִי קֶרֶן שֶׁל הַתְחָלָה, שֶׁכָּעֵת נִקְשֶׁרֶת בַּצָּפוֹן סְתָם. אַחַר כָּךְ צָרִיךְ לְקָשְׁרָהּ בַּדָּרוֹם, שֶׁשָּׁם הוּא קֶשֶׁר הַכֹּל, וְהַגּוּף בָּהּ נִמְצָא, וְעַל כָּךְ מַעֲרָבִית דְּרוֹמִית."],[8,"","נִמְצֵאת קֶרֶן זוֹ שָׁלֹשׁ פְּעָמִים: אַחַת לְקַבֵּל אוֹתָהּ אָדָם בַּתְּחִלָּה, אַחַר כָּךְ לְקָשְׁרָהּ בִּשְׁתֵּי זְרוֹעוֹת, לְהִתְחַבֵּר בַּגּוּף וְלִהְיוֹת הַכֹּל אֶחָד. וְזֶהוּ סִדּוּר שֶׁל הַיִּחוּד הַשָּׁלֵם. וְכָל צַד וְצַד בְּאוֹתוֹ קֶשֶׁר שֶׁרָאוּי לוֹ, וְלֹא יַחֲלִיף צַד בְּצַד אַחֵר שֶׁלֹּא רָאוּי לוֹ, כְּדֵי שֶׁלֹּא יֵעָנֵשׁ. מִי שֶׁעוֹשֶׂה יִחוּד זֶה כָּרָאוּי כְּפִי שֶׁאָמַרְנוּ, אַשְׁרֵי חֶלְקוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֲרֵי יוֹדֵעַ לְסַדֵּר שֶׁבַח רִבּוֹנוֹ וְיִחוּד רִבּוֹנוֹ, וְלֹא עוֹד, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ. עָלָיו כָּתוּב, (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר."]]],[["רִבִּי שִׁמְעוֹן פָּתַח (תהילים כ״ה:א׳-ב׳) לְדָוִד אֵלֶיךָ יְיָ נַפְשִׁי אֶשָּׂא אֱלֹהַי בְּךָ בָטַחְתִּי וְגוֹ', מַאי קָא חָמָא דָּוִד לְסַדְּרָא הַאי שְׁבָחָא הָכִי. וְכֻלְּהוּ שְׁבָחֵי דְּאִינּוּן בְּאַלְפָא בֵּיתָא כֻּלְּהוּ שְׁלֵמִין, וְהַאי חַסְרָא דְּלָא אִית בֵּיהּ ו'. וַאֲמַאי סִדּוּרָא דָּא לְמִנְפַּל עַל אַנְפִּין.","אֶלָּא (תא חזי) רָזָא עִלָּאָה הוּא, גָּנִיז בֵּין חַבְרַיָּיא. בְּשַׁעֲתָא דְּלֵילְיָא עָאל, (ושלטא) אִילָנָא תַּתָּאָה דְּתַלְיָיא בֵּיהּ מוֹתָא פָּרִישׁ עַנְפּוֹי וּמְכַסְּיָא לְכֹלָּא. וְעַל דָּא אִתְחֲשָׁךְ. וְכָל בְּנֵי עָלְמָא טַעֲמִין טַעֲמָא דְּמוֹתָא, וְאַקְדִּים בַּר נָשׁ וְיָהִיב לֵיהּ פִּקְדוֹנָא דְּנַפְשֵׁיהּ, וְאַפְקְדֵיהּ בִּידֵיהּ בְּפִקְדוֹנָא. וּבְגִין דְּנָטִיל לוֹן בְּפִקְדוֹנָא, תָּב פִּקְדוֹנָא לְמָארֵיהּ בְּשַׁעֲתָא דְּאָתֵי צַפְרָא. כַּד אָתֵי צַפְרָא וְתָב לְגַבֵּיהּ פִּקְדוֹנֵיהּ, בָּעֵי לְבָרְכָא לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ מְהֵימָנָא עִלָּאָה.","לְבָתַר דְּקָם, עָאל לְבֵי כְּנִישְׁתָּא, מִעְטַּר בְּטוֹטְפֵי. אִתְכְּסֵּי בְּכִיסוּי דְּצִיצִית. עָאל וּמַדְכֵּי גַּרְמֵיהּ בְּקוּרְבְּנִין בְּקַדְמִיתָא. לְבָתַר קַבִּיל עָלֵיהּ עוֹל מַלְכוּתָא בְּסִדּוּרָא דִּשְׁבָחֵי דְּדָוִד, דְּאִינּוּן סִדּוּרָא דְּעוֹל מַלְכוּתָא. וּבְסִדּוּרָא דִּשְׁבָחָא דָּא, אַשְׁרָא עָלֵיהּ הַהוּא עוֹל. לְבָתַר סִדּוּרָא דִּצְלוֹתָא דִּמְיוּשָׁב, וּצְלוֹתָא דִּמְעוּמָד, לְקַשְּׁרָא לוֹן כַּחֲדָא.","תָּא חֲזֵי רָזָא דְּמִלָּה אַף עַל גַּב דִּצְלוֹתָא תַּלְיָיא בְּמִלּוּלָא וְדִבּוּרָא דְּפוּמָא, כֹּלָּא תַּלְיָיא בְּעִקָרָא דְּעוֹבָדָא בְּקַדְמִיתָא, וּלְבָתַר בְּדִבּוּרָא וּבְמִלּוּלָא דְּפוּמָא. מַאן עוֹבָדָא, אֶלָּא הַהוּא עוֹבָדָא דְּעָבִיד בַּר נָשׁ בְּקַדְמִיתָא, כְּגַוְונָא דִּצְלוֹתָא הוּא, וְלָא יִצְלֵי בַּר נָשׁ צְלוֹתָא, עַד דְּיִתְחֲזֵי עוֹבָדָא בְּקַדְמִיתָא כְּגַוְונָא דִּצְלוֹתָא. (שמות ר\"א ע\"ב)","עוֹבָדָא דְקַדְמֵיתָא (ס\"א בקדמיתא עובדא) בְּשַׁעֲתָא דְּבַר נָשׁ קָאִים, בָּעֵי לְדַכְּאָה גַּרְמֵיהּ בְּקַדְמִיתָא. וּלְבָתַר יְקַבֵּל עָלֵיהּ הַאי עוֹל, לְפָרְשָׂא עַל רֵישֵׁיהּ פְּרִישׂוּ דְּמִצְוָה. לְבָתַר יִתְקְשַׁר קִשּׁוּרָא דְּיִחוּדָא דְּאִינּוּן תְּפִלִּין, (מהו תפלין) תְּפִלָּה שֶׁל רֹאשׁ, וְשֶׁל יַד. וּלְאַתְקְנָא לוֹן בְּקִשּׁוּרָא חֲדָא בִּשְׂמָאלָא, וְעַל לִבָּא, כְּמָה דְּאוֹקִימְנָא (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וְגוֹ'. וּכְתִיב (שיר השירים ח׳:ו׳) שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ כַּחוֹתָם עַל זְרוֹעֶךָ. וְהָא אוֹקִימְנָא. וְדָא הוּא עוֹבָדָא בְּקַדְמִיתָא.","לְבָתַר בְּשַׁעֲתָא דְּבַּר נָשׁ עָאל לְבֵי כְּנִישְׁתָּא, יִדְכֵּי גַּרְמֵיהּ בְּקַדְמִיתָא, בְּקָרְבְּנִין, בְּמִלּוּלָא דְּפוּמָא. לְבָתַר יְקַבֵּל עָלֵיהּ הַאי עוֹל מַלְכוּת, לְפָרְשָׂא עַל רֵישֵׁיהּ (פרישו דמצוה) בְּשִׁבְחֵי דְּדָוִד מַלְכָּא. כְּגַוְונָא דְּעוֹבָדָא דְּפָרִישׂ עַל רֵישֵׁיהּ פְּרִישׂוּ דְּמִצְוָה. וּלְבָתַר צְלוֹתָא דִּמְיוּשָׁב, לָקֳבֵל תְּפִלָּה שֶׁל יַד. לְבָתַר צְלוֹתָא דִּמְעוּמָד, דְּהִיא לָקֳבֵל תְּפִלָּה דְּרֵישָׁא. וְדָא כְּגַוְונָא דְּדָא. עוֹבָדָא כְּגַוְונָא דְּדִבּוּרָא. וַדַּאי בְּעוֹבָדָא וּמִלּוּלָא תַּלְיָיא צְלוֹתָא.","וְאִי פָּגִים עוֹבָדָא, מִלּוּלָא לָא אַשְׁכַּח אֲתָר דְּשַׁרְיָא בֵּיהּ, וְלָאו אִיהוּ צְלוֹתָא, וְאִתְפְּגִים הַהוּא בַּר נָשׁ לְעֵילָּא וְתַתָּא. (ולא עוד אלא) דְּבָעֵינָן לְאַחֲזָאָה עוֹבָדָא, וּלְמַלְּלָא מִלּוּלָא עָלֵיהּ, וְדָא הוּא צְלוֹתָא שְׁלִים. וַוי לֵיהּ לְבַר נָשׁ דְּפָגִים צְלוֹתֵיהּ, פּוּלְחָנָא דְּמָארֵיהּ. עָלֵיהּ כְּתִיב, (ישעיהו א׳:ט״ו) כִּי תָבוֹאוּ לֵרָאוֹת פָּנָי וְגוֹ'. גַּם כִּי תַרְבּוּ תְפִלָּה אֵינֶנִּי שׁוֹמֵעַ, דְּהָא בְּעוֹבָדָא וּבְמִלּוּלָא תַּלְיָא מִלְּתָא.","תָּא חֲזֵי, כֵּיוָן דְּבַר נָשׁ עָבִיד צְלוֹתָא כְּגַוְונָא דָּא, בְּעוֹבָדָא וּבְמִלּוּלָא, וְקָשִׁיר קִשּׁוּרָא דְּיִיחוּדָא, אִשְׁתְּכַח דְּעַל יְדֵיהּ מִתְבָּרְכָן עִלָּאִין וְתַתָּאִין. כְּדֵין בָּעֵי לֵיהּ לְבַר נָשׁ לְאַחֲזָאָה גַּרְמֵיהּ, בָּתַר דְּסִיֵּים צְלוֹתָא דַּעֲמִידָה, כְּאִלּוּ אִתְפְּטַר מִן עָלְמָא, דְּהָא אִתְפְּרַשׁ מִן אִילָנָא דְּחַיֵּי, וְכָנִישׁ רַגְלוֹי לְגַבֵּי הַהוּא אִילָנָא דְּמוֹתָא, דְּאָהֲדָר לֵיהּ פִּקְדוֹנֵיהּ. כְּמָה דְאַתְּ אָמֵר (בראשית מ״ט:ל״ג) וַיֶּאֱסוֹף רַגְלָיו אֶל הַמִּטָּה. דְּהָא אוֹדֵי חֶטְאוֹי, וְצַלֵּי עָלַיְיהוּ. הַשְׁתָּא בָּעֵי לְאִתְכַּנְּשָׁא לְגַבֵּי הַהוּא אִילָנָא דְּמוֹתָא, וּלְמִנְפַּל, וְלֵימָא לְגַבֵּיהּ אֵלֶיךָ יְיָ נַפְשִׁי אֶשָּׂא. בְּקַדְמִיתָא, יָהִיבְנָא לָךְ בְּפִקְדוֹנָא, הַשְׁתָּא דְּקַשִׁירְנָא יִיחוּדָא, וְעָבֵידְנָא עוֹבָדָא וּמִלּוּלָא כְּדְקָא יֵאוֹת, וְאוֹדֵינָא עַל חֲטָאַי, הָא נַפְשִׁי מָסִירְנָא לָךְ וַדַּאי."],[[0,"ר\"ש פתח","וכו': ר' שמעון פתח, לדוד אליך ה' נפשי אשא אלקי בך בטחתי וגו'. שואל, מה ראה דוד לסדר שבח זה כך, שכל השבחים שהם בסדר אלף בית כולם שלמים, וזה חסר, שאין בו \u0003ו'.\u0004 ולמה הוא סדר זה, לנפילת אפים."],[1,"אלא רזא עלאה","וכו': ומשיב אלא סוד עליון הוא גנוז בין החברים. בשעה שנכנס הלילה, אילן התחתון שהמות תלוי בו, שהוא מלכות מצד הדין, פורש ענפיו ומכסה הכל. וע\"כ, נעשה חשך, וכל בני העולם טועמים טעם המות. ואדם מקדים עצמו ונותן לו פקדון נפשו, ומפקידה בידו בפקדון. למשך זמן הלילה, שיחזירה לאור הבקר. ומשום שלקח הנפש בפקדון, חוזר הפקדון לבעלו בשעה שבא הבוקר. וכשבא הבוקר, והפקדון חזר אליו, צריך לברך את הקב\"ה, שהוא נאמן העליון."],[2,"לבתר דקם עאל","וכו': אחר שקם משנתו, נכנס לבית הכנסת, מעטר עצמו בתפלין, ומתכסה בכסוי של ציצית, נכנס ומטהר עצמו תחילה בקרבנות. לאחר כך מקבל עליו עול מלכות בסדר השבחים של דוד, שהם סדר של עול מלכות, ובסדר שבחים זה, הוא משרה עליו עול ההוא. לאחר כך סדר תפלה דמיושב, שהיא כנגד המלכות. וסדר תפלה דמעומד שהוא כנגד ז\"א, לקשר אותם, ז\"א ומלכות, ביחד."],[3,"ת\"ח רזא דמלה","וכו': בוא וראה, סוד הדבר, אע\"פ שהתפלה תלויה בדבור, ובדבור הפה, הכל תלוי בעיקר בתחילה במעשה, ולאח\"כ בדבור, ובדבור הפה. מהו המעשה. אלא מעשה ההוא שעושה אדם תחילה. הוא כעין התפלה, ולא יתפלל אדם תפלה, עד שיראה מעשה תחילה כעין התפלה."],[4,"עובדא דקדמיתא בשעתא","וכו': המעשה שבתחילה, הוא בשעה שאדם קם משנתו, צריך לטהר עצמו תחילה, דהיינו שיעשה צרכיו, ואח\"כ יקבל עליו עול הזה, לפרוש על ראשו פרשות של מצוה. לאח\"כ יקשור קשר היחוד, שהם תפלין, תפלה של ראש ותפלה של יד, ולתקן אותם בקשר אחד בשמאל, ועל הלב. כמו שהעמדנו שמאלו תחת לראשי. וכתוב, שימני כחותם על לבך כחותם על זרועך. דהיינו תפלה של יד, שה\"ס המלכות שניתנה על הזרוע כנגד הלב. וכבר העמדנו. וזה הוא המעשה, שצריך לעשות בתחילה."],[5,"לבתר בשעתא דב\"נ","וכו': לאחר כך, בשעה שאדם נכנס לבית הכנסת, יטהר עצמו תחילה בקרבנות, בדבור הפה. דהיינו שיאמר פרשת הקרבנות. ואח\"כ יקבל עליו עול מלכות לפרוש על ראשו, בשבחים של דוד המלך, כעין המעשה של הפורש על ראשו פרשות של מצוה. שהוא כנגד המעשה דציצית ולאח\"כ תפלה דמיושב, שהוא כנגד המעשה של תפלה של יד. דהיינו המלכות. ולאח\"כ תפלה דמעומד, שהיא סוד ז\"א, שהוא כנגד המעשה של תפילין של ראש. וזה כנגד זה, המעשה צריך להיות כעין הדבור, כי ודאי במעשה ודבור תלויה התפלה."],[6,"ואי פגים עובדא","וכו': ואם פוגם המעשה, אין הדבור מוצא מקום לשרות עליו, והוא אינה תפלה, ואדם ההוא נפגם למעלה ולמטה. כי צריכים להראות מעשה ולדבר עליו דבור, וזו היא תפלה שלמה. אוי לאדם שפוגם תפלתו עבודת אדונו, עליו כתוב, כי תבואו לראות פני וגו'. גם כי תרבו תפלה אינני שומע. כי במעשה ובדבור תלוי הדבר."],[7,"ת\"ח כיון דבר נש","וכו': בוא וראה, כיון שהאדם עשה תפלתו כאפן הזה במעשה ובדבור, וקשר קשר היחוד, נמצא שעליונים ותחתונים מתברכים על ידו. אז, אחר שגמר תפלת העמידה, צריך האדם להראות את עצמו, כאלו נפטר מן העולם. שהרי נפרד מן עץ החיים, שהוא ז\"א, שה\"ס תפלת העמידה, ואסף רגליו אל אותו אילן המות, שהחזיר לו פקדונו, שהחזיר לו נפשו בבקר (כנ\"ל אות ס\"ז) כש\"א ויאסוף רגליו אל המטה. כי כבר התוודה על חטאיו והתפלל עליהם, עתה צריך להיות נאסף אל אותו אילן המות, ולפול על פניו, ויאמר אליו, אליך ה' נפשי אשא. בתחילה כשהלכתי לישון, נתתי לך הנפש בפקדון, עתה שקשרתי היחוד, ועשיתי המעשה והדבור כראוי, והתודיתי על חטאי, הרי נפשי מסורה לך ודאי. כלומר שיקבל עליו מסירות נפש."]],[[0,"","רַבִּי שִׁמְעוֹן פָּתַח, (תהלים כה) לְדָוִד אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא אֱלֹהַי בְּךְ בָטַחְתִּי וְגוֹ'. מָה רָאָה דָוִד לְסַדֵּר שֶׁבַח זֶה כָּכָה? וְכָל הַשְּׁבָחִים שֶׁהֵם בְּא\"ב, כֻּלָּם שְׁלֵמִים, וְזֶה חָסֵר, שֶׁאֵין בּוֹ ו'? וְלָמָּה סִדּוּר זֶה לִפֹּל עַל אַפַּיִם?"],[1,"","אֶלָּא סוֹד עֶלְיוֹן הוּא גָּנוּז בֵּין הַחֲבֵרִים. בְּשָׁעָה שֶׁנִּכְנָס הַלַּיְלָה, (ושולט) הָעֵץ הַתַּחְתּוֹן שֶׁהַמָּוֶת תָּלוּי בּוֹ, פּוֹרֵשׂ עֲנָפָיו וּמְכַסֶּה הַכֹּל. וְעַל כָּךְ מַחְשִׁיךְ, וְכָל בְּנֵי הָעוֹלָם טוֹעֲמִים טַעַם הַמָּוֶת, וּמַקְדִּים אָדָם וְנוֹתֵן פִּקְדוֹן נַפְשׁוֹ, וּמַפְקִיד בְּיָדוֹ בְּפִקָּדוֹן. וּמִשּׁוּם שֶׁלּוֹקֵחַ אוֹתָם בְּפִקָּדוֹן, חוֹזֵר הַפִּקָּדוֹן לִבְעָלָיו בְּשָׁעָה שֶׁמַּגִּיעַ הַבֹּקֶר. כְּשֶׁמַּגִּיעַ הַבֹּקֶר וְחוֹזֵר אֵלָיו פִּקְדוֹנוֹ, צָרִיךְ לְבָרֵךְ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא הַנֶּאֱמָן הָעֶלְיוֹן."],[2,"","אַחֲרֵי שֶׁקָּם, נִכְנָס לְבֵית הַכְּנֶסֶת, מִתְעַטֵּר בִּתְפִלִּין, מִתְכַּסֶּה בְּכִסּוּי צִיצִית, נִכְנָס וּמְטַהֵר עַצְמוֹ בַּקָּרְבָּנוֹת בַּתְּחִלָּה, אַחַר כָּךְ מְקַבֵּל עָלָיו עֹל מַלְכוּת בַּסִּדּוּר שֶׁל שִׁבְחֵי דָוִד, שֶׁהֵם סִדּוּר שֶׁל עֹל מַלְכוּת. וּבְסִדּוּר שֶׁבַח זֶה מַשְׁרֶה עָלָיו אוֹתוֹ עֹל. אַחַר כָּךְ סִדּוּר תְּפִלַּת מִיֹּשֶׁב, וּתְפִלָּה מֵעֹמֶד, לְקָשְׁרָם כְּאֶחָד."],[3,"","בֹּא רְאֵה סוֹד הַדָּבָר, אַף עַל גַּב שֶׁתְּפִלָּה תְּלוּיָה בְּמֶלֶל וְדִבּוּר הַפֶּה - הַכֹּל תָּלוּי בְּעִקַּר הַמַּעֲשֶׂה בַּתְּחִלָּה, אַחַר כָּךְ בְּדִבּוּר וּבְמֶלֶל הַפֶּה. אֵיזֶה מַעֲשֶׂה? אֶלָּא אוֹתוֹ מַעֲשֶׂה שֶׁעוֹשֶׂה הָאָדָם בַּתְּחִלָּה כְּמוֹ תְּפִלָּה זוֹ. וְלֹא יִתְפַּלֵּל אָדָם תְּפִלָּה, עַד שֶׁיִּרְאֶה מַעֲשֶׂה בַּתְּחִלָּה כְּמוֹ הַתְּפִלָּה."],[4,"","מַעָשֶׂה רִאשׁוֹן (בראשונה מעשה) בְּשָׁעָה שֶׁאָדָם קָם - צָרִיךְ לְטַהֵר עַצְמוֹ בַּתְּחִלָּה, וְאַחַר כָּךְ יְקַבֵּל עָלָיו עֹל זֶה, יִפְרֹשׂ עַל רֹאשׁוֹ פְּרִיסַת מִצְוָה. אַחַר כָּךְ יִקָּשֵׁר קֶשֶׁר הַיִּחוּד, שֶׁהֵם תְּפִלִּין, (מהו תפלין, ') תְּפִלָּה שֶׁל רֹאשׁ וְשֶׁל יָד, וּלְתַקְּנָם בְּקֶשֶׁר אֶחָד בִּשְׂמֹאל וְעַל הַלֵּב, כְּפִי שֶׁבֵּאַרְנוּ (שיר השירים ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וְגוֹ'. וְכָתוּב (שם ח) שִׂימֵנִי כַחוֹתָם עַל לִבֶּךְ כַּחוֹתָם עַל זְרוֹעֶךְ. וַהֲרֵי בֵּאַרְנוּ. וְזֶהוּ הַמַּעֲשֶׂה שֶׁבַּתְּחִלָּה."],[5,"","אַחַר כָּךְ, בְּשָׁעָה שֶׁאָדָם נִכְנָס לְבֵית הַכְּנֶסֶת, יְטַהֵר עַצְמוֹ בַּתְּחִלָּה בַּקָּרְבָּנוֹת, בְּדִבּוּר הַפֶּה. אַחַר כָּךְ יְקַבֵּל עָלָיו עֹל מַלְכוּת זֶה, לִפְרֹשׂ עַל רֹאשׁוֹ (פרישת מצוה) בְּשִׁבְחֵי דָּוִד הַמֶּלֶךְ, כְּמוֹ הַמַּעֲשֶׂה שֶׁפּוֹרֵס עַל רֹאשׁוֹ פְּרִישַׂת מִצְוָה. אַחַר כָּךְ תְּפִלַּת מִיֹּשֶׁב כְּנֶגֶד תְּפִלִּין שֶׁל יָד, וְאַחַר כָּךְ תְּפִלַּת מֵעֹמֶד שֶׁהִיא כְּנֶגֶד תְּפִלִּין שֶׁל רֹאשׁ. וְזֶה כְּמוֹ זֶה. מַעֲשֶׂה כְּמוֹ דִבּוּר. וַדַּאי בְּמַעֲשֶׂה וְדִבּוּר תְּלוּיָה הַתְּפִלָּה."],[6,"","וְאִם פּוֹגֵם אֶת הַמַּעֲשֶׂה, הַדִּבּוּר לֹא מוֹצֵא מָקוֹם שֶׁשּׁוֹרֶה בּוֹ, וְזוֹ לֹא תְפִלָּה, וְנִפְגָּם הָאִישׁ הַהוּא לְמַעְלָה וּלְמַטָּה, (ולא עוד, אלא) שֶׁצָּרִיךְ לְהַרְאוֹת מַעֲשֶׂה וּלְמַלֵּל דִּבּוּר עָלָיו, וְזוֹהִי תְּפִלָּה שְׁלֵמָה. אוֹי לָאִישׁ שֶׁפּוֹגֵם בִּתְפִלָּתוֹ, עֲבוֹדַת רִבּוֹנוֹ, עָלָיו כָּתוּב (ישעיה א) כי תבאו לראות פני וגו'. גם כי תרבו תפלה אינני שמע. שהרי במעשה ודבור הדבר תלוי."],[7,"","בֹּא רְאֵה, כֵּיוָן שֶׁאָדָם עוֹשֶׂה תְפִלּוֹת כָּךְ, בְּמַעֲשֶׂה וּבְדִבּוּר, וְקוֹשֵׁר קֶשֶׁר הַיִּחוּד, נִמְצָא שֶׁעַל יָדוֹ מִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים. וְאָז צָרִיךְ הָאָדָם לְהַרְאוֹת עַצְמוֹ, אַחֲרֵי שֶׁסִּיֵּם תְּפִלַּת עֲמִידָה, כְּאִלּוּ נִפְטָר מִן הָעוֹלָם, שֶׁהֲרֵי נִפְרָד מֵעֵץ הַחַיִּים וְכִנֵּס רַגְלָיו לְאוֹתוֹ עֵץ הַמָּוֶת, שֶׁהֶחֱזִיר לוֹ פִּקְדוֹנוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מט) וַיֶּאֱסֹף רַגְלָיו אֶל הַמִּטָּה, שֶׁהֲרֵי הוֹדָה עַל חֲטָאָיו וְהִתְפַּלֵּל עֲלֵיהֶם. עַכְשָׁו צָרִיךְ לְהִתְכַּנֵּס לְאוֹתוֹ עֵץ הַמָּוֶת, וְלִנְפֹּל וְלוֹמַר אֵלָיו, אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא. בַּהַתְחָלָה נָתַתִּי לְךְ בְּפִקָּדוֹן. כָּעֵת שֶׁקָּשַׁרְתִּי אֶת הַיִּחוּד וְעָשִׂיתִי מַעֲשֶׂה וְדִבּוּר כָּרָאוּי וְהוֹדֵיתִי עַל חֲטָאַי, הֲרֵי נַפְשִׁי מָסַרְתִּי לְךְ בְּוַדַּאי."]]],[["וְיֶחֶזֵי בַּר נָשׁ גַּרְמֵיהּ כְּאִילּוּ פָּטִיר מִן עָלְמָא, דְּנַפְשֵׁיהּ מָסִיר לְהַאי אֲתָר דְּמוֹתָא, בְּגִין כַּךְ לָא אִית בֵּיהּ וָא\"ו, דְּוָא\"ו אִילָנָא דְּחַיֵּי הוּא, וְהַאי אִילָנָא דְּמוֹתָא הוּא. וְהָא קָא מַשְׁמַע לָן, דְּרָזָא דְּמִלָּה, (מאי קא משמע לן רזא דמלה) דְּאִית חוֹבִין דְּלָא מִתְכַּפְּרָן, עַד דְּאִתְפְּטַר בַּר נָשׁ מֵעָלְמָא, הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ב:י״ד) אִם יְכוּפַּר הֶעָוֹן הַזֶּה לָכֶם עַד תְּמוּתוּן, וְהַאי יָהִיב גַּרְמֵיהּ וַדַּאי לְמוֹתָא, וּמָסִיר נַפְשֵׁיהּ לְהַאי אֲתָר. לָאו בְּפִקְדוֹנָא כְּמָה בְּלֵילְיָא, אֶלָּא כְּמַאן דְּאִתְפְּטָר מִן עָלְמָא וַדַּאי.","וְתִקּוּנָא דָּא בָּעֵי בְּכַוָּונָא דְּלִבָּא וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא מְרַחֵם עֲלוֹי, וּמְכַפֵּר לֵיהּ לְחוֹבֵיהּ. זַכָּאָה הוּא בַּר נָשׁ דְּיָדַע לְמִפְּתֵּי לֵיהּ, וּלְמִפְלַח לְמָארֵיהּ, בִּרְעוּתָא וּבְכַוָּונָא דְּלִבָּא. וַוי לֵיהּ לְמַאן דְּאָתֵי לְמִפְתֵּי לְמָארֵיהּ, בְּלִבָּא רְחִיקָא, וְלָא בִּרְעוּתָא. כְּמָה דְאַתְּ אָמֵר (תהילים ע״ח:ל״ו-ל״ז) וַיְפַתּוּהוּ בְּפִיהֶם וּבִלְשׁוֹנָם יְכַזְּבוּ לוֹ וְלִבָּם לֹא נָכוֹן עִמּוֹ. הוּא אוֹמֵר (תהילים כ״ה:א׳) אֵלֶיךָ יְיָ נַפְשִׁי אֶשָּׂא, וְלָאו כָּל מִלּוֹי אֶלָּא בְּלִבָּא רְחִיקָא, הָא גָּרַם עָלֵיהּ לְאִסְתַּלְּקָא מֵעָלְמָא, עַד לָא מָטוּן יוֹמוֹי, בְּזִמְנָא דְּהָא אִילָנָא אִתְּעַר בְּעָלְמָא לְמֶעְבַּד דִּינָא.","וְעַל דָּא בָּעֵי בַּר נָשׁ לְאַדְבְּקָא נַפְשֵׁיהּ וּרְעוּתֵיהּ בְּמָארֵיהּ, וְלָא יֵיתֵי לְגַבֵּיהּ בִּרְעוּתָא כְּדִיבָא, בְּגִין דִּכְתִּיב, (תהילים ק״א:ז׳) דּוֹבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עֵינָי. מַאי לֹא יִכּוֹן. אֶלָּא בְּשַׁעֲתָא דְּהוּא אַתְקִין גַּרְמֵיהּ לְהַאי, וְלִבֵּיהּ רְחִיקָא מִּקוּדְשָׁא בְּרִיךְ הוּא, קָלָא נָפִיק וְאָמַר, לֹא יִכּוֹן לְנֶגֶד עֵינָי. (אמאי) הַאי בָּעֵי לְאַתְקְנָא גַּרְמֵיהּ, לֹא יִכּוֹן, לָא בָּעֵינָא דְּיִתְתָּקַּן. כָּל שֶׁכֵּן אִי אָתֵי לְיַחֲדָא שְׁמָא קַדִּישָׁא, וְלָא מְיָחֵד לֵיהּ כְּדְקָא יֵאוֹת.","זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, עָלַיְיהוּ כְּתִיב (ישעיהו ס״ו:י״ח) וּבָאוּ וְרָאוּ אֶת כְבוֹדִי וְגוֹ'. וּכְתִיב, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ וְגוֹ'. אָתָא רִבִּי אֶלְעָזָר וְנָשִׁיק יְדוֹי. אָמַר, אִלְמָלֵא לָא אֲתֵינָא לְעָלְמָא אֶלָּא לְמִשְׁמַע מִלִּין אִלֵּין דַּיָי. אָמַר רִבִּי יְהוּדָה, זַכָּאָה חוּלָקָנָא, וְזַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּאִינּוּן מִתְדַּבְּקִין בְּקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים וְגוֹ'. (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן"],[[0,"ויחזי בר נש","וכו': ויראה אדם את עצמו כאלו נפטר מן העולם, כי מסר נפשו למקום ההוא של מות. משום זה אין \u0003ו'\u0004 בסדר א\"ב של אליך ה' נפשי אשא, כי \u0003ו'\u0004 הוא עץ החיים, דהיינו ז\"א שה\"ס ו' דהויה, וזה, שמסר לו נפשו הוא אילן המות, דהיינו מלכות. וזה שמלמדנו, כי סוד הדבר הוא, שיש עונות שאינם מתכפרים עד שאדם נפטר מן העולם. ז\"ש אם יכופר לכם העון הזה עד תמותון וע\"כ נותן זה את עצמו ודאי למיתה ומוסר נפשו לאותו מקום, למלכות, לא בפקדון כמו בלילה, אלא כמי שנפטר מן העולם ודאי."],[1,"ותקונא דא בעי","וכו': ותקון זה צריך להיות בכוונת הלב, ואז הקב\"ה מרחם עליו ומכפר עונותיו. אשרי האדם היודע לפתות ולעבוד אדונו ברצון וכוונת הלב. אוי לו למי שבא לפתות רבונו בלב רחוק ולא ברצון. כש\"א ויפתוהו בפיהם ובלשונם יכזבו לו ולבם לא נכון עמו. הוא אומר, אליך ה' נפשי אשא, וכל דבריו אינם אלא בלב רחוק. וזה גורם לו להסתלק מן העולם לפני זמנו, בזמן שאילן הזה מתעורר בעולם לעשות דין."],[2,"ועל דא בעי","וכו': וע\"כ צריך האדם להדביק נפשו ורצונו באדונו, ולא יבא אליו ברצון שקר. משום שכתוב, דובר שקרים לא יכון לנגד עיני, מהו לא יכון. ומשיב, אלא בשעה שמתקן עצמו לזה, למסירת נפש בנפילת אפים, ולבו רחוק מהקב\"ה, יוצא קול ואומר לא יכון לנגד עיני. זה רוצה לתקן את עצמו, לא יכון, איני רוצה שיתתקן. כל שכן אם בא ליחד השם הקדוש, ואינו מיחדו כראוי."],[3,"זכאה חולקהון","וכו': אשרי חלקם של הצדיקים בעולם הזה ובעולם הבא. עליהם כתוב, ובאו וראו את כבודי וגו'. וכתוב, אך צדיקים יודו לשמך וגו'. בא ר' אלעזר ונשק ידיו. אמר אם לא באתי לעולם אלא לשמוע דברים אלו די. א\"ר יהודה, אשרי חלקנו ואשרי חלקם של ישראל, שהם מתדבקים בהקב\"ה, שכתוב, ואתם הדבקים וגו'. ועמך כולם צדיקים וגו'. ברוך ה' לעולם אמן ואמן. ימלוך ה' לעולם אמן ואמן."]],[[0,"","וְיִרְאֶה אָדָם עַצְמוֹ כְּאִלּוּ נִפְטַר מֵהָעוֹלָם, שֶׁנַּפְשׁוֹ מָסַר לִמְקוֹם הַמָּוֶת הַזֶּה, מִשּׁוּם כָּךְ אֵין בּוֹ וָא\"ו, שֶׁוָּא\"ו עֵץ הַחַיִּים הוּא, וְזֶה עֵץ הַמָּוֶת הוּא. וְזֶה בָּא לְהַשְׁמִיעֵנוּ, שֶׁסּוֹד הַדָּבָר (מה בא להשמיענו סוד הדבר) - שֶׁיֵּשׁ חֲטָאִים שֶׁלֹּא מִתְכַּפְּרִים עַד שֶׁנִּפְטָר הָאָדָם מֵהָעוֹלָם, זֶהוּ שֶׁכָּתוּב (ישעיהכב) אִם יְכֻפַּר הֶעָון הַזֶּה לָכֶם עַד תְּמֻתוּן. וְזֶה נָתַן עַצְמוֹ וַדַּאי לָמוּת וּמָסַר נַפְשׁוֹ לְמָקוֹם זֶה, לֹא בְּפִקָּדוֹן כְּמוֹ בַּלַּיְלָה, אֶלָּא כְּמִי שֶׁנִּפְטָר מֵהָעוֹלָם וַדַּאי."],[1,"","וְתִקּוּן זֶה צָרִיךְ בְּכַוָּנַת הַלֵּב, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מְרַחֵם עָלָיו וּמְכַפֵּר לוֹ עַל חֲטָאָיו. אַשְׁרֵי הָאִישׁ שֶׁיּוֹדֵעַ לְפַתּוֹתוֹ וְלַעֲבֹד לְרִבּוֹנוֹ בְּרָצוֹן וּבְכַוָּנַת הַלֵּב. אוֹי לְמִי שֶׁבָּא לְפַתּוֹת לְרִבּוֹנוֹ בְּלֵב רָחוֹק, וְלֹא בְרָצוֹן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים עח) וַיְפַתּוּהוּ בְּפִיהֶם וּבִלְשׁוֹנָם יְכַזְּבוֹ לוֹ וְלִבָּם לֹא נָכוֹן עִמּוֹ. הוּא אוֹמֵר (שם כה) אֵלֶיךְ ה' נַפְשִׁי אֶשָּׂא, וְלֹא כָּל דְּבָרָיו, אֶלָּא בְּלֵב רָחוֹק, זֶה גּוֹרֵם עָלָיו לְהִסְתַּלֵּק מֵהָעוֹלָם טֶרֶם שֶׁלֹּא הִגִּיעוּ יָמָיו, בִּזְמַן שֶׁאִילָן זֶה מִתִעוֹרֵר בָּעוֹלָם לַעֲשׂוֹת דִּין."],[2,"","וְלָכֵןֹ צָרִיךְ אָדָם לְהַדְבִּיק נַפְשׁוֹ וּרְצוֹנוֹ בְּרִבּוֹנוֹ, וְלֹא יָבא אֵלָיו בְּרָצוֹן כּוֹזֵב, מִשּׁוּם שֶׁכָּתוּב (שם קא) דֹּבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עֵינָי. מַה זֶּה לֹא יִכּוֹן? בְּשָׁעָה שֶׁהוּא מַתְקִין עַצְמוֹ לָזֶה וְלִבּוֹ רָחַק מִן הַקָּדוֹשׁ בָּרוּךְ הוּא, קוֹל יוֹצֵא וְאוֹמֵר: לֹא יִכּוֹן לְנֶגֶד עֵינָי. (למה) זֶה צָרִיךְ לְתַקֵּן אֶת עַצְמוֹ, לֹא יִכּוֹן, אֵינוֹ רוֹצֶה שֶׁיִּתְתַּקֵּן. כָּל שֶׁכֵּן אִם הוּא בָּא לְיַחֵד שֵׁם הַקָּדוֹשׁ וְלֹא מְיַחֲדוֹ כָּרָאוּי."],[3,"","אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (ישעיה סו) וּבָאוּ וְרָאוּ אֶת כְּבוֹדִי וְגוֹ'. וְכָתוּב (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ וְגוֹ'. בָּא רַבִּי אֶלְעָזָר וְנָשַׁק יָדוֹ וְאָמַר, אִלְמָלֵא לֹא בָאתִי לָעוֹלָם רַק לִשְׁמֹעַ דְּבָרִים אֵלּוּ - דַּי לִי. אָמַר רַבִּי יְהוּדָה, אַשְׁרֵי חֶלְקִי וְאַשְׁרֵי חֵלֶק יִשְׂרָאֵל, שֶׁנִּדְבָּקִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁכָּתוּב (דברים ד) וְאַתֶּם הַדְּבֵקִים וְגוֹ'. (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. בָּרוּךָ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן"]]]]};
